    pub fn title(&self) -> String {
        format!("{APP_NAME} – {}", self.active_panel().path.display())
    }

    pub fn theme(&self) -> Theme {
        theme::app_theme()
    }

    pub fn subscription(&self) -> Subscription<Message> {
        // `listen` yields the event stream, so the mapping can decide
        // without routing every key through a message first.
        //
        // The routing state is read through a shared cell, deliberately *not*
        // carried in the stream by `with`. `with` folds its value into the
        // subscription's hash, and iced's tracker drops any subscription whose
        // hash changes: every keystroke that opened a prompt, started a job or
        // raised a conflict killed the keyboard subscription and spawned a
        // fresh one, so the keys pressed around that moment went to a stream
        // nobody was listening to. That is why the app looked alive and then
        // ignored the keyboard, and why no test caught it — the routing itself
        // was correct.
        //
        // A cell instead: the hash stays constant, so this subscription lives
        // as long as the window does, and it reads the current state on every
        // key rather than a copy from when it was built.
        let key_state = Arc::clone(
            self.key_state
                .get_or_init(|| Arc::new(KeyStateCell(Mutex::new(self.prompt_key_state())))),
        );

        Subscription::batch([
            // `with` is unavoidable: iced requires the `filter_map` closure to
            // capture nothing, so the cell has to travel as the subscription's
            // value. What matters is *which* value. The old code carried the
            // `PromptKeyState` itself, so the hash tracked the state and
            // changed on every message; iced's tracker drops a subscription
            // whose hash changes, which killed the keyboard stream at exactly
            // the moments the app got busy — the keys pressed right after
            // opening a prompt or starting a copy went nowhere. That is why
            // the app looked alive and then ignored the keyboard.
            //
            // Carrying the cell instead gives a hash that is fixed for the
            // life of the app: the same `Arc`, hashed by its contents, which
            // never change. The stream survives every state change and reads
            // the current state on each key.
            keyboard::listen()
                .with(key_state)
                .filter_map(|(cell, event)| {
                    match event {
                        keyboard::Event::KeyPressed {
                            key,
                            physical_key,
                            modifiers,
                            repeat,
                            ..
                        } => route_press(
                            // A panic in a key handler would leave the lock
                            // poisoned. The state is a few Copy values and cannot
                            // be half-written, so reading the inner value is safe —
                            // and it keeps one panic from silencing every key
                            // afterwards.
                            &cell
                                .0
                                .lock()
                                .unwrap_or_else(|poisoned| poisoned.into_inner()),
                            key,
                            physical_key,
                            modifiers,
                            repeat,
                        ),
                        keyboard::Event::ModifiersChanged(modifiers) => {
                            Some(Message::ModifiersChanged(modifiers))
                        }
                        _ => None,
                    }
                }),
            // Keeps the status bar's progress and the open page current.
            if self.pipeline.is_some()
                || self.filing_status.page_open()
                || self.hermes_overview.is_some()
            {
                iced::time::every(SNAPSHOT_EVERY)
                    .map(|_| Message::FilingStatus(FilingStatusMessage::Tick))
            } else {
                Subscription::none()
            },
            // The bar of a running model download reads a counter the download
            // thread fills; nothing else wakes the view.
            if self.hermes_flow_is_visible() {
                iced::time::every(hermes_flow::STEP_INTERVAL).map(|_| Message::HermesFlowTick)
            } else {
                Subscription::none()
            },
            if self.ai_model_download_runs() {
                iced::time::every(DOWNLOAD_BAR_EVERY)
                    .map(|_| Message::AiModel(AiModelMessage::Progress))
            } else {
                Subscription::none()
            },
            if self.ocr_models_download_runs() {
                iced::time::every(DOWNLOAD_BAR_EVERY)
                    .map(|_| Message::OcrModels(OcrModelsMessage::Progress))
            } else {
                Subscription::none()
            },
            // Mouse, focus and modifier events of every status: widgets capture
            // the clicks and the pointer moves the menu has to know about.
            event::listen_with(|event, status, _window| Some((event, status)))
                .with(Arc::clone(&self.input))
                .filter_map(|(input, (event, status))| input.lock().handle(&event, status)),
            window::resize_events().map(|(_id, size)| Message::WindowResized(size)),
            window::events().filter_map(|(_id, event)| match event {
                window::Event::Focused => Some(Message::WindowFocused),
                window::Event::FileHovered(_) => Some(Message::FilesHovered),
                window::Event::FilesHoveredLeft => Some(Message::FilesHoverLeft),
                window::Event::FileDropped(path) => Some(Message::FileDropped(path)),
                _ => None,
            }),
            // The close button and Alt+F4 end the app through Quit, which saves
            // the session first; the window does not close by itself.
            window::close_requests().map(|_id| Message::Quit),
            native_menu_events(),
            // The transfer's ticks. Taken out of the app because a subscription
            // outlives `&self`; the receiver is taken so the subscription
            // rebuilds itself when a new transfer starts.
            // The transfer's ticks. The receiver lives in an Arc because a
            // mpsc Receiver is neither Clone nor Hash, and run_with needs the
            // data to be both: the Arc for Clone, the newtype for Hash.
            match &self.progress_rx {
                None => Subscription::none(),
                Some(shared) => {
                    let rx = Arc::clone(shared);
                    struct ProgressStream(
                        Arc<tokio::sync::Mutex<mpsc::UnboundedReceiver<fs::transfer::Tick>>>,
                    );
                    impl std::hash::Hash for ProgressStream {
                        fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
                            "ncrs-progress".hash(state);
                        }
                    }
                    // The stream yields ticks; the app speaks messages, so
                    // the mapping happens here rather than in the app.
                    Subscription::run_with(ProgressStream(rx), |p: &ProgressStream| {
                        futures::StreamExt::map(
                            receiver_stream(Arc::clone(&p.0)),
                            Message::JobProgress,
                        )
                    })
                }
            },
        ])
    }

    // -----------------------------------------------------------------------
    // Update
    // -----------------------------------------------------------------------

    pub fn update(&mut self, message: Message) -> Task<Message> {
        let task = self.update_message(message);
        let back = self.return_to_overview_when_its_card_is_gone();
        Task::batch([task, back])
    }

    fn return_to_overview_when_its_card_is_gone(&mut self) -> Task<Message> {
        if !self.return_to_hermes_overview
            || self.filing_setup.is_some()
            || self.hermes_setup.is_some()
            || self.filing.as_ref().is_some_and(FilingModule::has_card)
        {
            return Task::none();
        }
        self.return_to_hermes_overview = false;
        self.open_hermes_overview()
    }

    fn update_message(&mut self, message: Message) -> Task<Message> {
        if let Message::Panel(panel_message) = &message {
            if panel_message.resets_type_ahead() {
                self.panels.type_ahead.reset();
            }
        }
        if let Message::NoticeExpired(generation) = message {
            if generation == self.notice_generation {
                self.notice = None;
            }
            return Task::none();
        }
        if leaves_bar_fields(&message) {
            self.set_path_field(None);
            self.command_line.leave();
        }
        if let Message::SaveSessionState(generation) = message {
            return match self.due_session_state(generation) {
                Some((path, state)) => {
                    let order = Arc::clone(&self.session_writes);
                    Task::future(async move {
                        // A failed write was already reported to stderr.
                        drop(
                            tokio::task::spawn_blocking(move || {
                                write_session_state(&order, generation, &path, &state);
                            })
                            .await,
                        );
                    })
                    .discard()
                }
                None => Task::none(),
            };
        }
        let had_search_keys = self.search_has_keys();
        let applied = self.apply_unless_refused(message);
        let task = Task::batch([
            applied,
            self.request_hermes_column(),
            self.schedule_session_save(),
        ]);
        // A dialog that opens while a line is being typed gets the keys, not the field.
        if self.command_line.is_focused() && self.command_line_is_blocked() {
            self.command_line.leave();
            self.publish_key_state();
            return Task::batch([task, release_focus()]);
        }
        // The text field keeps typing into the query until it is told to let
        // go, so leaving the search's panel releases it.
        if had_search_keys && !self.search_has_keys() {
            return Task::batch([task, release_focus()]);
        }
        task
    }

    fn apply(&mut self, message: Message) -> Task<Message> {
        let task = match message {
            // A raw key press. Routed here rather than in the subscription,
            // because that one cannot see whether a prompt is open.
            // --- copy / move ---
            Message::Transfer(kind) => self.open_transfer_dialog(kind),
            Message::TransferDialog(dialog_message) => self.update_transfer_dialog(dialog_message),

            Message::ModifiersChanged(modifiers) => {
                self.modifiers = modifiers;
                Task::none()
            }
            Message::DialogFocus(step) => {
                let buttons = self.dialog_button_count();
                if buttons > 0 {
                    // `buttons` is 2 or 3 and `step` is -1 or 1.
                    self.dialog_focus =
                        (self.dialog_focus + buttons).wrapping_add_signed(step) % buttons;
                }
                Task::none()
            }
            Message::DialogActivate => self.activate_dialog_button(),
            Message::ToggleConflictAll => {
                self.conflict_all = !self.conflict_all;
                Task::none()
            }

            // The user answered a conflict. The queue's pending job carries
            // what was asked, so the answer lands on the right file.
            Message::TransferConflict(choice) => self.answer_conflict(choice),

            // A tick from the copy on the blocking thread. The only thing the
            // status bar needs, and nothing more.
            Message::JobProgress(tick) => {
                self.job_progress = Some(tick);
                Task::none()
            }

            Message::DismissConfigError => {
                self.config_error = None;
                self.config_problem = None;
                Task::none()
            }

            // Stop the running job. The abort key (Ctrl+C on a Mac unless
            // rebound) and Escape both, because a long copy that cannot be
            // stopped is the case a queue was supposed to fix.
            //
            // A delete in flight finishes its current entry even so: it runs in
            // `spawn_blocking`, which cannot be cancelled, so the panel may
            // still list that entry for a moment after the abort.
            Message::AbortJob => self.abort_job(),
            Message::Trash(trash_message) => self.update_trash(trash_message),
            Message::HitList(hit_message) => self.update_hit_list(hit_message),

            // One row of a transfer finished. Continue with the next, or ask
            // about a name that is in the way.
            Message::TransferRowDone {
                result,
                index,
                generation,
            } => {
                if generation != self.generation {
                    return Task::none();
                }
                self.jobs.finish();
                self.job_done += 1;
                let Some(transfer) = self.transfer.clone() else {
                    return Task::none();
                };
                match result {
                    // A remembered "all" answer applies to the rows after this
                    // one, without asking again.
                    Ok(done) => {
                        self.transfer_rows_done = index + 1;
                        let rule = self.conflict_rule.unwrap_or(fs::transfer::OnConflict::Fail);
                        self.run_from(done, index + 1, rule)
                    }
                    // A name that is taken is the one the user can answer.
                    // Matched on the error kind, not on the message text: a
                    // wording change in the filesystem layer would otherwise
                    // silently turn every conflict into a hard failure.
                    // The dialog names the file itself, so the reason travels
                    // no further; it stays in the payload for the status line.
                    Err(RowFailure::Conflict(_reason)) => {
                        self.dialog_focus = conflict::OVERWRITE_FOCUS;
                        self.pending_conflict = Some(PendingConflict { transfer, index });
                        // Else the dialog would be asked behind the box.
                        Task::batch([self.close_quick_open(), self.close_command_palette()])
                    }
                    // Rows before this one are already done, so the panels are
                    // reloaded to show them.
                    Err(RowFailure::Refused(refusal)) => {
                        let text = self.lang.text(match refusal {
                            fs::archive::SevenZipRefusal::Encrypted => Msg::ErrorArchiveEncrypted,
                            fs::archive::SevenZipRefusal::DictionaryTooLarge => {
                                Msg::ErrorArchiveDictionaryTooLarge
                            }
                        });
                        self.set_status_error(text);
                        self.end_transfer()
                    }
                    Err(RowFailure::UnsafeName(name)) => {
                        let text = fill_template(
                            self.lang.text(Msg::ErrorRemoteUnsafeName),
                            &[("{name}", &name)],
                        );
                        self.set_status_error(&text);
                        self.end_transfer()
                    }
                    Err(RowFailure::Other(reason)) => {
                        self.set_status_error(&reason);
                        self.end_transfer()
                    }
                }
            }

            Message::OpenExternal(kind) => self.open_external(kind),

            Message::ViewExtracted {
                generation,
                slot,
                result,
            } => self.view_extracted(generation, slot, result),

            #[cfg(target_os = "macos")]
            Message::OpenPrivacySettings => {
                self.open_privacy_settings();
                Task::none()
            }

            // --- drive menu ---
            Message::VolumeMenu(side) => {
                self.open_volume_menu(side);
                Task::none()
            }
            Message::VolumeMenuMove(delta) => {
                if let Some(menu) = self.volume_menu.as_mut() {
                    menu.move_by(delta);
                }
                Task::none()
            }
            Message::VolumeMenuFirst => {
                if let Some(menu) = self.volume_menu.as_mut() {
                    menu.selected = 0;
                }
                Task::none()
            }
            Message::VolumeMenuLast => {
                if let Some(menu) = self.volume_menu.as_mut() {
                    menu.selected = menu.last_row();
                }
                Task::none()
            }
            Message::VolumeMenuRemove => self.remove_highlighted_row(),
            Message::AddFavourite => self.add_favourite(),
            Message::RemoveFavourite => self.remove_favourite(),
            Message::OpenFavourites => self.open_favourites(),
            Message::VolumeMenuActivate => self.go_to_selected_volume(),
            Message::VolumeMenuClick(index) => {
                if let Some(menu) = self.volume_menu.as_mut() {
                    menu.selected = index;
                }
                self.go_to_selected_volume()
            }
            Message::VolumeMenuClose => {
                self.volume_menu = None;
                Task::none()
            }

            // --- context menu ---
            menu_message @ (Message::ContextMenuAt { .. }
            | Message::ContextMenuKey
            | Message::ContextMenuMove(_)
            | Message::ContextMenuFirst
            | Message::ContextMenuLast
            | Message::ContextMenuHover(_)
            | Message::ContextMenuActivate
            | Message::ContextMenuClick(_)
            | Message::ContextMenuOpenSub
            | Message::ContextMenuCloseSub
            | Message::ContextMenuSubHover(_)
            | Message::ContextMenuSubClick(_)
            | Message::ContextMenuClose) => self.update_context_menu(menu_message),

            Message::HermesFile(file_message) => self.update_hermes_file(file_message),

            Message::QuickFix(fix_message) => self.update_quick_fix(fix_message),

            // --- path field ---
            path_message @ (Message::PathFieldInput(_)
            | Message::PathFieldSubmit
            | Message::PathFieldCancel
            | Message::PathChecked { .. }
            | Message::ClickedOutside) => self.update_path_field(path_message),

            Message::CommandLine(line_message) => self.update_command_line(line_message),

            // --- delete ---
            Message::Delete { permanent } => self.open_delete_dialog(permanent),
            Message::CopyToClipboard(kind) => self.copy_to_clipboard(kind),
            Message::Paste => self.paste_from_clipboard(),
            Message::ClipboardRead(content) => self.paste_content(content),
            Message::CopyFilesToClipboard => self.copy_files_to_clipboard(),
            Message::DeleteCancel => {
                self.delete_dialog = None;
                Task::none()
            }
            Message::DeleteConfirm => self.confirm_delete(),
            Message::DeleteRowDone {
                result,
                index,
                generation,
            } => {
                if generation != self.generation {
                    return Task::none();
                }
                self.jobs.finish();
                match result {
                    Ok(()) => {
                        self.remember_trashed(index);
                        self.run_delete_row(index + 1)
                    }
                    Err(reason) => {
                        let text = self.delete_failure(index, &reason);
                        self.set_status_error(&text);
                        self.end_delete()
                    }
                }
            }

            // --- job queue ---
            Message::JobFinished(event) => {
                // Progress arrives mid-run; only the terminal events free the
                // slot for the next job.
                let finished = matches!(event, JobEvent::Done);
                if finished {
                    self.jobs.finish();
                }
                if let Some(next) = self.jobs.start_next(run_job) {
                    return next;
                }
                Task::none()
            }

            // --- modal prompt ---
            // Handled before the panels: while a prompt is open every
            // keystroke belongs to it, and Enter must not open a directory.
            Message::CreateDirPrompt => {
                let parent = self.active_panel().path.clone();
                self.open_prompt(Prompt::create_dir(parent))
            }
            Message::CreateFilePrompt => {
                let parent = self.active_panel().path.clone();
                self.open_prompt(Prompt::create_file(parent))
            }
            Message::PackPrompt => self.open_pack_prompt(),
            Message::ArchiveWritten { result, generation } => {
                self.archive_written(generation, result)
            }
            Message::PromptInput(text) => {
                if let Some(prompt) = self.prompt.as_mut() {
                    prompt.set_name(text);
                }
                Task::none()
            }
            Message::PromptToggleKeepFolders => self.toggle_keep_folders(),
            // Its own arm, not an early return: starting the job changes what the
            // keys mean, and the routing state is published after the match.
            Message::PromptSubmit if self.valid_prompt_has_its_own_job() => self.start_prompt_job(),
            Message::PromptSubmit => {
                let Some(prompt) = self.prompt.as_ref() else {
                    return Task::none();
                };
                if let Err(reason) = prompt.validate() {
                    self.set_prompt_error(reason);
                    return Task::none();
                }
                let kind = prompt.kind();
                let side = self.prompt_side.unwrap_or(self.panels.active);
                let parent = self.panel(side).path.clone();
                let new_name = prompt.name().trim().to_string();
                let request_id = self.prompt_request_id.wrapping_add(1);
                self.prompt_request_id = request_id;
                self.set_prompt_busy(true);

                // The new entry's name, carried through the task so the
                // reload can select it.
                let target = parent.join(&new_name);
                let finished = move |result| Message::PromptFinished {
                    prompt: kind,
                    request_id,
                    result,
                };
                let create = match kind {
                    PromptKind::CreateDir => Task::perform(fs::create_dir(target), finished),
                    PromptKind::CreateFile => Task::perform(fs::create_file(target), finished),
                    // Taken out above: a pack and a paste have their own jobs.
                    PromptKind::Pack | PromptKind::Paste => Task::none(),
                };

                // The reload belongs *after* the create, not beside it.
                // Running both at once races: a read that finishes first sees a
                // directory that does not contain the new entry yet, and the
                // selection then points at whatever is there instead.
                self.pending_reload = Some(PendingReload {
                    side,
                    name: new_name,
                });
                create
            }
            Message::PromptCancel => {
                self.prompt = None;
                self.pending_paste = None;
                self.prompt_side = None;
                Task::none()
            }
            Message::PromptFinished {
                prompt: kind,
                request_id,
                result,
            } => self.finish_prompt(kind, request_id, result),

            Message::Panel(panel_message) => self.update_panel(panel_message),
            Message::TitleBar(title_bar) => update_title_bar(title_bar),
            Message::ComputeFolderSizes => self.compute_folder_sizes(),
            Message::FolderSizeMeasured { run, folder, size } => {
                self.folder_size_measured(run, folder, size)
            }
            Message::SwitchLanguage => {
                self.switch_language();
                Task::none()
            }
            #[cfg(any(target_os = "macos", target_os = "windows"))]
            Message::DragOutStarted(started) => self.drag_out_started(started),

            Message::WindowResized(size) => {
                self.apply_window_size(size);
                Task::none()
            }
            Message::WindowFocused => self.reload_local_panels(),
            Message::FilesHovered => {
                self.drop_hover = true;
                Task::none()
            }
            Message::FilesHoverLeft => {
                self.drop_hover = false;
                Task::none()
            }
            Message::FileDropped(path) => self.queue_dropped_file(path),
            Message::DropSettled(generation) => self.copy_settled_drop(generation),
            Message::OpenSearch => self.open_search(),
            Message::Search(search) => self.update_search(search),
            Message::QuickOpen(quick_open) => self.update_quick_open(quick_open),
            Message::CommandPalette(command_palette) => {
                self.update_command_palette(command_palette)
            }
            Message::KeyBindings(shortcuts) => self.update_key_bindings(shortcuts),
            Message::ThemeFetch(fetch_message) => self.update_theme_fetch(fetch_message),
            Message::RuleSuggestions(suggestions) => self.update_rule_suggestions(suggestions),
            Message::Rules(rules) => self.update_rules(rules),
            Message::ReviewList(review) => {
                let update = self.update_review_list(review);
                Task::batch([update, self.request_review_preview()])
            }
            Message::SavedQueries(queries) => self.update_saved_queries(queries),
            Message::Tags(tags) => self.update_tags(tags),
            Message::HermesPage(page) => self.show_hermes_page(page),
            Message::HermesFocus(focus) => self.focus_hermes(focus),
            Message::HermesStep(step) => self.step_hermes_page(step),
            Message::ReorganisationPlan(plan) => self.update_reorganisation(plan),
            // #73 hangs the executor here; until then the selection goes nowhere.
            Message::ExecuteReorganisation(selection) => self.run_reorganisation(selection),
            Message::ReorganisationExecuted(result) => self.reorganisation_executed(result),
            Message::UndoReorganisation => self.undo_reorganisation(),
            Message::DocumentsFiled(result) => self.documents_filed(result),
            Message::DocumentsRefiled(result) => self.documents_refiled(result),
            Message::ReorganisationUndone(result) => self.reorganisation_undone(result),
            Message::About(about_message) => self.update_about(about_message),
            Message::OcrModels(models_message) => self.update_ocr_models(models_message),
            Message::AiModel(model_message) => self.update_ai_model(model_message),
            Message::Grant(grant_message) => self.update_grant(grant_message),
            Message::Remote(remote_message) => self.update_remote(remote_message),
            Message::Settings(settings_message) => self.update_settings(settings_message),
            Message::Filing(filing_message) => self.update_filing(filing_message),
            Message::FilingStatus(page_message) => self.update_filing_status(page_message),
            Message::HermesColumn(column_message) => self.update_hermes_column(column_message),
            Message::FilingSetup(setup_message) => self.update_filing_setup(setup_message),
            Message::HermesSetup(setup_message) => self.update_hermes_setup(setup_message),
            Message::HermesOverview(overview_message) => {
                self.update_hermes_overview(overview_message)
            }
            Message::HermesFlowTick => {
                self.hermes_flow_step = self.hermes_flow_step.wrapping_add(1);
                Task::none()
            }
            #[cfg(any(target_os = "macos", test))]
            Message::RunCommand(action) => self.run_command(action),
            #[cfg(target_os = "macos")]
            Message::InstallNativeMenu => {
                native_menu::install(self.lang, &self.keymap, self.menu_availability());
                Task::none()
            }
            Message::Quit => self.quit(),
            // Handled in `update`, which owns the timer's generation check.
            Message::NoticeExpired(_) | Message::SaveSessionState(_) => Task::none(),
        };

        // The keyboard subscription cannot see `&self`, so it reads the routing
        // state from a cell this method keeps current.
        //
        // This runs *after* the match, and that ordering is the point. Published
        // before it, the cell would always describe the state from before the
        // message that has just been handled — one step behind — so the keys
        // that follow a conflict would still be routed as panel keys and the
        // dialog could not be answered at all.
        self.publish_key_state();
        #[cfg(target_os = "macos")]
        native_menu::sync(self.lang, &self.keymap, self.menu_availability());
        task
    }

    /// What the menu bar lets the user run: nothing while a dialog or box is
    /// open, otherwise what works in the area the keys go to.
    #[cfg(any(target_os = "macos", test))]
    fn menu_availability(&self) -> Availability {
        if self.overlay_is_open() {
            Availability::Blocked
        } else if self.search_has_keys() {
            Availability::Open(KeyScope::Search)
        } else {
            Availability::Open(KeyScope::Panel)
        }
    }

    /// A reload of the same folder keeps the run; another folder ends it.
    fn stop_folder_size_run_if_left(&mut self, side: PanelSide) {
        let left = self
            .folder_size_run
            .as_ref()
            .is_some_and(|run| run.side == side && self.panel(side).path != run.directory);
        if left {
            self.stop_folder_size_run();
        }
    }

    fn stop_folder_size_run(&mut self) {
        if let Some(run) = self.folder_size_run.take() {
            run.stop.store(true, std::sync::atomic::Ordering::Relaxed);
        }
    }

    fn compute_folder_sizes(&mut self) -> Task<Message> {
        let targets = folder_size_targets(self.active_panel());
        if targets.is_empty() {
            return Task::none();
        }
        self.stop_folder_size_run();
        self.folder_size_runs_started += 1;
        self.folder_size_run = Some(FolderSizeRun {
            id: self.folder_size_runs_started,
            side: self.panels.active,
            directory: self.active_panel().path.clone(),
            waiting: targets.into(),
            stop: Arc::new(AtomicBool::new(false)),
        });
        self.next_folder_size_walk()
    }

    /// Starts the walk of the next waiting folder; the run is over when none is
    /// left.
    fn next_folder_size_walk(&mut self) -> Task<Message> {
        let Some(run) = self.folder_size_run.as_mut() else {
            return Task::none();
        };
        let Some(folder) = run.waiting.pop_front() else {
            self.folder_size_run = None;
            return Task::none();
        };
        let (id, stop) = (run.id, Arc::clone(&run.stop));
        let walked = folder.clone();
        Task::perform(
            tokio::task::spawn_blocking(move || fs::measure_folder(&walked, &stop)),
            move |done| Message::FolderSizeMeasured {
                run: id,
                folder: folder.clone(),
                size: done.ok().flatten(),
            },
        )
    }

    fn folder_size_measured(
        &mut self,
        run: u64,
        folder: PathBuf,
        measured: Option<fs::FolderSize>,
    ) -> Task<Message> {
        if self.folder_size_run.as_ref().map(|current| current.id) != Some(run) {
            return Task::none();
        }
        if let (Some(size), Some(parent), Some(name)) =
            (measured, folder.parent(), folder.file_name())
        {
            self.folder_sizes
                .entry(parent.to_path_buf())
                .or_default()
                .insert(name.to_owned(), size);
            let rows = self.visible_rows;
            for side in [PanelSide::Left, PanelSide::Right] {
                let panel = self.panel_mut(side);
                if panel.path != parent || panel.is_virtual() {
                    continue;
                }
                let Some(entry) = panel
                    .entries
                    .iter_mut()
                    .find(|entry| entry.is_dir && entry.name == name)
                else {
                    continue;
                };
                entry.folder_size = Some(size);
                if panel.sort.column == fs::SortColumn::Size {
                    panel.resort(rows);
                }
            }
        }
        self.next_folder_size_walk()
    }

    fn update_quick_fix(&mut self, message: QuickFixMessage) -> Task<Message> {
        match message {
            QuickFixMessage::Open => self.open_quick_fix(),
            QuickFixMessage::Close => {
                self.quick_fix = None;
                Task::none()
            }
            QuickFixMessage::Loaded { generation, result } => {
                self.quick_fix_loaded(generation, result)
            }
            QuickFixMessage::Move(delta) => self.with_quick_fix(|menu| menu.move_by(delta)),
            QuickFixMessage::First => self.with_quick_fix(QuickFix::select_first),
            QuickFixMessage::Last => self.with_quick_fix(QuickFix::select_last),
            QuickFixMessage::Hover(index) => self.with_quick_fix(|menu| menu.select(index)),
            QuickFixMessage::Activate => self.run_quick_fix_entry(),
            QuickFixMessage::Click(index) => {
                drop(self.with_quick_fix(|menu| menu.select(index)));
                self.run_quick_fix_entry()
            }
            QuickFixMessage::Filed(summary) => self.quick_fix_filed(&summary),
        }
    }

    fn with_quick_fix(&mut self, change: impl FnOnce(&mut QuickFix)) -> Task<Message> {
        if let Some(menu) = self.quick_fix.as_mut() {
            change(menu);
        }
        Task::none()
    }

    /// The inquiries under the cursor or among the marked files of the active
    /// panel.
    fn inquiry_paths(&self) -> Vec<PathBuf> {
        self.action_sources()
            .into_iter()
            .filter(|path| self.hermes_column.state_of(path) == Some(HermesFileState::Inquiry))
            .collect()
    }

    /// Cmd+.: opens the menu on the inquiries of the active panel, and looks up
    /// their reviews on a blocking thread. Says so when there are none.
    fn open_quick_fix(&mut self) -> Task<Message> {
        if self.overlay_is_open() || self.search.open || !self.hermes_active() {
            return Task::none();
        }
        let paths = self.inquiry_paths();
        let found_access = self.filing.as_ref().and_then(FilingModule::review_access);
        let Some(access) = found_access.filter(|_| !paths.is_empty()) else {
            let text = self.lang.text(Msg::StatusQuickFixNone).to_owned();
            return self.show_notice(text);
        };
        let side = self.panels.active;
        let panel = self.panel(side);
        let anchor = layout::cursor_row_anchor(
            side == PanelSide::Right,
            panel.selected.saturating_sub(panel.scroll_offset),
            panel.row_height(),
            self.window_size,
        );
        self.job_error = None;
        self.notice = None;
        self.quick_fix_generation = self.quick_fix_generation.wrapping_add(1);
        let generation = self.quick_fix_generation;
        self.quick_fix =
            Some(QuickFix::new(anchor, self.window_size).with_kinds(self.kinds.clone()));
        Task::perform(
            tokio::task::spawn_blocking(move || access.items_for(&paths)),
            move |joined| {
                let result = joined.unwrap_or_else(|err| Err(err.to_string()));
                Message::QuickFix(QuickFixMessage::Loaded { generation, result })
            },
        )
    }

    fn quick_fix_loaded(
        &mut self,
        generation: u64,
        result: Result<Vec<ReviewItem>, String>,
    ) -> Task<Message> {
        if generation != self.quick_fix_generation || self.quick_fix.is_none() {
            return Task::none();
        }
        match result {
            Ok(items) if items.is_empty() => {
                self.quick_fix = None;
                let text = self.lang.text(Msg::StatusQuickFixNone).to_owned();
                self.show_notice(text)
            }
            Ok(items) => self.with_quick_fix(|menu| menu.loaded(items)),
            Err(detail) => {
                self.quick_fix = None;
                self.set_status_error(&detail);
                Task::none()
            }
        }
    }

    /// Carries out the highlighted entry. The menu closes first for everything
    /// that opens or files something else.
    fn run_quick_fix_entry(&mut self) -> Task<Message> {
        let Some(menu) = self.quick_fix.as_mut() else {
            return Task::none();
        };
        let Some(action) = menu.selected_action() else {
            return Task::none();
        };
        match action {
            QuickFixAction::Accept(group) if menu.group_items(group).len() > 1 => {
                menu.summarise(group);
                Task::none()
            }
            QuickFixAction::Accept(group) | QuickFixAction::FileGroup(group) => {
                self.file_quick_fix_group(group)
            }
            QuickFixAction::Back => {
                menu.back();
                Task::none()
            }
            QuickFixAction::SetFields => self.open_review_from_quick_fix(),
            QuickFixAction::CreateRule => self.open_rule_form_from_quick_fix(),
            QuickFixAction::Later => {
                self.quick_fix = None;
                Task::none()
            }
            QuickFixAction::Exclude => {
                let paths = menu.paths();
                self.quick_fix = None;
                self.exclude_from_hermes(paths)
            }
        }
    }

    /// Files the documents of a group one after the other, each through the
    /// review's own confirm: never a plain move.
    fn file_quick_fix_group(&mut self, group: usize) -> Task<Message> {
        let Some(menu) = self.quick_fix.take() else {
            return Task::none();
        };
        let items = menu.group_items(group);
        let Some(access) = self.filing.as_ref().and_then(FilingModule::review_access) else {
            self.set_status_error(INDEX_NOT_OPEN);
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.accept(&items)),
            |joined| {
                Message::QuickFix(QuickFixMessage::Filed(joined.unwrap_or_else(|err| {
                    AcceptSummary {
                        failed: 1,
                        first_failure: Some(err.to_string()),
                        ..AcceptSummary::default()
                    }
                })))
            },
        )
    }

    fn quick_fix_filed(&mut self, summary: &AcceptSummary) -> Task<Message> {
        self.hermes_column.invalidate_all();
        self.hermes_reads.clear();
        self.hermes_detail_reads.clear();
        let notice = match accept_notice(summary, self.lang) {
            Some(text) => self.show_notice(text),
            None => {
                let detail = summary.first_failure.clone().unwrap_or_default();
                self.set_status_error(&detail);
                Task::none()
            }
        };
        let tasks = [PanelSide::Left, PanelSide::Right].map(|each| {
            let panel = self.panel(each);
            let path = panel.path.clone();
            let cursor = panel
                .selected_entry()
                .map(|entry| entry.name.to_string_lossy().into_owned());
            self.load(each, path, cursor)
        });
        Task::batch(tasks.into_iter().chain([notice]))
    }

    /// Opens the review page on the document of the menu with its form open,
    /// to fill in the missing field.
    fn open_review_from_quick_fix(&mut self) -> Task<Message> {
        let Some(menu) = self.quick_fix.take() else {
            return Task::none();
        };
        let Some(item) = menu.item_to_fix() else {
            return Task::none();
        };
        let field = field_to_fix(item);
        let path = item.path.clone();
        let opened = self.open_review_list();
        if let Some(view) = self.review_list.as_mut() {
            view.edit_on_load(path, field);
        }
        opened
    }

    /// Opens the rule form with what the review would file the document of the
    /// menu with.
    fn open_rule_form_from_quick_fix(&mut self) -> Task<Message> {
        let Some(menu) = self.quick_fix.take() else {
            return Task::none();
        };
        let Some(item) = menu.item_to_fix() else {
            return Task::none();
        };
        let prefill = rule_prefill_of(
            item,
            self.filing_config.default_pattern.as_deref(),
            &self.kinds,
        );
        self.open_rule_form(RuleForm::from_document(prefill, &self.kinds), None)
    }

    fn update_context_menu(&mut self, message: Message) -> Task<Message> {
        match message {
            Message::ContextMenuAt { side, index } => {
                let pointer = self.input.lock().pointer;
                self.open_context_menu(side, index, Some(pointer));
                Task::none()
            }
            Message::ContextMenuKey => {
                let side = self.panels.active;
                let index = self.panel(side).selected;
                self.open_context_menu(side, index, None);
                Task::none()
            }
            Message::ContextMenuMove(delta) => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.move_by(delta);
                }
                Task::none()
            }
            Message::ContextMenuFirst => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.select_first();
                }
                Task::none()
            }
            Message::ContextMenuLast => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.select_last();
                }
                Task::none()
            }
            Message::ContextMenuHover(index) => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.hover(index);
                }
                Task::none()
            }
            Message::ContextMenuActivate => self.run_context_menu_entry(),
            Message::ContextMenuClick(index) => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.select(index);
                    if menu.selected_is_hermes() {
                        menu.open_submenu();
                        return Task::none();
                    }
                    menu.close_submenu();
                }
                self.run_context_menu_entry()
            }
            Message::ContextMenuOpenSub => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.open_submenu();
                }
                Task::none()
            }
            Message::ContextMenuCloseSub => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.close_submenu();
                }
                Task::none()
            }
            Message::ContextMenuSubHover(index) => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.select_sub(index);
                }
                Task::none()
            }
            Message::ContextMenuSubClick(index) => {
                if let Some(menu) = self.context_menu.as_mut() {
                    menu.select_sub(index);
                }
                self.run_context_menu_entry()
            }
            Message::ContextMenuClose => {
                self.context_menu = None;
                Task::none()
            }
            _ => Task::none(),
        }
    }

    fn update_path_field(&mut self, message: Message) -> Task<Message> {
        match message {
            Message::PathFieldInput(typed) => {
                self.command_line.leave();
                self.set_path_field(Some(typed));
                Task::none()
            }
            Message::PathFieldSubmit => self.go_to_typed_path(),
            Message::PathChecked {
                request_id,
                side,
                target,
                result,
            } => self.finish_path_check(request_id, side, &target, result),
            Message::PathFieldCancel => {
                self.set_path_field(None);
                release_focus()
            }
            Message::ClickedOutside => {
                self.context_menu = None;
                self.set_path_field(None);
                self.command_line.leave();
                Task::none()
            }
            _ => Task::none(),
        }
    }

    fn update_command_line(&mut self, message: CommandLineMessage) -> Task<Message> {
        let ctx = CommandLineCtx {
            blocked: self.command_line_is_blocked(),
            lang: self.lang,
            remote: self.active_panel().remote().is_some(),
            active_side: self.panels.active,
            active_path: self.active_panel().path.clone(),
            home: &self.home,
            shell_directory: shell_directory(self.active_panel()),
        };
        let (inner, action) = command_line::update(&mut self.command_line, message, &ctx);
        let task = inner.map(Message::CommandLine);
        match action {
            None => task,
            Some(CommandLineAction::ClosePathField) => {
                self.set_path_field(None);
                task
            }
            Some(CommandLineAction::ShowError(text)) => {
                self.set_status_error(&text);
                task
            }
            Some(CommandLineAction::OpenDirectory { side, destination }) => {
                self.job_error = None;
                self.notice = None;
                Task::batch([
                    self.load(side, destination.directory, destination.select),
                    task,
                ])
            }
            Some(CommandLineAction::ShowPathProblem { problem, target }) => {
                let reason = self.path_problem_text(&problem, &target);
                self.set_status_error(&reason);
                task
            }
            Some(CommandLineAction::ShellFinished { report }) => self.finish_shell_command(report),
        }
    }

    /// Settings and the filing setup replace the panel area; an overlay covers it.
    fn command_line_is_blocked(&self) -> bool {
        self.overlay_is_open() || self.settings.is_some() || self.filing_setup.is_some()
    }

    /// A shell command ended: its report goes to the status bar and both panels
    /// are re-read, as the command may have changed what they show.
    fn finish_shell_command(&mut self, report: Result<String, String>) -> Task<Message> {
        let reloads = [PanelSide::Left, PanelSide::Right].map(|each| {
            let path = self.panel(each).path.clone();
            self.load(each, path, None)
        });
        let notice = match report {
            Ok(text) => {
                self.job_error = None;
                self.show_notice(text)
            }
            Err(text) => {
                self.set_status_error(&text);
                Task::none()
            }
        };
        Task::batch(reloads.into_iter().chain([notice]))
    }

    /// The rows the menu was opened on are gone. It acts on the active panel,
    /// so only that panel's reload closes it.
    fn close_menu_of_reloaded(&mut self, side: PanelSide) {
        if side == self.panels.active {
            self.context_menu = None;
        }
    }

    /// Sets what the path field shows, or ends the editing with `None`. Any
    /// change makes an answer still on its way stale.
    fn set_path_field(&mut self, value: Option<String>) {
        self.path_check_id = self.path_check_id.wrapping_add(1);
        self.path_field = value;
    }

    /// Enter in the path field: looks at the typed path on the blocking pool and
    /// opens it in the active panel once the answer is in.
    fn go_to_typed_path(&mut self) -> Task<Message> {
        let Some(raw_path) = self.path_field.clone() else {
            return Task::none();
        };
        let typed = raw_path.trim();
        if typed.is_empty() {
            self.set_path_field(None);
            return release_focus();
        }
        let side = self.panels.active;
        // Before anything that asks the disk: an address, or a path typed
        // while the panel is on a server, is no path of this computer.
        if let Some(opened) = self.open_typed_remote(side, typed) {
            return opened;
        }
        let target = fs::resolve_typed_path(&self.active_panel().path, &self.home, typed);
        self.path_check_id = self.path_check_id.wrapping_add(1);
        let request_id = self.path_check_id;
        Task::perform(fs::locate(target.clone()), move |result| {
            Message::PathChecked {
                request_id,
                side,
                target: target.clone(),
                result,
            }
        })
    }

    /// What typing `typed` into the path field does when it names a server: an
    /// `sftp://` address opens it (or the connect dialog, when the address has
    /// no user), a path typed over a server's folder is read on that server.
    /// `None` for an ordinary path.
    fn open_typed_remote(&mut self, side: PanelSide, typed: &str) -> Option<Task<Message>> {
        let is_address = typed
            .get(..7)
            .is_some_and(|scheme| scheme.eq_ignore_ascii_case("sftp://"));
        let target = if is_address {
            match fs::remote::parse_url(typed) {
                Ok(url) => match url.remote_path() {
                    Some(place) => place,
                    None => {
                        self.set_path_field(None);
                        let opened = self.open_connect_dialog_for(&url);
                        return Some(Task::batch([opened, release_focus()]));
                    }
                },
                Err(_) => {
                    let text = self.lang.text(Msg::ErrorRemoteUrlInvalid).to_owned();
                    self.set_status_error(&text);
                    return Some(Task::none());
                }
            }
        } else {
            let place = RemotePath::parse(&self.active_panel().path)?;
            let home = self
                .remote
                .session(place.server())
                .map_or_else(|| "/".to_owned(), |session| session.home().to_owned());
            place.resolve_typed(typed, &home)
        };
        self.set_path_field(None);
        self.job_error = None;
        self.notice = None;
        Some(Task::batch([
            self.load(side, target.to_path_buf(), None),
            release_focus(),
        ]))
    }

    /// The connect dialog for an address that names no user.
    fn open_connect_dialog_for(&mut self, url: &fs::remote::RemoteUrl) -> Task<Message> {
        if self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.connect_attempts = self.connect_attempts.wrapping_add(1);
        self.connect_dialog = Some(ConnectDialog::for_address(self.connect_attempts, url));
        operation::focus(remote_ui::field_id(ConnectField::User))
    }

    /// The answer to [`Self::go_to_typed_path`]: a destination closes the field
    /// and loads it, a problem is reported and leaves the field open. An answer
    /// to text that has since changed, or to a field that is closed, is dropped.
    fn finish_path_check(
        &mut self,
        request_id: u64,
        side: PanelSide,
        target: &Path,
        result: Result<fs::Destination, fs::PathProblem>,
    ) -> Task<Message> {
        if request_id != self.path_check_id || self.path_field.is_none() {
            return Task::none();
        }
        match result {
            Ok(destination) => {
                self.set_path_field(None);
                self.job_error = None;
                self.notice = None;
                Task::batch([
                    self.load(side, destination.directory, destination.select),
                    release_focus(),
                ])
            }
            Err(problem) => {
                let reason = self.path_problem_text(&problem, target);
                self.set_status_error(&reason);
                Task::none()
            }
        }
    }

    /// Why `target` cannot be opened, for the status bar.
    fn path_problem_text(&self, problem: &fs::PathProblem, target: &Path) -> String {
        let shown = target.display().to_string();
        match problem {
            fs::PathProblem::Missing => fill_template(
                self.lang.text(Msg::StatusPathMissing),
                &[("{path}", &shown)],
            ),
            fs::PathProblem::Unreadable { reason } => fill_template(
                self.lang.text(Msg::StatusPathUnreadable),
                &[("{path}", &shown), ("{reason}", reason)],
            ),
        }
    }

    /// Writes the current routing state into the cell the keyboard reads.
    ///
    /// A no-op before the first `subscription()` call, which is the only time
    /// there is no cell — the subscription creates it.
    fn publish_key_state(&mut self) {
        let state = self.prompt_key_state();
        // An overlay answers Escape itself.
        let search_open = self.search_has_keys() && !self.overlay_is_open();
        let job_running = state.job_running;
        let mut input = self.input.lock();
        input.path_editing = state.path_editing;
        input.command_line = state.command_line;
        input.search_open = search_open;
        input.job_running = job_running;
        input.quick_open = self.quick_open.is_some();
        input.command_palette = self.command_palette.is_some();
        input.key_bindings = self
            .key_bindings
            .as_ref()
            .is_some_and(|shortcuts| !shortcuts.is_recording());
        input.theme_fetch = self.theme_fetch.is_some();
        input.rule_suggestions = self.rule_suggestions.is_some();
        input.rules = self.rules.is_some();
        input.review_list = self.review_list.is_some();
        input.saved_queries = self.saved_queries.is_some();
        input.tags = self.tags.is_some();
        input.hermes_sidebar = state.hermes_sidebar;
        input.transfer_dialog = self.transfer_dialog.is_some();
        input.reorganisation_plan = self.reorganisation.is_some();
        input.settings = self.settings.is_some()
            && self.filing_setup.is_none()
            && !self.blocking_overlay_is_open();
        drop(input);
        // `get` rather than `get_or_init`: the cell is created by the
        // subscription, and `update` must not create it — a cell nothing reads
        // would just be a value nobody sees. Before the first `subscription()`
        // call there is nothing to publish to, and that is fine: no keys have
        // been pressed yet.
        if let Some(cell) = self.key_state.get() {
            *cell
                .0
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner()) = state;
        }
    }

    // -----------------------------------------------------------------------
    // View
    // -----------------------------------------------------------------------

    pub fn view(&self) -> Element<'_, Message> {
        let panel_view = |side: PanelSide| {
            let hermes_cell: Option<ncrs_files::HermesCellOf<'_>> =
                self.hermes_active().then(|| {
                    let column = ColumnView::new(
                        &self.hermes_column,
                        &self.filing_config.locations,
                        self.hermes_spinner_angle,
                        &self.file_list_tags,
                        &self.tag_exceptions,
                        self.window_size.width / 2.0,
                        &self.kinds,
                    );
                    let (lang, palette) = (self.lang, self.palette);
                    Box::new(move |entry: &fs::FileEntry| {
                        panel::hermes_cell_of(entry, column, lang, &palette)
                    }) as ncrs_files::HermesCellOf<'_>
                });
            ncrs_files::view(
                self.panel(side),
                ncrs_files::ViewCtx {
                    side,
                    lang: self.lang,
                    palette: self.palette,
                    is_active: self.panels.active == side,
                    visible_rows: self.visible_rows,
                    hermes_cell,
                },
            )
            .map(Message::Panel)
        };

        let side_view_plain = |side: PanelSide| match self.search.view.as_ref() {
            _ if self.trash_view.is_some() && side == self.trash_side => self.trash_panel(side),
            Some(search) if self.search.open && side == self.search.side => {
                let keymap = &self.keymap;
                ncrs_search::view(
                    search,
                    self.search.rows,
                    ncrs_search::ViewCtx {
                        lang: self.lang,
                        palette: &self.palette,
                        is_active: self.panels.active == side,
                        shortcuts: self.toggle_shortcuts(),
                        toggle_for_press: Rc::new(move |key, physical_key, modifiers| {
                            search_toggle_for_press(keymap, key, physical_key, modifiers)
                        }),
                        column_header: panel::plain_column_header(self.lang, &self.palette),
                    },
                )
                .map(Message::Search)
            }
            _ => panel_view(side),
        };

        let side_view = |side: PanelSide| {
            let plain = side_view_plain(side);
            let view: Element<'_, Message> = if self.is_drop_target(side) {
                Stack::with_children([
                    plain,
                    container(Space::new())
                        .width(Length::Fill)
                        .height(Length::Fill)
                        .style(theme::outlined_in(self.palette.accent))
                        .into(),
                ])
                .into()
            } else {
                plain
            };
            // The cursor goes on a wrapper, not on the overlay: a Stack layer
            // with its own cursor lifts the pointer off the layers below, so
            // the panel would report the pointer as gone and end the hover.
            // The wrapper stays in place without a drag so the panel keeps its
            // widget state when a drag starts.
            let wrapper = mouse_area(view);
            Element::from(match self.drag_cursor(side) {
                Some(interaction) => wrapper.interaction(interaction),
                None => wrapper,
            })
        };

        let panels = row![
            side_view(PanelSide::Left),
            theme::vertical_rule(self.palette.border),
            side_view(PanelSide::Right),
        ]
        .height(Length::Fill);

        let below_title_bar = if let Some(state) = self.settings.as_ref() {
            self.settings_area(state)
        } else if let Some(area) = self.ablage_area() {
            area
        } else {
            container(column![
                panels,
                command_line_ui::view(command_line_ui::Props {
                    prompt: self.active_panel().path.display().to_string(),
                    typed: self.command_line.typed(),
                    focused: self.command_line.is_focused(),
                    focusable: !self.command_line_is_blocked(),
                    running: self.command_line.running(),
                    key_label: self
                        .keymap
                        .shortcut_label(&KeyAction::CommandLine.message()),
                    lang: self.lang,
                    palette: &self.palette,
                })
                .map(Message::CommandLine),
                fkeys::view(&self.function_key_bar(), &self.palette,),
                statusbar::view(
                    self.active_panel(),
                    self.lang,
                    &self.palette,
                    statusbar::Activity {
                        side: self.panels.active,
                        theme_name: self.theme_name(),
                        job: self.job_status(),
                        job_press: self.transfer.is_some().then_some(Message::TransferDialog(
                            TransferDialogMessage::ShowProgress,
                        )),
                        filing: self.filing_badge(),
                        on_blocked_press: blocked_access_press(
                            self.sandbox.active,
                            &self.active_panel().path,
                        ),
                        on_failure_press: self
                            .job_error
                            .is_some()
                            .then(|| self.job_error_press.clone())
                            .flatten(),
                        blocked_by_sandbox: cfg!(target_os = "macos") && self.sandbox.active,
                        notice: self.notice.as_deref(),
                        hermes_line: self.hermes_line(),
                    },
                    self.status_error(),
                    self.search_status(),
                    statusbar::PathBar {
                        editing: self.path_field.as_deref(),
                        on_input: Message::PathFieldInput,
                        on_submit: Message::PathFieldSubmit,
                        on_copy: Message::CopyToClipboard(ClipboardKind::Directory),
                        hit_line: self.hit_line(),
                    },
                ),
            ])
            .width(Length::Fill)
            .height(Length::Fill)
        };

        let window = container(column![self.title_bar_view(), below_title_bar])
            .width(Length::Fill)
            .height(Length::Fill)
            .style(theme::root(&self.palette));

        // The cards sit on the same scrim as the modals; the panels keep their
        // keys. Every modal below stacks on this base, so it stays above them.
        let module_card = self
            .filing
            .as_ref()
            .filter(|module| module.has_card())
            .and_then(|module| filing_ui::view(module, self.window_size, self.lang, &self.palette));
        let setup_card = self.filing_setup.as_ref().map(|setup| {
            let context = filing_setup_ui::SetupContext {
                current_folder: &self.active_panel().path,
                home: &self.home,
                index_is_plain: self
                    .filing
                    .as_ref()
                    .is_some_and(FilingModule::index_is_plain),
                lang: self.lang,
                window: self.window_size,
            };
            filing_setup_ui::view(setup, &context, &self.palette)
        });
        let hermes_card = self.hermes_setup_view();
        let cards: Vec<Element<'_, Message>> = setup_card
            .into_iter()
            .chain(hermes_card)
            .chain(module_card)
            .collect();
        let base: Element<'_, Message> = if cards.is_empty() {
            window.into()
        } else {
            let card = Column::with_children(cards)
                .spacing(theme::spacing::LINE_GAP)
                .align_x(iced::Alignment::Center);
            Stack::with_children([window.into(), dialog::scrim(card.into())]).into()
        };
        let root = if cfg!(target_os = "macos") {
            base
        } else {
            titlebar::with_resize_edges(base)
        };

        if let Some(menu) = self.quick_fix.as_ref() {
            let click_catcher = mouse_area(Space::new().width(Length::Fill).height(Length::Fill))
                .on_press(Message::QuickFix(QuickFixMessage::Close));
            return Stack::with_children([
                root,
                click_catcher.into(),
                quick_fix_view::view(menu, self.lang, &self.palette),
            ])
            .into();
        }

        if let Some(menu) = self.context_menu.as_ref() {
            // A left press anywhere beside the menu closes it, the path field
            // and the column titles included: those take their own clicks and
            // would never report one. A right press passes through, so another
            // row's menu replaces this one.
            // A Ctrl+click on a Mac is a right click and passes through too.
            let mut click_catcher =
                mouse_area(Space::new().width(Length::Fill).height(Length::Fill));
            if !is_context_click(self.modifiers) {
                click_catcher = click_catcher.on_press(Message::ContextMenuClose);
            }
            return Stack::with_children([
                root,
                click_catcher.into(),
                context_menu_view::view(menu, self.lang, &self.keymap, &self.palette),
            ])
            .into();
        }

        if let Some(menu) = self.volume_menu.as_ref() {
            let menu_element = volumes_view::view(
                menu.side,
                volumes_view::MenuRows {
                    volumes: &menu.volumes,
                    favourites: &menu.favourites,
                    servers: &menu.servers,
                    trash: menu.trash,
                },
                menu.selected,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(menu_element)]).into();
        }

        if let Some(deletion) = self.delete_dialog.as_ref() {
            let dialog_element = delete_dialog_view::view(
                &self.delete_subject(deletion),
                deletion.permanent,
                self.dialog_focus,
                self.window_size,
                self.lang,
                &self.palette,
            )
            .map(Message::from);
            return Stack::with_children([root, dialog::scrim(dialog_element)]).into();
        }

        if let Some(card) = self.about.as_ref() {
            let card_element = about_ui::view(
                card,
                self.app_version,
                self.dialog_focus,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(card_element)]).into();
        }

        if let Some(card) = self.ocr_models.as_ref() {
            let card_element = ocr_models_ui::view(
                card,
                self.dialog_focus,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(card_element)]).into();
        }

        if let Some(card) = self.ai_model.as_ref().filter(|_| !self.ai_card_hidden) {
            let card_element = ai_model_ui::view(
                card,
                self.dialog_focus,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(card_element)]).into();
        }

        if self.start_over_dialog {
            let question = hermes_overview_ui::start_over_dialog(
                self.dialog_focus,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(question)]).into();
        }

        if let Some(dialog) = self.connect_dialog.as_ref() {
            let dialog_element =
                remote_ui::view(dialog, self.window_size, self.lang, &self.palette);
            return Stack::with_children([root, dialog::scrim(dialog_element)]).into();
        }

        if self.grant_dialog {
            let dialog_element = grant_ui::view(
                self.dialog_focus,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(dialog_element)]).into();
        }

        // The conflict dialog comes first, before the prompt. A conflict is
        // asked *after* the prompt is gone — the user submitted, and the name
        // turned out to be taken — so behind the prompt's early return the
        // dialog was never drawn. That was a real bug, and the snapshot test is
        // what found it.
        if self.conflict_is_open() {
            let name = self.conflict_name();
            let conflict_element = conflict::view(
                &name,
                self.lang,
                &self.palette,
                self.conflict_all,
                self.dialog_focus,
                self.window_size,
            )
            .map(Message::from);
            return Stack::with_children([root, dialog::scrim(conflict_element)]).into();
        }

        if let Some(confirm) = self.transfer_dialog.as_ref() {
            let confirm_element =
                transfer_ui::confirm(confirm, self.window_size, self.lang, &self.palette)
                    .map(Message::from);
            return Stack::with_children([root, dialog::scrim(confirm_element)]).into();
        }

        if let Some(running) = self.progress_mask() {
            let progress_element =
                transfer_ui::progress(&running, self.window_size, self.lang, &self.palette)
                    .map(Message::from);
            return Stack::with_children([root, dialog::scrim(progress_element)]).into();
        }

        if let Some(quick_open) = self.quick_open.as_ref() {
            let box_element =
                quick_open_ui::view(quick_open, self.window_size, self.lang, &self.palette)
                    .map(Message::QuickOpen);
            return Stack::with_children([root, dialog::scrim(box_element)]).into();
        }

        if let Some(shortcuts) = self.key_bindings.as_ref() {
            let dialog_element =
                key_bindings_ui::view(shortcuts, self.window_size, self.lang, &self.palette);
            return Stack::with_children([root, dialog::scrim(dialog_element)]).into();
        }

        if let Some(command_palette) = self.command_palette.as_ref() {
            let box_element = command_palette_ui::view(
                command_palette,
                self.window_size,
                self.lang,
                &self.palette,
            );
            return Stack::with_children([root, dialog::scrim(box_element)]).into();
        }

        if let Some(card) = self.theme_fetch.as_ref() {
            let card_element =
                theme_fetch_ui::view(card, self.window_size, self.lang, &self.palette);
            return Stack::with_children([root, dialog::scrim(card_element)]).into();
        }

        // Then the create-directory prompt, for F7.
        let Some(prompt) = self.prompt.as_ref() else {
            return root;
        };
        let overlay = dialog::view(
            prompt,
            self.window_size,
            self.lang,
            &self.palette,
            Message::PromptInput,
            Message::PromptSubmit,
            Message::PromptCancel,
        );
        let Some(prompt_element) = overlay else {
            return root;
        };

        // The prompt sits above everything and takes every keystroke; the scrim
        // swallows clicks meant for the panels underneath.
        Stack::with_children([root, dialog::scrim(prompt_element)]).into()
    }

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    pub fn panel(&self, side: PanelSide) -> &PanelState {
        self.panels.panel(side)
    }

    pub fn panel_mut(&mut self, side: PanelSide) -> &mut PanelState {
        self.panels.panel_mut(side)
    }

    pub fn active_panel(&self) -> &PanelState {
        self.panels.active_panel()
    }

    pub fn active_panel_mut(&mut self) -> &mut PanelState {
        self.panels.active_panel_mut()
    }

    #[allow(dead_code)] // Used by upcoming two-panel operations (copy/move).
    pub fn inactive_panel_mut(&mut self) -> &mut PanelState {
        self.panel_mut(self.panels.active.other())
    }

    /// The error the status line shows: a job's, else the config's.
    pub fn status_error(&self) -> Option<&str> {
        self.job_error.as_deref().or(self.config_error.as_deref())
    }

    /// What the bar's path field says while the active panel is a hit list:
    /// the query, where it ran and how many files it left, with the way back.
    /// The keys the bar shows: the search's while it has the keys, else the
    /// panels'. A hit list is no folder, so F7 (new folder) is left out.
    fn function_key_bar(&self) -> [Option<&'static str>; keymap::FUNCTION_KEY_COUNT] {
        if self.search_has_keys() {
            return self.search_function_keys;
        }
        let mut keys = self.function_keys;
        if self.active_panel().is_hit_list() {
            if let Some(slot) = keys.get_mut(keymap::NEW_FOLDER_SLOT) {
                *slot = None;
            }
        }
        keys
    }

    fn hit_line(&self) -> Option<statusbar::HitLine> {
        let panel = self.active_panel();
        let list = panel.hit_list.as_ref()?;
        let count = panel.entries.len();
        let template = self.lang.text(if count == 1 {
            Msg::HitListPathBarOne
        } else {
            Msg::HitListPathBarMany
        });
        let scope = titlebar::tab_label(&list.scope, &self.home, false, usize::MAX);
        Some(statusbar::HitLine {
            text: fill_template(
                template,
                &[
                    ("{query}", &list.query),
                    ("{scope}", &scope),
                    ("{count}", &count.to_string()),
                ],
            ),
            back_key: "Esc".to_owned(),
            back_label: self.lang.text(Msg::HitListBackHint).to_owned(),
        })
    }

    /// What the status bar shows instead of the panel's entry while the search
    /// has the keys: the cursor's file below the root.
    /// Empty without a cursor, so the panel's entry does not pose as the
    /// search's.
    fn search_status(&self) -> Option<String> {
        if !self.search_has_keys() {
            return None;
        }
        let view = self.search.view.as_ref()?;
        let Some((path, _)) = view.cursor_target() else {
            return Some(String::new());
        };
        let relative = path.strip_prefix(&view.root).unwrap_or(&path);
        Some(relative.display().to_string())
    }

    /// The state the key routing needs, cheap to clone.
    fn prompt_key_state(&self) -> PromptKeyState {
        let job_running = self.jobs.is_busy();
        let config_error = self.config_error.is_some();
        let volume_menu = self.volume_menu.is_some();
        let context_menu = self.context_menu.is_some();
        let context_submenu = self
            .context_menu
            .as_ref()
            .is_some_and(ContextMenu::submenu_is_open);
        let quick_fix = self.quick_fix.is_some();
        let path_editing = self.path_field.is_some();
        let command_line = self.command_line.is_focused();
        let search = self.search_has_keys();
        let trash = self.trash_has_keys();
        let hit_list = self.active_panel().is_hit_list();
        let quick_open = self.quick_open.is_some();
        let command_palette = self.command_palette.is_some();
        let key_bindings = self.key_bindings.is_some();
        let key_bindings_recording = self
            .key_bindings
            .as_ref()
            .is_some_and(KeyBindings::is_recording);
        let filing_status = self.filing_status.page_open();
        let hermes_overview = self.hermes_overview.is_some();
        let hermes_overview_editing = self
            .hermes_overview
            .as_ref()
            .is_some_and(OverviewState::is_editing);
        let filing_setup = self.filing_setup.is_some();
        let hermes_setup = self.hermes_setup.is_some();
        let filing_card = self
            .filing
            .as_ref()
            .is_some_and(FilingModule::card_can_be_dismissed);
        let theme_fetch = self.theme_fetch.is_some();
        let rule_suggestions = self.rule_suggestions.is_some();
        let rules = self.rules.is_some();
        let rules_form = self.rules.as_ref().is_some_and(RulesPage::is_editing);
        let rules_confirming_delete = self
            .rules
            .as_ref()
            .is_some_and(RulesPage::is_confirming_delete);
        let review_list = self.review_list.is_some();
        let review_list_editing = self
            .review_list
            .as_ref()
            .is_some_and(ReviewList::is_editing);
        let review_list_replanning = self
            .review_list
            .as_ref()
            .is_some_and(|view| view.replan().is_some());
        let saved_queries = self.saved_queries.is_some();
        let tags = self.tags.is_some();
        let hermes_sidebar =
            self.hermes_focus == HermesFocus::Sidebar && self.open_hermes_page().is_some();
        let reorganisation_plan = self.reorganisation.is_some();
        let about = self.about.is_some();
        let ocr_models = self.ocr_models.is_some();
        let ai_model = self.ai_card_is_shown();
        let grant_dialog = self.grant_dialog;
        let connect_dialog = self.connect_dialog.is_some();
        let settings = self.settings.is_some();
        let transfer_dialog = self.transfer_dialog.is_some();
        let transfer_progress = self.progress_mask_is_open();
        let start_over_dialog = self.start_over_dialog;
        let delete_dialog = match &self.delete_dialog {
            None => DeleteKeys::Closed,
            Some(deletion) if deletion.permanent => DeleteKeys::Permanent,
            Some(_) => DeleteKeys::Trash,
        };
        match &self.prompt {
            None => PromptKeyState {
                keymap: Arc::clone(&self.keymap),
                job_running,
                config_error,
                delete_dialog,
                start_over_dialog,
                volume_menu,
                context_menu,
                context_submenu,
                quick_fix,
                path_editing,
                command_line,
                search,
                trash,
                hit_list,
                quick_open,
                command_palette,
                key_bindings,
                key_bindings_recording,
                filing_status,
                hermes_overview,
                hermes_overview_editing,
                filing_setup,
                hermes_setup,
                filing_card,
                theme_fetch,
                rule_suggestions,
                rules,
                rules_form,
                rules_confirming_delete,
                review_list,
                review_list_editing,
                review_list_replanning,
                saved_queries,
                tags,
                hermes_sidebar,
                reorganisation_plan,
                about,
                ocr_models,
                ai_model,
                grant_dialog,
                connect_dialog,
                settings,
                // A conflict is asked while no prompt is open — the prompt is
                // gone by then, the transfer is what is running. Without this
                // the dialog's keys would fall through to the panels.
                conflict_open: self.conflict_is_open(),
                transfer_dialog,
                transfer_progress,
                ..PromptKeyState::default()
            },
            Some(prompt) => PromptKeyState {
                keymap: Arc::clone(&self.keymap),
                open: true,
                job_running,
                config_error,
                delete_dialog,
                start_over_dialog,
                volume_menu,
                context_menu,
                context_submenu,
                quick_fix,
                path_editing,
                command_line,
                search,
                trash,
                hit_list,
                quick_open,
                command_palette,
                key_bindings,
                key_bindings_recording,
                filing_status,
                hermes_overview,
                hermes_overview_editing,
                filing_setup,
                hermes_setup,
                filing_card,
                theme_fetch,
                rule_suggestions,
                rules,
                rules_form,
                rules_confirming_delete,
                review_list,
                review_list_editing,
                review_list_replanning,
                saved_queries,
                tags,
                hermes_sidebar,
                reorganisation_plan,
                about,
                ocr_models,
                ai_model,
                grant_dialog,
                connect_dialog,
                settings,
                conflict_open: self.conflict_is_open(),
                transfer_dialog,
                transfer_progress,
                busy: prompt.busy(),
                typed: prompt.name().into(),
            },
        }
    }

    /// NC's rule for F5, F6 and F8: tagged rows win, otherwise the row under
    /// the cursor. The `..` entry is never a thing to act on. In the search
    /// view the same holds for its files, and never for all files found.
    fn action_sources(&self) -> Vec<PathBuf> {
        if let Some(search) = self.open_search_view() {
            return search.action_files();
        }
        let panel = self.active_panel();
        if panel.selection.any_tagged() {
            panel
                .selection
                .ordered(&panel.entries)
                .into_iter()
                .map(|e| e.path.clone())
                .collect()
        } else {
            panel
                .selected_entry()
                .filter(|e| !e.is_parent)
                .map(|e| vec![e.path.clone()])
                .unwrap_or_default()
        }
    }

    /// Puts the path or name of the target on the clipboard and says so in the
    /// status bar. Nothing happens under an overlay or with nothing to copy.
    fn copy_to_clipboard(&mut self, kind: ClipboardKind) -> Task<Message> {
        if self.overlay_is_open() {
            return Task::none();
        }
        let from_results = self
            .open_search_view()
            .filter(|_| kind != ClipboardKind::Directory)
            .map(|search| clipboard_text_of_files(&search.action_files(), kind));
        let Some(copied) =
            from_results.unwrap_or_else(|| clipboard_text(self.active_panel(), kind))
        else {
            return Task::none();
        };
        self.job_error = None;
        let shown = self.show_notice(self.copied_notice(kind, copied.count));
        Task::batch([iced::clipboard::write(copied.text), shown])
    }

    fn update_filing(&mut self, message: FilingMessage) -> Task<Message> {
        let Some(module) = self.filing.as_mut() else {
            return Task::none();
        };
        if matches!(message, FilingMessage::CopyRecoveryKey) {
            let Some(key_text) = module.recovery_key_text() else {
                return Task::none();
            };
            let copied = self.show_notice(self.lang.text(Msg::FilingKeyCopied).to_owned());
            return Task::batch([iced::clipboard::write(key_text), copied]);
        }
        let work_finished = matches!(message, FilingMessage::WorkDone { .. });
        let was_starting = matches!(module.phase(), Phase::Starting);
        let was_changing_protection = module.is_changing_protection();
        let work = module.update(message);
        let mut pipeline_started = false;
        if self.pipeline.is_none() && matches!(module.phase(), Phase::Ready) {
            let started = module.start_pipeline().ok();
            pipeline_started = started.is_some();
            (self.pipeline, self.pdf_library_missing) = match started {
                Some((runner, missing)) => (Some(runner), missing),
                None => (None, None),
            };
        }
        let skipped = if was_starting && !matches!(module.phase(), Phase::Starting) {
            module
                .locations()
                .iter()
                .filter(|entry| !matches!(entry.status, LocationStatus::Ready(_)))
                .count()
        } else {
            0
        };
        // A text field only gets the keys once it has the focus.
        let field = match module.phase() {
            Phase::ShowRecoveryKey { .. } if work_finished => Some(filing_ui::GROUP_FIELD_ID),
            Phase::AskRecoveryKey { .. } if work_finished => Some(filing_ui::KEY_FIELD_ID),
            _ => None,
        };
        let ask_for_ai_model =
            matches!(module.phase(), Phase::Ready) && module.ai_model_is_missing();
        let asks_encryption = module.asks_encryption();
        let protection_change_wants_a_card = was_changing_protection
            && !module.is_changing_protection()
            && (asks_encryption || module.has_card());
        let exceptions_access = work_finished.then(|| module.tags_access()).flatten();
        let mut tasks: Vec<Task<Message>> = work.map(run_filing_work).into_iter().collect();
        tasks.extend(exceptions_access.map(|access| {
            Task::perform(
                tokio::task::spawn_blocking(move || access.exceptions()),
                |joined| {
                    let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                    Message::Tags(TagsMessage::ExceptionsRead(result))
                },
            )
        }));
        if asks_encryption && self.hermes_setup.is_none() && self.pending_hermes_start.is_none() {
            self.open_hermes_setup();
        }
        if protection_change_wants_a_card && self.hermes_overview.is_some() {
            tasks.push(self.leave_hermes_overview_state());
            self.return_to_hermes_overview = true;
        }
        tasks.push(self.advance_hermes_plan());
        tasks.extend(field.map(operation::focus));
        if pipeline_started {
            // The index is open and `reconcile` has settled what a crash left;
            // what an earlier run planned but did not move goes now.
            tasks.push(self.run_filing());
        }
        if ask_for_ai_model && !self.ai_model_asked {
            tasks.push(self.open_ai_model());
            self.ai_model_asked = self.ai_model.is_some();
        }
        if skipped > 0 {
            let text = fill_template(
                self.lang.text(Msg::FilingLocationsSkipped),
                &[("{count}", &skipped.to_string())],
            );
            tasks.push(self.show_notice(text));
        }
        Task::batch(tasks)
    }

    /// The dots move only while the picture is on screen.
    fn hermes_flow_is_visible(&self) -> bool {
        self.hermes_setup.is_some() || self.hermes_overview.is_some()
    }

    fn hermes_setup_offer(&self) -> SetupOffer {
        let models_dir = self
            .filing_index_path
            .as_deref()
            .and_then(crate::filing::ai_models_dir);
        SetupOffer {
            existing_index: self
                .filing_index_path
                .as_deref()
                .and_then(ExistingIndex::of_file),
            model_download: models_dir.is_some_and(|dir| !model_is_installed(&dir)),
            hermes_was_off: self.hermes_is_off(),
        }
    }

    /// Opens the card with what the config lists now.
    fn open_hermes_setup(&mut self) {
        let setup = HermesSetup::new(&self.filing_config.locations, self.hermes_setup_offer());
        self.dialog_focus = setup.first_focus(setup.can_start());
        self.hermes_setup = Some(setup);
    }

    /// The card cannot be changed while the folders are written or the module
    /// starts and creates the index.
    fn hermes_setup_is_busy(&self) -> bool {
        self.pending_hermes_start.is_some()
            || self.hermes_setup.as_ref().is_some_and(HermesSetup::is_busy)
            || self
                .filing
                .as_ref()
                .is_some_and(FilingModule::is_creating_index)
    }

    fn hermes_focus_order(&self) -> Vec<SetupFocus> {
        self.hermes_setup
            .as_ref()
            .map(|setup| setup.focus_order(setup.can_start() && !self.hermes_setup_is_busy()))
            .unwrap_or_default()
    }

    fn hermes_setup_view(&self) -> Option<Element<'_, Message>> {
        let setup = self.hermes_setup.as_ref()?;
        let card = hermes_setup_ui::SetupView {
            setup,
            focus: self.hermes_focus_order().get(self.dialog_focus).copied(),
            busy: self.hermes_setup_is_busy(),
            creating_index: self
                .filing
                .as_ref()
                .is_some_and(FilingModule::is_creating_index),
            creation_error: self
                .filing
                .as_ref()
                .and_then(FilingModule::index_creation_error),
            home: &self.home,
            flow_step: self.hermes_flow_step,
            lang: self.lang,
            window: self.window_size,
        };
        Some(hermes_setup_ui::view(&card, &self.palette))
    }

    /// Enter on the element that has the focus.
    fn activate_hermes_focus(&mut self) -> Task<Message> {
        let Some(element) = self.hermes_focus_order().get(self.dialog_focus).copied() else {
            return Task::none();
        };
        self.update_hermes_setup(match element {
            SetupFocus::ChooseInbox => HermesSetupMessage::PickFolder(FolderSlot::Inbox),
            SetupFocus::ChooseFilingLocation => {
                HermesSetupMessage::PickFolder(FolderSlot::FilingLocation)
            }
            SetupFocus::Encrypted => HermesSetupMessage::ChooseEncrypted(true),
            SetupFocus::Plain => HermesSetupMessage::ChooseEncrypted(false),
            SetupFocus::LoadModel => HermesSetupMessage::ToggleLoadModel,
            SetupFocus::Later => HermesSetupMessage::Later,
            SetupFocus::Start => HermesSetupMessage::Start,
        })
    }

    fn update_hermes_setup(&mut self, message: HermesSetupMessage) -> Task<Message> {
        match message {
            HermesSetupMessage::PickFolder(slot) => {
                let Some(setup) = self.hermes_setup.as_mut() else {
                    return Task::none();
                };
                if !setup.start_picking(slot) {
                    return Task::none();
                }
                (self.pick_folder)(&self.active_panel().path).map(move |folder| {
                    Message::HermesSetup(HermesSetupMessage::FolderPicked { slot, folder })
                })
            }
            HermesSetupMessage::FolderPicked { slot, folder } => match folder {
                Some(picked) => {
                    let granted = self.grant_chosen_folder(&picked, |granted_folder, result| {
                        Message::HermesSetup(HermesSetupMessage::Granted {
                            folder: granted_folder,
                            result,
                        })
                    });
                    Task::batch([granted, self.resolve_hermes_folder(slot, picked)])
                }
                None => {
                    if let Some(setup) = self.hermes_setup.as_mut() {
                        setup.cancel_picking();
                    }
                    Task::none()
                }
            },
            HermesSetupMessage::Granted { folder, result } => {
                if let (Some(setup), Err(reason)) = (self.hermes_setup.as_mut(), result) {
                    setup.show_note(SetupNote::GrantFailed { folder, reason });
                }
                Task::none()
            }
            HermesSetupMessage::Resolved {
                slot,
                folder,
                resolved,
            } => {
                if let Some(setup) = self.hermes_setup.as_mut() {
                    setup.finish_picking(slot, folder, resolved);
                }
                Task::none()
            }
            HermesSetupMessage::ChooseEncrypted(encrypted) => {
                if let Some(setup) = self.hermes_setup.as_mut() {
                    setup.choose_encrypted(encrypted);
                }
                Task::none()
            }
            HermesSetupMessage::ToggleLoadModel => {
                if let Some(setup) = self.hermes_setup.as_mut() {
                    setup.toggle_load_model();
                }
                Task::none()
            }
            HermesSetupMessage::Start => self.start_hermes_setup(),
            HermesSetupMessage::Written(result) => match result {
                Ok(filing) => self.hermes_written(filing),
                Err(error) => {
                    self.pending_hermes_start = None;
                    if let Some(setup) = self.hermes_setup.as_mut() {
                        setup.stop_writing(SetupNote::SaveFailed(error));
                    }
                    Task::none()
                }
            },
            HermesSetupMessage::Later => self.hermes_later(),
        }
    }

    /// Looks up `folder` on a blocking thread; the answer is a `Resolved`.
    fn resolve_hermes_folder(&self, slot: FolderSlot, folder: PathBuf) -> Task<Message> {
        let resolve_folder = self.resolve_folder;
        Task::perform(
            tokio::task::spawn_blocking({
                let looked_up = folder.clone();
                move || resolve_folder(&looked_up)
            }),
            move |joined| {
                Message::HermesSetup(HermesSetupMessage::Resolved {
                    slot,
                    folder,
                    resolved: joined.unwrap_or_else(|join| Err(join.to_string())),
                })
            },
        )
    }

    fn start_hermes_setup(&mut self) -> Task<Message> {
        let configured_path = self.config_path.clone();
        let Some(setup) = self.hermes_setup.as_mut() else {
            return Task::none();
        };
        let Some(config_path) = configured_path else {
            setup.stop_writing(SetupNote::NoConfigPath);
            return Task::none();
        };
        let Some(request) = setup.start() else {
            return Task::none();
        };
        self.pending_hermes_start = Some(request.plan);
        let locations = request.locations;
        let written_path = config_path.clone();
        Task::perform(
            tokio::task::spawn_blocking(move || {
                filing_setup::write_locations(&written_path, &locations)
            }),
            move |joined| {
                Message::HermesSetup(HermesSetupMessage::Written(joined.unwrap_or_else(|join| {
                    Err(FilingWriteError::Io {
                        path: config_path,
                        reason: join.to_string(),
                    })
                })))
            },
        )
    }

    /// The locations are saved. A module that waits at the encryption question
    /// on the same locations creates the index; any other is started again on
    /// the new ones and gets there by itself.
    fn hermes_written(&mut self, filing: Filing) -> Task<Message> {
        if let Some(setup) = self.hermes_setup.as_mut() {
            setup.written();
        }
        if self.pending_hermes_start.is_none() {
            return self.apply_saved_filing(filing).1;
        }
        let module_waits = self
            .filing
            .as_ref()
            .is_some_and(|module| module.asks_encryption() && module.has_configured_locations());
        if module_waits && self.filing_config.locations == filing.locations {
            self.filing_config = filing;
            return self.advance_hermes_plan();
        }
        let replaceable = self.filing_key_store.is_some()
            && self
                .filing
                .as_ref()
                .is_none_or(FilingModule::can_take_first_setup);
        if !replaceable {
            self.filing_config = filing;
            self.pending_hermes_start = None;
            self.hermes_setup = None;
            return self.show_notice(self.saved_filing_notice(SavedFilingApplies::AtNextStart));
        }
        self.pipeline = None;
        self.filing = None;
        let task = self.start_filing_module(&filing);
        self.refresh_filing_snapshot();
        task
    }

    /// "Später": Hermes stays off its first run until the user asks again.
    fn hermes_later(&mut self) -> Task<Message> {
        if self.hermes_setup_is_busy() {
            return Task::none();
        }
        self.hermes_setup = None;
        if self.filing.is_some() {
            self.update_filing(FilingMessage::Dismiss)
        } else {
            Task::none()
        }
    }

    /// Takes the next step of "Hermes starten" the module's phase allows, and
    /// closes the card once the module's own cards or the work take over.
    fn advance_hermes_plan(&mut self) -> Task<Message> {
        let (Some(mut plan), Some(module)) = (self.pending_hermes_start, self.filing.as_mut())
        else {
            return Task::none();
        };
        let step = plan.next_step(module.phase());
        let card_is_done = card_is_done_at(module.phase());
        let creation = match step {
            PlanStep::CreateIndex { encrypted } => module.create_index_with(encrypted),
            PlanStep::Wait | PlanStep::Done { .. } | PlanStep::Abandon => None,
        };
        self.pending_hermes_start = match step {
            PlanStep::Done { .. } | PlanStep::Abandon => None,
            PlanStep::Wait | PlanStep::CreateIndex { .. } => Some(plan),
        };
        if card_is_done {
            self.hermes_setup = None;
        }
        let mut tasks: Vec<Task<Message>> = creation.map(run_filing_work).into_iter().collect();
        if let PlanStep::Done { load_model } = step {
            // The choice was made on the card; the module does not ask again.
            self.ai_model_asked = true;
            if load_model {
                tasks.push(self.open_ai_model());
                tasks.push(self.start_ai_model_download());
            }
        }
        Task::batch(tasks)
    }

    fn update_filing_setup(&mut self, message: FilingSetupMessage) -> Task<Message> {
        match message {
            FilingSetupMessage::Toggle => {
                if self.hermes_setup.take().is_some() {
                    self.pending_hermes_start = None;
                } else if self.filing_setup.take().is_none() {
                    if self.filing_config.locations.is_empty() {
                        self.open_hermes_setup();
                    } else {
                        self.filing_setup = Some(FilingSetup::new(&self.filing_config.locations));
                    }
                }
                Task::none()
            }
            FilingSetupMessage::Close => {
                self.filing_setup = None;
                Task::none()
            }
            FilingSetupMessage::PickFolder(mode) => {
                let Some(setup) = self.filing_setup.as_mut() else {
                    return Task::none();
                };
                if !setup.start_adding() {
                    return Task::none();
                }
                (self.pick_folder)(&self.active_panel().path).map(move |folder| {
                    Message::FilingSetup(FilingSetupMessage::FolderPicked { mode, folder })
                })
            }
            FilingSetupMessage::FolderPicked { mode, folder } => {
                let Some(setup) = self.filing_setup.as_mut() else {
                    return Task::none();
                };
                match folder {
                    Some(picked) => {
                        let granted =
                            self.grant_chosen_folder(&picked, |granted_folder, result| {
                                Message::FilingSetup(FilingSetupMessage::Granted {
                                    folder: granted_folder,
                                    result,
                                })
                            });
                        Task::batch([granted, self.resolve_setup_folder(mode, picked)])
                    }
                    None => {
                        setup.cancel_adding();
                        Task::none()
                    }
                }
            }
            FilingSetupMessage::AddPanelFolder(mode) => {
                let Some(setup) = self.filing_setup.as_mut() else {
                    return Task::none();
                };
                if !setup.start_adding() {
                    return Task::none();
                }
                let folder = self.active_panel().path.clone();
                self.resolve_setup_folder(mode, folder)
            }
            FilingSetupMessage::Granted { folder, result } => {
                if let (Some(setup), Err(reason)) = (self.filing_setup.as_mut(), result) {
                    setup.show_note(SetupNote::GrantFailed { folder, reason });
                }
                Task::none()
            }
            FilingSetupMessage::Added {
                mode,
                folder,
                resolved,
            } => {
                if let Some(setup) = self.filing_setup.as_mut() {
                    setup.finish_adding(mode, folder, resolved);
                }
                Task::none()
            }
            FilingSetupMessage::SetTarget(index) => {
                if let Some(setup) = self.filing_setup.as_mut() {
                    setup.set_target(index);
                }
                Task::none()
            }
            FilingSetupMessage::ToggleImages(index) => {
                if let Some(setup) = self.filing_setup.as_mut() {
                    setup.toggle_images(index);
                }
                Task::none()
            }
            FilingSetupMessage::Remove(index) => {
                if let Some(setup) = self.filing_setup.as_mut() {
                    setup.remove(index);
                }
                Task::none()
            }
            FilingSetupMessage::Save => {
                let Some(setup) = self.filing_setup.as_mut() else {
                    return Task::none();
                };
                let Some(config_path) = self.config_path.clone() else {
                    setup.refuse_saving(SetupNote::NoConfigPath);
                    return Task::none();
                };
                let Some(chosen) = setup.start_saving() else {
                    return Task::none();
                };
                let written_path = config_path.clone();
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        filing_setup::write_locations(&written_path, &chosen)
                    }),
                    move |joined| {
                        Message::FilingSetup(FilingSetupMessage::Saved(joined.unwrap_or_else(
                            |join| {
                                Err(FilingWriteError::Io {
                                    path: config_path,
                                    reason: join.to_string(),
                                })
                            },
                        )))
                    },
                )
            }
            FilingSetupMessage::Saved(result) => {
                // The file is written even when the card was closed meanwhile,
                // so the module follows it all the same.
                match result {
                    Ok(filing) => {
                        let (applies, task) = self.apply_saved_filing(filing);
                        self.filing_setup = None;
                        let notice = self.show_notice(self.saved_filing_notice(applies));
                        Task::batch([task, notice])
                    }
                    Err(error) => {
                        if let Some(setup) = self.filing_setup.as_mut() {
                            setup.finish_saving(SetupNote::SaveFailed(error));
                        }
                        Task::none()
                    }
                }
            }
        }
    }

    /// Looks up `folder` on a blocking thread; the answer is an `Added`.
    fn resolve_setup_folder(&self, mode: LocationMode, folder: PathBuf) -> Task<Message> {
        let resolve_folder = self.resolve_folder;
        Task::perform(
            tokio::task::spawn_blocking({
                let looked_up = folder.clone();
                move || resolve_folder(&looked_up)
            }),
            move |joined| {
                Message::FilingSetup(FilingSetupMessage::Added {
                    mode,
                    folder,
                    resolved: joined.unwrap_or_else(|join| Err(join.to_string())),
                })
            },
        )
    }

    fn saved_filing_notice(&self, applies: SavedFilingApplies) -> String {
        match applies {
            SavedFilingApplies::AtNextStart => {
                self.lang.text(Msg::FilingSetupSavedNextStart).to_owned()
            }
            SavedFilingApplies::Now => {
                match self
                    .keymap
                    .shortcut_label(&Message::FilingStatus(FilingStatusMessage::Toggle))
                {
                    Some(key) => fill_template(
                        self.lang.text(Msg::FilingSetupSavedRunning),
                        &[("{key}", &key)],
                    ),
                    None => self
                        .lang
                        .text(Msg::FilingSetupSavedRunningUnbound)
                        .to_owned(),
                }
            }
        }
    }

    /// A module that works on configured locations keeps running on them:
    /// there is no reload, and the saved list takes over at the next start.
    /// One without locations, or none at all, is replaced at once.
    fn apply_saved_filing(&mut self, filing: Filing) -> (SavedFilingApplies, Task<Message>) {
        let replaceable = self.filing_key_store.is_some()
            && self.filing.as_ref().is_none_or(|module| {
                !module.has_configured_locations() && module.can_be_replaced()
            });
        if !replaceable {
            self.filing_config = filing;
            return (SavedFilingApplies::AtNextStart, Task::none());
        }
        // Dropping the runner stops it and lets go of the index before the
        // new module opens it again.
        self.pipeline = None;
        self.filing = None;
        let task = self.start_filing_module(&filing);
        self.refresh_filing_snapshot();
        (SavedFilingApplies::Now, task)
    }

    /// Shows `text` in the status bar for [`NOTICE_DURATION`]. The timer carries
    /// the generation, so it cannot clear a notice that came after it.
    fn show_notice(&mut self, text: String) -> Task<Message> {
        self.notice_generation = self.notice_generation.wrapping_add(1);
        self.notice = Some(text);
        let generation = self.notice_generation;
        Task::perform(
            async { tokio::time::sleep(NOTICE_DURATION).await },
            move |()| Message::NoticeExpired(generation),
        )
    }

    fn copied_notice(&self, kind: ClipboardKind, count: usize) -> String {
        let (one, many) = match kind {
            ClipboardKind::Path | ClipboardKind::Directory => {
                (Msg::StatusPathCopied, Msg::StatusPathsCopied)
            }
            ClipboardKind::Name => (Msg::StatusNameCopied, Msg::StatusNamesCopied),
        };
        if count == 1 {
            self.lang.text(one).to_string()
        } else {
            self.lang.text(many).replace("{count}", &count.to_string())
        }
    }

    fn dialog_button_count(&self) -> usize {
        if self.hermes_setup.is_some() {
            self.hermes_focus_order().len()
        } else if self.about.is_some() {
            3
        } else if self.model_card_has_one_button() {
            1
        } else if self.delete_dialog.is_some()
            || self.start_over_dialog
            || self.ocr_models.is_some()
            || self.ai_card_is_shown()
            || self.grant_dialog
        {
            2
        } else if self.conflict_is_open() {
            3
        } else {
            0
        }
    }

    /// A model card that has nothing left to ask: it only reports, and has
    /// Close or Done. The AI card that could not turn the AI on has a second
    /// button.
    fn model_card_has_one_button(&self) -> bool {
        let ocr = self
            .ocr_models
            .as_ref()
            .is_some_and(|card| card.is_installed() || card.is_finished());
        let ai = self.ai_model.as_ref().is_some_and(|card| {
            card.is_installed()
                || (card.is_finished() && card.outcome() != Some(InstallOutcome::StillOff))
        });
        ocr || ai
    }

    /// Enter in a button dialog: whatever the focused button does.
    fn activate_dialog_button(&mut self) -> Task<Message> {
        if self.hermes_setup.is_some() {
            return self.activate_hermes_focus();
        }
        if self.start_over_dialog {
            return if self.dialog_focus == hermes_overview_ui::START_OVER_CONFIRM_FOCUS {
                self.update_hermes_overview(HermesOverviewMessage::ConfirmStartOver)
            } else {
                self.start_over_dialog = false;
                Task::none()
            };
        }
        if self.delete_dialog.is_some() {
            return if self.dialog_focus == delete_dialog_view::CONFIRM_FOCUS {
                self.confirm_delete()
            } else {
                self.delete_dialog = None;
                Task::none()
            };
        }
        if self.about.is_some() {
            return match self.dialog_focus {
                about_ui::REPOSITORY_FOCUS => self.update_about(AboutMessage::OpenRepository),
                about_ui::LICENSES_FOCUS => self.update_about(AboutMessage::OpenLicenses),
                _ => self.update_about(AboutMessage::Close),
            };
        }
        if self.model_card_has_one_button() {
            return if self.ocr_models.is_some() {
                self.close_ocr_models()
            } else {
                self.close_ai_model()
            };
        }
        if self.ai_model.as_ref().is_some_and(AiModelCard::is_finished) {
            return if self.dialog_focus == ai_model_ui::DOWNLOAD_FOCUS {
                self.update_ai_model(AiModelMessage::ShowAiSetting)
            } else {
                self.close_ai_model()
            };
        }
        if self.ocr_models.is_some() {
            return if self.dialog_focus == ocr_models_ui::DOWNLOAD_FOCUS {
                self.start_ocr_models_download()
            } else {
                self.close_ocr_models()
            };
        }
        if self.ai_card_is_shown() {
            return if self.dialog_focus == ai_model_ui::DOWNLOAD_FOCUS {
                self.press_ai_model_button()
            } else {
                self.close_ai_model()
            };
        }
        if self.grant_dialog {
            return if self.dialog_focus == grant_ui::GRANT_FOCUS {
                self.update_grant(GrantMessage::Choose)
            } else {
                self.update_grant(GrantMessage::Later)
            };
        }
        if self.conflict_is_open() {
            let choice = match self.dialog_focus {
                conflict::OVERWRITE_FOCUS => ConflictChoice::ThisOverwrite,
                conflict::KEEP_FOCUS => ConflictChoice::ThisKeep,
                _ => ConflictChoice::Cancel,
            };
            return self.answer_conflict(choice);
        }
        Task::none()
    }

    /// A prompt, dialog or menu is on top of the panels.
    fn overlay_is_open(&self) -> bool {
        self.blocking_overlay_is_open() || self.context_menu.is_some()
    }

    /// Everything on top of the panels except the context menu, which a new
    /// right click may replace.
    fn blocking_overlay_is_open(&self) -> bool {
        self.ablage_tab_is_open() || self.overlay_apart_from_overview_is_open()
    }

    /// The page of filing that stands in for the panels: the overview or the
    /// status.
    fn ablage_tab_is_open(&self) -> bool {
        self.hermes_overview.is_some()
            || self.filing_status.page_open()
            || self.rule_suggestions.is_some()
            || self.review_list.is_some()
            || self.rules.is_some()
            || self.saved_queries.is_some()
            || self.tags.is_some()
            || self.reorganisation.is_some()
    }

    /// Closes the page of filing without a word, for a page that replaces it.
    fn close_ablage_tab(&mut self) -> Task<Message> {
        self.filing_status.close_page();
        self.rule_suggestions = None;
        self.review_list = None;
        self.rules = None;
        self.saved_queries = None;
        self.tags = None;
        self.reorganisation = None;
        self.leave_hermes_overview()
    }

    /// What the overview itself may open on top of it: the model cards.
    fn overlay_apart_from_overview_is_open(&self) -> bool {
        self.prompt.is_some()
            || self.quick_fix.is_some()
            || self.conflict_is_open()
            || self.transfer_dialog.is_some()
            || self.progress_mask_is_open()
            || self.delete_dialog.is_some()
            || self.start_over_dialog
            || self.volume_menu.is_some()
            || self.quick_open.is_some()
            || self.command_palette.is_some()
            || self.key_bindings.is_some()
            || self.theme_fetch.is_some()
            || self.about.is_some()
            || self.ocr_models.is_some()
            || self.ai_card_is_shown()
            || self.grant_dialog
            || self.connect_dialog.is_some()
            || self.hermes_setup.is_some()
    }

    /// Whether the context menu entry can do something for the current
    /// cursor row and tags.
    fn context_action_enabled(&self, action: ContextAction) -> bool {
        if let Some(search) = self.open_search_view() {
            let has_cursor = search.cursor_target().is_some();
            return match action {
                ContextAction::Open
                | ContextAction::View
                | ContextAction::Edit
                | ContextAction::ShowOnOtherSide => has_cursor,
                ContextAction::Copy
                | ContextAction::Move
                | ContextAction::Trash
                | ContextAction::DeletePermanently => !self.action_sources().is_empty(),
                ContextAction::CopyPath | ContextAction::CopyName => has_cursor,
                ContextAction::NewFolder
                | ContextAction::ComputeFolderSizes
                | ContextAction::RemoveFromList => false,
            };
        }
        let panel = self.active_panel();
        let cursor_row = panel.selected_entry();
        match action {
            ContextAction::Open => cursor_row.is_some(),
            ContextAction::View | ContextAction::Edit => {
                cursor_row.is_some_and(|entry| !entry.is_dir && !entry.is_parent)
            }
            ContextAction::Copy
            | ContextAction::Move
            | ContextAction::Trash
            | ContextAction::DeletePermanently => !self.action_sources().is_empty(),
            ContextAction::NewFolder => true,
            ContextAction::CopyPath => clipboard_text(panel, ClipboardKind::Path).is_some(),
            ContextAction::CopyName => clipboard_text(panel, ClipboardKind::Name).is_some(),
            ContextAction::ComputeFolderSizes => !folder_size_targets(panel).is_empty(),
            ContextAction::ShowOnOtherSide => cursor_row.is_some(),
            ContextAction::RemoveFromList => cursor_row.is_some(),
        }
    }

    /// The menu of the search results at the pointer, for the file the cursor
    /// is on or the tagged ones.
    fn open_search_context_menu(&mut self) {
        if self.blocking_overlay_is_open() || !self.search_has_keys() {
            return;
        }
        self.job_error = None;
        self.notice = None;
        let pointer = self.input.lock().pointer;
        let is_enabled = |action| self.context_action_enabled(action);
        self.context_menu = Some(ContextMenu::for_search_results(
            pointer,
            self.window_size,
            is_enabled,
        ));
    }

    /// Opens the context menu on row `index` of `side`, at `anchor` or, without
    /// one, below that row. The cursor goes to the row; tags stay, so the menu
    /// acts on them as F5 and F8 do.
    fn open_context_menu(&mut self, side: PanelSide, index: usize, anchor: Option<Point>) {
        if self.blocking_overlay_is_open() || (self.search.open && side == self.search.side) {
            return;
        }
        // An open menu is replaced by a right click and left alone by the keys.
        if anchor.is_none() && self.context_menu.is_some() {
            return;
        }
        let rows = self.visible_rows;
        self.panels.active = side;
        self.job_error = None;
        self.notice = None;
        let panel = self.panel_mut(side);
        // As in the Finder: a click on a row outside the tags drops them, so
        // the menu cannot act on rows the user did not point at.
        let on_untagged_row = panel
            .entries
            .get(index)
            .is_some_and(|entry| !panel.selection.is_tagged(&entry.path));
        if anchor.is_some() && on_untagged_row {
            panel.selection.clear();
        }
        panel.select(index, rows);
        let window = self.window_size;
        let cursor_panel = self.panel(side);
        let place_at = anchor.unwrap_or_else(|| {
            layout::cursor_row_anchor(
                side == PanelSide::Right,
                cursor_panel
                    .selected
                    .saturating_sub(cursor_panel.scroll_offset),
                cursor_panel.row_height(),
                window,
            )
        });
        let hermes_enabled = |action| self.hermes_action_enabled(action);
        let hermes = self.hermes_ready().then(|| HermesMenu {
            excluded: self.cursor_is_excluded_from_hermes(),
            is_enabled: &hermes_enabled,
        });
        let is_enabled = |action| self.context_action_enabled(action);
        self.context_menu = Some(if self.panel(side).is_hit_list() {
            ContextMenu::for_hit_list(place_at, self.window_size, is_enabled, hermes)
        } else {
            ContextMenu::with_hermes(place_at, self.window_size, is_enabled, hermes)
        });
    }

    /// Closes the menu and sends the message its highlighted entry stands for,
    /// the same one its key sends. Closed first: the actions refuse to run
    /// under an overlay.
    fn run_context_menu_entry(&mut self) -> Task<Message> {
        let Some(open) = self.context_menu.as_mut() else {
            return Task::none();
        };
        if open.selected_is_hermes() && !open.submenu_is_open() {
            open.open_submenu();
            return Task::none();
        }
        let from_search = self.search_has_keys();
        let Some(menu) = self.context_menu.take() else {
            return Task::none();
        };
        let chosen = if menu.submenu_is_open() {
            menu.selected_hermes_action().map(HermesAction::message)
        } else {
            menu.selected_action().map(|action| match action {
                // Enter on a result shows it in the other panel.
                ContextAction::Open if from_search => Message::Search(SearchMessage::Activate),
                other => other.message(),
            })
        };
        chosen.map_or_else(Task::none, |message| self.update(message))
    }

    /// The file or folder under the cursor of the active panel, for the Hermes
    /// commands: not the `..` row.
    fn hermes_cursor_entry(&self) -> Option<&fs::FileEntry> {
        self.active_panel()
            .selected_entry()
            .filter(|entry| !entry.is_parent)
    }

    fn cursor_is_excluded_from_hermes(&self) -> bool {
        self.hermes_cursor_entry().is_some_and(|entry| {
            if entry.is_dir {
                self.hermes_column
                    .summary_of(&entry.path)
                    .is_some_and(|summary| summary.excluded)
            } else {
                self.hermes_column.state_of(&entry.path) == Some(HermesFileState::Excluded)
            }
        })
    }

    fn inbox_location(&self) -> Option<&Path> {
        self.filing_config
            .locations
            .iter()
            .find(|location| location.mode == LocationMode::Inbox)
            .map(|location| location.path.as_path())
    }

    /// Whether the Hermes entry can do something for the cursor row; the
    /// greyed-out entries of the submenu.
    fn hermes_action_enabled(&self, action: HermesAction) -> bool {
        let Some(entry) = self.hermes_cursor_entry() else {
            return false;
        };
        let role_free = |role| role_of(&entry.path, &self.filing_config.locations) != Some(role);
        let needs_locations = !matches!(
            action,
            HermesAction::SetInbox | HermesAction::SetFilingLocation | HermesAction::SetArchive
        );
        if needs_locations && !self.hermes_active() {
            return false;
        }
        match action {
            HermesAction::ShowSuggestion => !self.inquiry_paths().is_empty(),
            HermesAction::HandToInbox => self
                .inbox_location()
                .is_some_and(|inbox| !entry.path.starts_with(inbox)),
            HermesAction::ProcessAgain => {
                !entry.is_dir
                    && self.live_pipeline().is_some()
                    && self.hermes_column.state_of(&entry.path) != Some(HermesFileState::Excluded)
                    && self
                        .filing_config
                        .locations
                        .iter()
                        .any(|location| entry.path.starts_with(&location.path))
            }
            HermesAction::ReprocessFolder => entry.is_dir,
            HermesAction::SetInbox => entry.is_dir && role_free(FolderRole::Inbox),
            HermesAction::SetFilingLocation => {
                entry.is_dir && role_free(FolderRole::FilingLocation)
            }
            HermesAction::SetArchive => entry.is_dir && role_free(FolderRole::Archive),
            HermesAction::Exclude | HermesAction::Include | HermesAction::Inspect => true,
        }
    }

    fn update_hermes_file(&mut self, message: HermesFileMessage) -> Task<Message> {
        match message {
            HermesFileMessage::RoleSaved(result) => return self.hermes_role_saved(result),
            HermesFileMessage::Included { path, result } => {
                return self.hermes_included(&path, result)
            }
            HermesFileMessage::HandToInbox
            | HermesFileMessage::ProcessAgain
            | HermesFileMessage::ReprocessFolder
            | HermesFileMessage::SetRole(_)
            | HermesFileMessage::ToggleExclusion
            | HermesFileMessage::ShowInInspection => {}
        }
        let available = if matches!(message, HermesFileMessage::SetRole(_)) {
            self.hermes_ready()
        } else {
            self.hermes_active()
        };
        if self.overlay_is_open() || self.search.open || !available {
            return Task::none();
        }
        let cursor = self
            .hermes_cursor_entry()
            .map(|entry| (entry.path.clone(), entry.is_dir));
        if message == HermesFileMessage::ReprocessFolder {
            let folder = match cursor {
                Some((path, true)) => path,
                Some((_, false)) | None => self.active_panel().path.clone(),
            };
            return self.reprocess_folder(folder);
        }
        let Some((path, is_dir)) = cursor else {
            return Task::none();
        };
        match message {
            HermesFileMessage::HandToInbox => {
                let Some(inbox) = self.inbox_location().map(Path::to_path_buf) else {
                    let text = self.lang.text(Msg::StatusHermesNoInbox).to_owned();
                    return self.show_notice(text);
                };
                self.open_transfer_dialog_to(TransferKind::Move, Some(inbox))
            }
            HermesFileMessage::ProcessAgain => self.process_again(&path),
            HermesFileMessage::SetRole(role) if is_dir => self.set_folder_role(&path, role),
            HermesFileMessage::ToggleExclusion => self.toggle_hermes_exclusion(path),
            HermesFileMessage::ShowInInspection => self.show_in_inspection(&path),
            HermesFileMessage::SetRole(_)
            | HermesFileMessage::ReprocessFolder
            | HermesFileMessage::RoleSaved(_)
            | HermesFileMessage::Included { .. } => Task::none(),
        }
    }

    fn process_again(&mut self, path: &Path) -> Task<Message> {
        let since = self
            .live_pipeline()
            .map_or(0, |runner| runner.snapshot().changed_sequence);
        let queued = !self
            .hermes_column
            .state_of(path)
            .is_some_and(|state| state == HermesFileState::Excluded)
            && self
                .live_pipeline()
                .is_some_and(|runner| runner.process_again(path));
        let text = if queued {
            self.invalidate_hermes_path(path);
            self.reading_again.ask(path.to_path_buf(), since);
            fill_template(
                self.lang.text(Msg::StatusHermesProcessingAgain),
                &[(
                    "{name}",
                    &path.file_name().map_or_else(
                        || path.display().to_string(),
                        |name| name.to_string_lossy().into_owned(),
                    ),
                )],
            )
        } else {
            self.lang.text(Msg::StatusHermesNotProcessable).to_owned()
        };
        self.show_notice(text)
    }

    fn set_folder_role(&mut self, folder: &Path, role: FolderRole) -> Task<Message> {
        let Some(config_path) = self.config_path.clone() else {
            let text = self.lang.text(Msg::FilingSetupNoConfigPath).to_owned();
            return self.show_notice(text);
        };
        let chosen =
            match filing_setup::locations_with_role(&self.filing_config.locations, folder, role) {
                Ok(chosen) => chosen,
                Err(refused) => {
                    let text = match refused.problem {
                        crate::filing_setup::SetupProblem::NoDocumentFolder => self
                            .lang
                            .text(Msg::StatusHermesRoleNeedsFilingLocation)
                            .to_owned(),
                        problem => crate::ui::filing_setup::problem_sentence(
                            problem,
                            &refused.chosen,
                            self.lang,
                            &self.home,
                        ),
                    };
                    self.set_status_error(&text);
                    return Task::none();
                }
            };
        let written_path = config_path.clone();
        Task::perform(
            tokio::task::spawn_blocking(move || {
                filing_setup::write_locations(&written_path, &chosen)
            }),
            move |joined| {
                Message::HermesFile(HermesFileMessage::RoleSaved(joined.unwrap_or_else(
                    |join| {
                        Err(FilingWriteError::Io {
                            path: config_path,
                            reason: join.to_string(),
                        })
                    },
                )))
            },
        )
    }

    fn hermes_role_saved(&mut self, result: Result<Filing, FilingWriteError>) -> Task<Message> {
        match result {
            Ok(filing) => {
                let (applies, task) = self.apply_saved_filing(filing);
                self.hermes_column.invalidate_all();
                self.hermes_reads.clear();
                let notice = self.show_notice(self.saved_filing_notice(applies));
                Task::batch([task, notice])
            }
            Err(error) => {
                let reason = crate::ui::filing_setup::write_failure_sentence(
                    &error,
                    &self.filing_config.locations,
                    self.lang,
                    &self.home,
                );
                let text = fill_template(
                    self.lang.text(Msg::StatusHermesRoleFailed),
                    &[("{reason}", &reason)],
                );
                self.set_status_error(&text);
                Task::none()
            }
        }
    }

    fn toggle_hermes_exclusion(&mut self, path: PathBuf) -> Task<Message> {
        if !self.cursor_is_excluded_from_hermes() {
            return self.exclude_from_hermes(vec![path]);
        }
        let Some(access) = self.filing.as_ref().and_then(FilingModule::review_access) else {
            self.set_status_error(INDEX_NOT_OPEN);
            return Task::none();
        };
        let included = path.clone();
        Task::perform(
            tokio::task::spawn_blocking(move || access.include(&path)),
            move |joined| {
                Message::HermesFile(HermesFileMessage::Included {
                    path: included.clone(),
                    result: joined.unwrap_or_else(|err| Err(err.to_string())),
                })
            },
        )
    }

    fn hermes_included(
        &mut self,
        path: &Path,
        result: Result<IncludeOutcome, String>,
    ) -> Task<Message> {
        let text = match result {
            Err(detail) => {
                self.set_status_error(&detail);
                return Task::none();
            }
            Ok(IncludeOutcome::ExcludedByAncestor(folder)) => fill_template(
                self.lang.text(Msg::StatusHermesIncludedByFolder),
                &[("{folder}", &folder.display().to_string())],
            ),
            Ok(IncludeOutcome::Included | IncludeOutcome::NotExcluded) => {
                self.invalidate_hermes_path(path);
                if let Some(runner) = self.live_pipeline() {
                    runner.rescan_around(path);
                }
                fill_template(
                    self.lang.text(Msg::StatusHermesIncluded),
                    &[(
                        "{name}",
                        &path.file_name().map_or_else(
                            || path.display().to_string(),
                            |name| name.to_string_lossy().into_owned(),
                        ),
                    )],
                )
            }
        };
        self.show_notice(text)
    }

    /// Opens the Hermes card on the inspection page, at the file's error if
    /// the page lists one for it.
    fn show_in_inspection(&mut self, path: &Path) -> Task<Message> {
        let task = if self.open_hermes_page().is_some() {
            self.go_to_hermes_page(HermesPage::Inspection)
        } else {
            self.open_filing_status()
        };
        self.filing_status.select_error_of(path);
        task
    }

    /// Alt+F1 / Alt+F2: list the drives and highlight the one `side` is on.
    /// Does nothing while a prompt or dialog holds the keyboard.
    fn open_volume_menu(&mut self, side: PanelSide) {
        self.open_volume_menu_on(side, false);
    }

    /// The favourites are listed below the drives, so the menu is worth
    /// opening with only those. `on_favourites` puts the highlight on the first.
    fn open_volume_menu_on(&mut self, side: PanelSide, on_favourites: bool) {
        if self.overlay_is_open() {
            return;
        }
        let volumes = (self.list_volumes)();
        let favourites: Vec<FavouriteRow> = self
            .favourites
            .iter()
            .map(|path| FavouriteRow {
                path: path.clone(),
                present: path.is_dir(),
            })
            .collect();
        let servers = self.server_rows();
        if volumes.is_empty() && favourites.is_empty() && servers.is_empty() {
            return;
        }
        let mut menu = VolumeMenu::new(side, volumes, &self.panel(side).path)
            .with_favourites(favourites)
            .with_servers(servers)
            .with_trash(self.trash_menu_row());
        if on_favourites {
            menu.selected = menu.volumes.len();
        }
        // A panel on a server opens the menu on that server.
        if let Some(current) = self.panel(side).remote() {
            if let Some(index) = menu.servers.iter().position(|row| row.server == current) {
                menu.selected = menu.volumes.len() + menu.favourites.len() + index;
            }
        }
        self.volume_menu = Some(menu);
    }

    /// The servers the drive menu lists: the saved ones in the order of the
    /// file, then those connected now that are not saved, by name.
    fn server_rows(&self) -> Vec<ServerRow> {
        let connected = self.remote.connected();
        let mut rows: Vec<ServerRow> = self
            .saved_servers
            .iter()
            .map(|entry| {
                let server = entry.server_id();
                ServerRow {
                    label: entry.label(),
                    url: entry.url(),
                    connected: connected.contains(&server),
                    server,
                }
            })
            .collect();
        let mut others: Vec<ServerRow> = connected
            .iter()
            .filter(|open| {
                !self
                    .saved_servers
                    .iter()
                    .any(|entry| entry.server_id() == **open)
            })
            .map(|server| ServerRow {
                label: server.to_string(),
                url: server.root_path(),
                server: server.clone(),
                connected: true,
            })
            .collect();
        others.sort_by(|a, b| a.label.cmp(&b.label));
        rows.extend(others);
        rows
    }

    /// The create of the name prompt has reported: close the prompt or show
    /// why it failed, and reload the folder.
    fn finish_prompt(
        &mut self,
        kind: PromptKind,
        request_id: u64,
        result: Result<(), fs::CreateDirError>,
    ) -> Task<Message> {
        if request_id != self.prompt_request_id {
            // Dismissed or retried while the operation ran.
            return Task::none();
        }
        // The queued reload runs here, after the create has reported —
        // never beside it. On success it selects the new entry; on
        // failure it still re-reads, because the name may belong to
        // something else that appeared meanwhile.
        let created = self
            .pending_reload
            .as_ref()
            .map(|pending| self.panel(pending.side).path.join(&pending.name));
        let reload = self.pending_reload.take().map(|pending| {
            let path = self.panel(pending.side).path.clone();
            self.load(pending.side, path, Some(pending.name))
        });

        match result {
            Ok(()) => {
                self.prompt = None;
                self.prompt_side = None;
                if let (PromptKind::CreateFile, Some(path)) = (kind, created) {
                    self.launch_external(fs::OpenKind::Edit, path, None, CopyOf::Nothing);
                }
            }
            Err(err) => {
                self.set_prompt_busy(false);
                self.set_prompt_error_text(&self.prompt_error(&err));
            }
        }
        reload.unwrap_or_else(Task::none)
    }

    /// Delete or Backspace in the drive menu. A drive row ignores it.
    fn remove_highlighted_row(&mut self) -> Task<Message> {
        let Some(menu) = self.volume_menu.as_mut() else {
            return Task::none();
        };
        let mut task = Task::none();
        if let Some(index) = menu.selected_favourite() {
            let removed = menu.favourites.remove(index);
            self.favourites.retain(|path| *path != removed.path);
            menu.selected = menu.selected.min(menu.last_row());
        } else if let Some(index) = menu.selected_server() {
            // A server is closed from its row. A saved one stays in the list,
            // a server that was only connected leaves it. Removing a saved
            // one is the settings' business.
            let listed = menu.servers.get(index).cloned();
            if let Some(row) = listed.filter(|candidate| candidate.connected) {
                let saved = self
                    .saved_servers
                    .iter()
                    .any(|entry| entry.server_id() == row.server);
                if saved {
                    if let Some(shown) = menu.servers.get_mut(index) {
                        shown.connected = false;
                    }
                } else {
                    menu.servers.remove(index);
                    menu.selected = menu.selected.min(menu.last_row());
                }
                task = Task::done(Message::Remote(RemoteMessage::Disconnect(row.server)));
            }
        }
        // Without drives, the last favourite leaves nothing to pick.
        if self
            .volume_menu
            .as_ref()
            .is_some_and(|open| open.row_count() == 0)
        {
            self.volume_menu = None;
        }
        task
    }

    /// Writes the session state here and now, then ends the app: the runtime
    /// stops right after, so no task would run.
    fn quit(&mut self) -> Task<Message> {
        if let Some(path) = &self.state_path {
            write_session_state(
                &self.session_writes,
                WriteOrder::FINAL,
                path,
                &self.session_state(),
            );
        }
        if let Some(copies) = self.view_copies.as_mut() {
            copies.close();
        }
        self.remote.close_all();
        iced::exit()
    }

    fn open_favourites(&mut self) -> Task<Message> {
        if self.favourites.is_empty() {
            let text = self.lang.text(Msg::StatusNoFavourites).to_owned();
            return self.show_notice(text);
        }
        self.open_volume_menu_on(self.panels.active, true);
        Task::none()
    }

    fn favourite_notice(&mut self, msg: Msg, path: &Path) -> Task<Message> {
        let text = fill_template(
            self.lang.text(msg),
            &[("{path}", &path.display().to_string())],
        );
        self.show_notice(text)
    }

    fn add_favourite(&mut self) -> Task<Message> {
        let path = self.active_panel().path.clone();
        let msg = if self.favourites.contains(&path) {
            Msg::StatusFavouriteAlready
        } else {
            self.favourites.push(path.clone());
            Msg::StatusFavouriteAdded
        };
        self.favourite_notice(msg, &path)
    }

    fn remove_favourite(&mut self) -> Task<Message> {
        let path = self.active_panel().path.clone();
        let before = self.favourites.len();
        self.favourites.retain(|favourite| *favourite != path);
        let msg = if self.favourites.len() < before {
            Msg::StatusFavouriteRemoved
        } else {
            Msg::StatusFavouriteNotOne
        };
        self.favourite_notice(msg, &path)
    }

    /// A click on the "access blocked" error: the Full Disk Access page of
    /// System Settings. A launch that fails says so in the status bar.
    #[cfg(target_os = "macos")]
    fn open_privacy_settings(&mut self) {
        self.job_error = None;
        let command = fs::privacy_settings_command();
        if let Err(reason) = self.launcher.launch(&command) {
            let failure = self
                .lang
                .text(Msg::ErrorOpenFailed)
                .replace("{name}", self.lang.text(Msg::StatusSystemSettings))
                .replace("{reason}", &reason);
            self.set_status_error(&failure);
        }
    }

    /// Closes the menu and takes its panel to the highlighted drive, as any
    /// directory change does: a failing read shows its error in the status bar.
    fn go_to_selected_volume(&mut self) -> Task<Message> {
        let Some(menu) = self.volume_menu.take() else {
            return Task::none();
        };
        if menu.selected_trash() {
            return self.open_trash_on(menu.side);
        }
        let target = match menu.volumes.get(menu.selected) {
            Some(volume) => volume.path.clone(),
            None if menu.selected_server().is_some() => {
                let Some(row) = menu
                    .selected_server()
                    .and_then(|index| menu.servers.get(index))
                else {
                    return Task::none();
                };
                row.url.clone()
            }
            None => {
                let Some(favourite) = menu
                    .selected
                    .checked_sub(menu.volumes.len())
                    .and_then(|index| menu.favourites.get(index))
                else {
                    return Task::none();
                };
                if !favourite.present {
                    let text = fill_template(
                        self.lang.text(Msg::ErrorFavouriteGone),
                        &[("{path}", &favourite.path.display().to_string())],
                    );
                    self.notice = None;
                    self.set_status_error(&text);
                    return Task::none();
                }
                favourite.path.clone()
            }
        };
        self.job_error = None;
        self.notice = None;
        self.panels.active = menu.side;
        self.load(menu.side, target, None)
    }

    /// F8 / Shift+F8: ask before deleting. Nothing to act on, or something
    /// else already holding the keyboard or the queue, means nothing happens.
    fn open_delete_dialog(&mut self, permanent: bool) -> Task<Message> {
        if self.jobs.is_busy()
            || self.prompt.is_some()
            || self.conflict_is_open()
            || self.delete_dialog.is_some()
        {
            return Task::none();
        }
        let sources = self.action_sources();
        if sources.is_empty() {
            return Task::none();
        }
        // An archive has no trash: its entries go for good.
        let permanent_on_this_side = permanent || self.panel(self.source_side()).archive.is_some();
        self.job_error = None;
        self.notice = None;
        self.dialog_focus = delete_dialog_view::default_focus(permanent_on_this_side);
        self.delete_dialog = Some(Deletion {
            sources,
            permanent: permanent_on_this_side,
            side: self.source_side(),
        });
        Task::none()
    }

    /// The dialog's subject line: the name for one entry, the count for more.
    ///
    /// A permanent delete also lists the first names, because tagged rows may
    /// lie outside the visible part of the panel and the user is about to lose
    /// them for good.
    fn delete_subject(&self, deletion: &Deletion) -> String {
        const LISTED: usize = 5;
        let name_of = |path: &PathBuf| {
            path.file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default()
        };
        match deletion.sources.as_slice() {
            [only] => self.lang.text(Msg::DeleteOne).replace(
                "{name}",
                &only
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default(),
            ),
            many => {
                let mut lines = vec![self
                    .lang
                    .text(Msg::DeleteMany)
                    .replace("{count}", &many.len().to_string())];
                if deletion.permanent {
                    lines.extend(many.iter().take(LISTED).map(name_of));
                    if many.len() > LISTED {
                        lines.push(
                            self.lang
                                .text(Msg::DeleteMore)
                                .replace("{count}", &(many.len() - LISTED).to_string()),
                        );
                    }
                }
                lines.join("\n")
            }
        }
    }

    /// The dialog was confirmed: start on the first entry.
    fn confirm_delete(&mut self) -> Task<Message> {
        let Some(deletion) = self.delete_dialog.take() else {
            return Task::none();
        };
        if let Some(archive) = self.panel(deletion.side).archive.clone() {
            return self.start_archive_delete(archive, deletion);
        }
        if !deletion.permanent {
            self.last_deletion.clear();
        }
        self.deleting = Some(deletion);
        self.generation = self.generation.wrapping_add(1);
        self.run_delete_row(0)
    }

    /// Deletes the entry at `index` on the blocking pool, or finishes when
    /// there is none. One entry per job, so Escape works between two entries.
    fn run_delete_row(&mut self, index: usize) -> Task<Message> {
        let Some(deletion) = self.deleting.clone() else {
            return Task::none();
        };
        let Some(path) = deletion.sources.get(index).cloned() else {
            let notice = self.moved_to_trash_notice(&deletion);
            return Task::batch([self.end_delete(), notice]);
        };
        let total = deletion.sources.len();
        self.job_progress = Some(fs::transfer::Tick { done: index, total });
        self.jobs.enqueue(jobs::Job {
            kind: jobs::JobKind::Delete,
            path: path.clone(),
            total: Some(total),
        });
        let generation = self.generation;
        let trash = Arc::clone(&self.trash);
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        if deletion.permanent {
                            fs::remove_permanently(&path).map_err(|err| err.to_string())
                        } else {
                            trash.trash(&path)
                        }
                    }),
                    move |outcome| Message::DeleteRowDone {
                        result: outcome.unwrap_or_else(|join| Err(join.to_string())),
                        index,
                        generation,
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    /// Ends the delete, finished, failed or stopped: the tags refer to entries
    /// that may be gone, so they go, and both panels are re-read.
    fn end_delete(&mut self) -> Task<Message> {
        let side = self.deleting.take().map_or(self.source_side(), |d| d.side);
        self.generation = self.generation.wrapping_add(1);
        self.job_progress = None;
        self.panel_mut(side).selection.clear();
        let tasks = [PanelSide::Left, PanelSide::Right].map(|each| {
            let path = self.panel(each).path.clone();
            self.load(each, path, None)
        });
        Task::batch(tasks.into_iter().chain([self.restart_search()]))
    }

    /// Notes that the entry at `index` of a delete went to the trash, for the
    /// key that puts the latest deletion back. A permanent delete has nothing
    /// to put back.
    fn remember_trashed(&mut self, index: usize) {
        let Some(deletion) = self.deleting.as_ref().filter(|d| !d.permanent) else {
            return;
        };
        if let Some(path) = deletion.sources.get(index) {
            self.last_deletion.push(path.clone());
        }
    }

    /// The notice after a delete that moved everything to a trash that can
    /// give it back.
    fn moved_to_trash_notice(&mut self, deletion: &Deletion) -> Task<Message> {
        if deletion.permanent || self.trash.reach() == fs::TrashReach::FinderOnly {
            return Task::none();
        }
        let count = deletion.sources.len().to_string();
        let text = match self
            .keymap
            .shortcut_label(&KeyAction::RestoreLastDeletion.message())
        {
            Some(key) => fill_template(
                self.lang.text(Msg::TrashMovedWithKey),
                &[("{count}", &count), ("{key}", &key)],
            ),
            None => fill_template(self.lang.text(Msg::TrashMoved), &[("{count}", &count)]),
        };
        self.show_notice(text)
    }

    // --- the trash ---

    fn update_trash(&mut self, message: TrashMessage) -> Task<Message> {
        let ctx = ncrs_ops::Ctx {
            trash_rows: self.trash_rows(),
            trash_generation: self.trash_generation,
        };
        let Some(action) = ncrs_ops::update_trash(self.trash_view.as_mut(), message, &ctx) else {
            return Task::none();
        };
        match action {
            TrashAction::Open => self.open_trash_on(self.source_side()),
            TrashAction::Close => {
                self.close_trash();
                release_focus()
            }
            TrashAction::Restore(items) => self.start_restore(items),
            TrashAction::RestoreRowDone {
                result,
                index,
                generation,
            } => self.restore_row_done(result, index, generation),
            TrashAction::RestoreLast => self.restore_last_deletion(),
            TrashAction::LastListed { generation, result } => {
                self.restore_listed_deletion(generation, result)
            }
            TrashAction::OpenInFinder => self.open_trash_in_finder(),
        }
    }

    /// Rows of the trash view that fit the window.
    fn trash_rows(&self) -> usize {
        layout::trash_visible_rows(self.window_size)
    }

    /// What the last row of the drive menu is called, if this build has one.
    fn trash_menu_row(&self) -> Option<Msg> {
        match self.trash.reach() {
            fs::TrashReach::Everything => Some(Msg::TrashTitleEverything),
            fs::TrashReach::OwnDeletions => Some(Msg::TrashTitleOwn),
            fs::TrashReach::FinderOnly => {
                cfg!(target_os = "macos").then_some(Msg::ActionOpenTrashInFinder)
            }
        }
    }

    /// Shows the trash in place of the panel on `side` and reads it. Where the
    /// app cannot read the trash, the Finder opens it instead.
    fn open_trash_on(&mut self, side: PanelSide) -> Task<Message> {
        if self.blocking_overlay_is_open() {
            return Task::none();
        }
        let reach = self.trash.reach();
        if reach == fs::TrashReach::FinderOnly {
            return self.open_trash_in_finder();
        }
        self.context_menu = None;
        self.job_error = None;
        self.notice = None;
        let closed_search = if self.search.open && self.search.side == side {
            self.update_search(SearchMessage::Close)
        } else {
            Task::none()
        };
        self.panels.active = side;
        self.trash_side = side;
        self.trash_view = Some(TrashView::new(reach));
        Task::batch([closed_search, self.list_trash()])
    }

    fn close_trash(&mut self) {
        self.trash_view = None;
        self.trash_generation = self.trash_generation.wrapping_add(1);
    }

    /// Reads the trash on the blocking pool; the answer carries the generation,
    /// so a late one finds the view closed or read again.
    fn list_trash(&mut self) -> Task<Message> {
        if self.trash_view.is_none() {
            return Task::none();
        }
        self.trash_generation = self.trash_generation.wrapping_add(1);
        let generation = self.trash_generation;
        if let Some(view) = self.trash_view.as_mut() {
            view.begin_reading();
        }
        let trash = Arc::clone(&self.trash);
        Task::perform(
            tokio::task::spawn_blocking(move || trash.list()),
            move |outcome| {
                Message::Trash(TrashMessage::Listed {
                    generation,
                    result: outcome.unwrap_or_else(|join| Err(join.to_string())),
                })
            },
        )
    }

    fn trash_panel(&self, side: PanelSide) -> Element<'_, Message> {
        let Some(view) = self.trash_view.as_ref() else {
            return Space::new().into();
        };
        trash_ui::view(trash_ui::Props {
            view,
            visible_rows: self.trash_rows(),
            is_active: self.panels.active == side,
            panel_width: self.window_size.width / 2.0,
            lang: self.lang,
            palette: &self.palette,
            finder_key: self
                .keymap
                .shortcut_label(&KeyAction::OpenTrashInFinder.message()),
        })
        .map(Message::from)
    }

    /// Whether a restore may start: nothing else holds the queue or the keys.
    fn restore_is_blocked(&self) -> bool {
        self.jobs.is_busy()
            || self.prompt.is_some()
            || self.conflict_is_open()
            || self.delete_dialog.is_some()
            || self.transfer_dialog.is_some()
            || self.restoring.is_some()
    }

    /// Puts `items` back, one per job, so Escape works between two entries.
    fn start_restore(&mut self, items: Vec<fs::TrashedItem>) -> Task<Message> {
        if items.is_empty() || self.restore_is_blocked() {
            return Task::none();
        }
        self.job_error = None;
        self.notice = None;
        self.restoring = Some(Restoration {
            items,
            restored: 0,
            skipped: 0,
            rule: None,
        });
        self.generation = self.generation.wrapping_add(1);
        self.run_restore_row(0, false)
    }

    /// Puts the entry at `index` back on the blocking pool, or finishes when
    /// there is none. With `overwrite`, what is in the way goes to the trash
    /// first: nothing is ever deleted for good here.
    fn run_restore_row(&mut self, index: usize, overwrite: bool) -> Task<Message> {
        let Some(restoring) = self.restoring.as_ref() else {
            return Task::none();
        };
        let Some(item) = restoring.items.get(index).cloned() else {
            return self.end_restore();
        };
        let total = restoring.items.len();
        self.job_progress = Some(fs::transfer::Tick { done: index, total });
        self.jobs.enqueue(jobs::Job {
            kind: jobs::JobKind::Restore,
            path: item.original.clone(),
            total: Some(total),
        });
        let generation = self.generation;
        let trash = Arc::clone(&self.trash);
        let sandbox = self.sandbox.clone();
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        restore_one(trash.as_ref(), &sandbox, &item, overwrite)
                    }),
                    move |outcome| {
                        Message::Trash(TrashMessage::RestoreRowDone {
                            result: outcome.unwrap_or_else(|join| {
                                Err(fs::RestoreError::Failed(join.to_string()))
                            }),
                            index,
                            generation,
                        })
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    fn restore_row_done(
        &mut self,
        result: Result<(), fs::RestoreError>,
        index: usize,
        generation: u64,
    ) -> Task<Message> {
        if generation != self.generation {
            return Task::none();
        }
        self.jobs.finish();
        let rule = self.restoring.as_ref().and_then(|restoring| restoring.rule);
        match result {
            Ok(()) => {
                if let Some(restoring) = self.restoring.as_mut() {
                    restoring.restored += 1;
                }
                self.run_restore_row(index + 1, false)
            }
            Err(fs::RestoreError::Taken) => match rule {
                Some(fs::transfer::OnConflict::Overwrite) => self.run_restore_row(index, true),
                Some(_) => self.skip_restore_row(index),
                None => {
                    self.dialog_focus = conflict::OVERWRITE_FOCUS;
                    self.restore_conflict = Some(index);
                    Task::batch([self.close_quick_open(), self.close_command_palette()])
                }
            },
            Err(fs::RestoreError::NotGranted) => {
                let name = self.restore_row_name(index);
                let text = fill_template(
                    self.lang.text(Msg::TrashRestoreNotGranted),
                    &[("{name}", &name)],
                );
                self.set_status_error_with_press(&text, Message::Trash(TrashMessage::OpenInFinder));
                self.end_restore()
            }
            Err(fs::RestoreError::Failed(reason)) => {
                let name = self.restore_row_name(index);
                let params = [("{name}", name.as_str()), ("{reason}", reason.as_str())];
                if cfg!(target_os = "macos") {
                    let text =
                        fill_template(self.lang.text(Msg::TrashRestoreFailedFinder), &params);
                    self.set_status_error_with_press(
                        &text,
                        Message::Trash(TrashMessage::OpenInFinder),
                    );
                } else {
                    let text = fill_template(self.lang.text(Msg::TrashRestoreFailed), &params);
                    self.set_status_error(&text);
                }
                self.end_restore()
            }
        }
    }

    fn restore_row_name(&self, index: usize) -> String {
        self.restoring
            .as_ref()
            .and_then(|restoring| restoring.items.get(index))
            .and_then(|item| item.original.file_name())
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    fn skip_restore_row(&mut self, index: usize) -> Task<Message> {
        if let Some(restoring) = self.restoring.as_mut() {
            restoring.skipped += 1;
        }
        self.run_restore_row(index + 1, false)
    }

    /// The answer to the conflict dialog of a restore.
    fn resume_restore(&mut self, index: usize, choice: ConflictChoice) -> Task<Message> {
        if choice == ConflictChoice::Cancel {
            return self.end_restore();
        }
        if choice.applies_to_all() {
            if let Some(restoring) = self.restoring.as_mut() {
                restoring.rule = Some(choice.conflict());
            }
        }
        match choice.conflict() {
            fs::transfer::OnConflict::Overwrite => self.run_restore_row(index, true),
            fs::transfer::OnConflict::Skip | fs::transfer::OnConflict::Fail => {
                self.skip_restore_row(index)
            }
        }
    }

    /// Ends the restore, finished, failed or stopped: reloads both panels and
    /// the trash, and says what came back unless an error already speaks.
    fn end_restore(&mut self) -> Task<Message> {
        let outcome = self.restoring.take();
        self.restore_conflict = None;
        self.conflict_all = false;
        self.generation = self.generation.wrapping_add(1);
        self.job_progress = None;
        let notice = match outcome {
            Some(done) if self.job_error.is_none() && (done.restored > 0 || done.skipped > 0) => {
                let mut text = fill_template(
                    self.lang.text(Msg::TrashRestored),
                    &[("{count}", &done.restored.to_string())],
                );
                if done.skipped > 0 {
                    text.push_str(&fill_template(
                        self.lang.text(Msg::TrashRestoredLeft),
                        &[("{skipped}", &done.skipped.to_string())],
                    ));
                }
                self.show_notice(text)
            }
            _ => Task::none(),
        };
        let reloads = [PanelSide::Left, PanelSide::Right].map(|each| {
            let path = self.panel(each).path.clone();
            self.load(each, path, None)
        });
        Task::batch(
            reloads
                .into_iter()
                .chain([self.list_trash(), self.restart_search(), notice]),
        )
    }

    /// The key behind "Restore the last deletion": reads the trash, then puts
    /// back what the latest F8 of this session moved there.
    fn restore_last_deletion(&mut self) -> Task<Message> {
        if self.restore_is_blocked() {
            return Task::none();
        }
        if self.last_deletion.is_empty() {
            return self.show_notice(self.lang.text(Msg::TrashNothingToRestore).to_owned());
        }
        self.generation = self.generation.wrapping_add(1);
        let generation = self.generation;
        let trash = Arc::clone(&self.trash);
        let trashed = self.last_deletion.clone();
        Task::perform(
            tokio::task::spawn_blocking(move || {
                trash
                    .list()
                    .map(|listed| newest_entries_from(&listed, &trashed))
            }),
            move |outcome| {
                Message::Trash(TrashMessage::LastListed {
                    generation,
                    result: outcome.unwrap_or_else(|join| Err(join.to_string())),
                })
            },
        )
    }

    /// Puts back the entries the trash still holds of the latest deletion.
    fn restore_listed_deletion(
        &mut self,
        generation: u64,
        result: Result<Vec<fs::TrashedItem>, String>,
    ) -> Task<Message> {
        if generation != self.generation {
            return Task::none();
        }
        let found = match result {
            Ok(found) => found,
            Err(reason) => {
                let text = fill_template(self.lang.text(Msg::TrashError), &[("{reason}", &reason)]);
                self.set_status_error(&text);
                return Task::none();
            }
        };
        // A job started while the trash was read: the deletion stays for the
        // next press.
        if self.restore_is_blocked() {
            return Task::none();
        }
        self.last_deletion.clear();
        if found.is_empty() {
            return self.show_notice(self.lang.text(Msg::TrashNothingToRestore).to_owned());
        }
        self.start_restore(found)
    }

    /// Shows the trash folder in the Finder, where the app cannot list it.
    #[cfg(target_os = "macos")]
    fn open_trash_in_finder(&mut self) -> Task<Message> {
        if let Err(reason) = self.launcher.launch(&fs::trash_in_finder_command()) {
            let text = fill_template(
                self.lang.text(Msg::TrashFinderFailed),
                &[("{reason}", &reason)],
            );
            self.set_status_error(&text);
        }
        Task::none()
    }

    /// Only the Finder has a trash the app cannot list; no other platform
    /// offers the action.
    #[cfg(not(target_os = "macos"))]
    fn open_trash_in_finder(&mut self) -> Task<Message> {
        Task::none()
    }

    /// F7 and Shift+F4: the name prompt for the active panel's folder.
    fn open_prompt(&mut self, prompt: Prompt) -> Task<Message> {
        self.prompt = Some(prompt);
        self.prompt_side = Some(self.panels.active);
        // The field has to be focused or the prompt swallows every
        // keystroke: `TextInput` only takes keys while focused, and
        // giving it an Id does not focus it.
        operation::focus(FIELD_ID)
    }

    /// F3 / F4: the row under the cursor goes to the external program. Tags
    /// are ignored, as in Norton Commander; `..` and directories have nothing
    /// to view or edit. A file inside an archive is unpacked first, and only
    /// viewing works: the copy is thrown away, so an edit would be lost.
    fn open_external(&mut self, kind: fs::OpenKind) -> Task<Message> {
        let target = match self.open_search_view() {
            Some(search) => search.cursor_target().filter(|(path, _)| !path.is_dir()),
            None => self
                .active_panel()
                .selected_entry()
                .filter(|entry| !entry.is_parent && !entry.is_dir)
                .map(|entry| (entry.path.clone(), None)),
        };
        let Some((path, line)) = target else {
            return Task::none();
        };
        // A file on a server is fetched, never opened in place: the path is an
        // address, and the program would get nothing it can open.
        if let Some(source) = RemotePath::parse(&path) {
            return match kind {
                fs::OpenKind::Edit => {
                    let text = self.lang.text(Msg::StatusRemoteReadOnly).to_owned();
                    self.set_status_error(&text);
                    Task::none()
                }
                fs::OpenKind::View => self.view_from_server(source),
            };
        }
        let in_archive = fs::archive::locate_in_archive(&path)
            .filter(|location| !location.inner.is_empty())
            .map(|location| location.archive);
        match (in_archive, kind) {
            (Some(_), fs::OpenKind::Edit) => {
                let text = self.lang.text(Msg::StatusArchiveReadOnly).to_owned();
                self.set_status_error(&text);
                Task::none()
            }
            (Some(archive), fs::OpenKind::View) => self.view_from_archive(path, archive),
            (None, _) => {
                self.launch_external(kind, path, line, CopyOf::Nothing);
                Task::none()
            }
        }
    }

    /// Starts unpacking `source`, a file in `archive`, for the viewer. The
    /// viewer starts when the copy is there, see `view_extracted`.
    fn view_from_archive(&mut self, source: PathBuf, archive: PathBuf) -> Task<Message> {
        let shown = source.clone();
        self.start_view_copy(archive, shown, jobs::JobKind::Extract, move |slot, tx| {
            let mut progress = fs::transfer::Reporting::new(tx);
            fs::archive::extract_for_view(&source, slot, &mut progress)
        })
    }

    /// Starts fetching `source`, a file on a server, for the viewer. The copies
    /// of one server are kept together under its root address, as those of an
    /// archive are under the archive.
    fn view_from_server(&mut self, source: RemotePath) -> Task<Message> {
        let pool = Arc::clone(&self.remote);
        let (key, shown) = (source.server().root_path(), source.to_path_buf());
        self.start_view_copy(key, shown, jobs::JobKind::Copy, move |slot, tx| {
            let mut progress = fs::transfer::Reporting::new(tx);
            fs::remote::transfer::download_for_view(&pool, &source, slot, &mut progress)
        })
    }

    /// The job behind F3 on an entry that is not on the disk: makes a slot for
    /// the copy under `group`, runs `work` on the blocking pool to fill it, and
    /// reports as `ViewExtracted`.
    fn start_view_copy(
        &mut self,
        group: PathBuf,
        shown: PathBuf,
        kind: jobs::JobKind,
        work: impl FnOnce(&Path, &mpsc::UnboundedSender<fs::transfer::Tick>) -> std::io::Result<PathBuf>
            + Send
            + 'static,
    ) -> Task<Message> {
        // A transfer or delete under way, or a dialog about to start one, owns
        // the queue and `generation`; unpacking beside it would lose its result.
        if self.jobs.is_busy()
            || self.transfer.is_some()
            || self.deleting.is_some()
            || self.delete_dialog.is_some()
            || self.transfer_dialog.is_some()
            || self.conflict_is_open()
        {
            let text = self.lang.text(Msg::StatusArchiveViewBusy).to_owned();
            return self.show_notice(text);
        }
        let made = self
            .view_copies
            .as_mut()
            .and_then(|copies| copies.slot(&group).ok());
        let Some(slot) = made else {
            let text = self
                .lang
                .text(if group_is_server(&group) {
                    Msg::ErrorRemoteViewUnavailable
                } else {
                    Msg::ErrorArchiveViewUnavailable
                })
                .to_owned();
            self.set_status_error(&text);
            return Task::none();
        };
        self.job_error = None;
        self.notice = None;
        self.job_done = 0;
        self.job_progress = None;
        let progress_tx = self.progress_sender();
        let generation = self.generation;
        self.extracting = Some(Extracting {
            archive: group,
            slot: slot.clone(),
        });
        self.jobs.enqueue(jobs::Job {
            kind,
            path: shown,
            total: None,
        });
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking({
                        let unpack_into = slot.clone();
                        move || work(&unpack_into, &progress_tx)
                    }),
                    move |outcome| {
                        let result = match outcome {
                            Ok(Ok(copy)) => Ok(copy),
                            Ok(Err(err)) => Err(RowFailure::from_io(err)),
                            Err(join) => Err(RowFailure::Other(join.to_string())),
                        };
                        Message::ViewExtracted {
                            generation,
                            slot,
                            result,
                        }
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    /// The copy for the viewer is there, or unpacking it failed.
    fn view_extracted(
        &mut self,
        generation: u64,
        slot: PathBuf,
        result: Result<PathBuf, RowFailure>,
    ) -> Task<Message> {
        if generation != self.generation {
            // The unpacking thread removed the slot itself when it failed.
            if result.is_ok() {
                self.discard_view_slot(&slot);
            }
            return Task::none();
        }
        self.jobs.finish();
        self.job_progress = None;
        let finished = self.extracting.take();
        match result {
            Ok(copy) => {
                let still_open = finished
                    .as_ref()
                    .is_some_and(|job| self.panel_shows(&job.archive));
                if let (true, Some(job)) = (still_open, finished) {
                    let origin = if group_is_server(&job.archive) {
                        CopyOf::Server
                    } else {
                        CopyOf::Archive
                    };
                    self.launch_external(fs::OpenKind::View, copy, None, origin);
                } else {
                    self.discard_view_slot(&slot);
                }
            }
            Err(failure) => {
                if let Some(copies) = self.view_copies.as_mut() {
                    copies.forget_slot(&slot);
                }
                let text = match failure {
                    RowFailure::Refused(refusal) => self.refusal_text(refusal),
                    RowFailure::UnsafeName(name) => fill_template(
                        self.lang.text(Msg::ErrorRemoteUnsafeName),
                        &[("{name}", &name)],
                    ),
                    RowFailure::Conflict(reason) | RowFailure::Other(reason) => reason,
                };
                self.set_status_error(&text);
            }
        }
        Task::none()
    }

    fn discard_view_slot(&mut self, slot: &Path) {
        if let Some(copies) = self.view_copies.as_mut() {
            copies.discard(slot);
        }
    }

    /// Whether a panel is in `place`: an archive, or the root address of the
    /// server whose folder it shows.
    fn panel_shows(&self, place: &Path) -> bool {
        [PanelSide::Left, PanelSide::Right].into_iter().any(|side| {
            let panel = self.panel(side);
            panel.archive.as_deref() == Some(place)
                || panel
                    .remote()
                    .is_some_and(|server| server.root_path() == place)
        })
    }

    fn refusal_text(&self, refusal: fs::archive::SevenZipRefusal) -> String {
        self.lang
            .text(match refusal {
                fs::archive::SevenZipRefusal::Encrypted => Msg::ErrorArchiveEncrypted,
                fs::archive::SevenZipRefusal::DictionaryTooLarge => {
                    Msg::ErrorArchiveDictionaryTooLarge
                }
            })
            .to_owned()
    }

    /// Reads both panels again, except those inside an archive or on a server.
    fn reload_local_panels(&mut self) -> Task<Message> {
        let reloads = [PanelSide::Left, PanelSide::Right].map(|side| {
            let panel = self.panel(side);
            (!panel.is_virtual()).then(|| (side, panel.path.clone()))
        });
        Task::batch(
            reloads
                .into_iter()
                .flatten()
                .map(|(side, path)| self.load(side, path, None)),
        )
    }

    /// Alt+F5: the name prompt for a new archive in the other panel's folder,
    /// with the name of the single entry, or of the folder they are in, as a
    /// start.
    fn open_pack_prompt(&mut self) -> Task<Message> {
        if self.jobs.is_busy()
            || self.prompt.is_some()
            || self.conflict_is_open()
            || self.delete_dialog.is_some()
            || self.transfer_dialog.is_some()
            || self.transfer.is_some()
        {
            return Task::none();
        }
        let source_side = self.source_side();
        // An archive or a server in the other panel cannot take the new
        // archive, so it goes beside the files; the field shows where.
        let target_side = if self.panel(source_side.other()).is_virtual()
            || self.panel(source_side.other()).is_hit_list()
        {
            source_side
        } else {
            source_side.other()
        };
        if self.panel(source_side).is_virtual() {
            let text = self.lang.text(Msg::StatusPackUnavailable).to_owned();
            self.set_status_error(&text);
            return Task::none();
        }
        let sources = self.action_sources();
        if sources.is_empty() {
            return Task::none();
        }
        self.job_error = None;
        self.notice = None;
        let target = self.panel(target_side).path.clone();
        let hit_list = self.panel(source_side).hit_list.as_ref();
        self.prompt = Some(match hit_list {
            Some(list) => {
                let name = hit_archive_name(&list.query)
                    .unwrap_or_else(|| suggested_archive_name(&sources));
                Prompt::pack_hits(target, sources, list.scope.clone(), &name)
            }
            None => {
                let name = suggested_archive_name(&sources);
                Prompt::pack(target, sources, &name)
            }
        });
        self.prompt_side = Some(target_side);
        operation::focus(FIELD_ID)
    }

    fn toggle_keep_folders(&mut self) -> Task<Message> {
        if let Some(prompt) = self.prompt.as_mut().filter(|prompt| !prompt.busy()) {
            prompt.toggle_keep_folders();
        }
        Task::none()
    }

    /// Enter in the pack prompt, once its name passed `Prompt::validate`: the
    /// prompt closes and one job writes the archive.
    fn start_pack(&mut self) -> Task<Message> {
        if self.jobs.is_busy() {
            let text = self.lang.text(Msg::StatusArchiveWriteBusy).to_owned();
            return self.show_notice(text);
        }
        let Some(prompt) = self.prompt.take() else {
            return Task::none();
        };
        let target_side = self.prompt_side.take().unwrap_or(self.panels.active);
        let archive = prompt.archive_path();
        let name = archive
            .file_name()
            .map(|file_name| file_name.to_string_lossy().into_owned())
            .unwrap_or_default();
        let folder = archive.parent().map(Path::to_path_buf).unwrap_or_default();
        let sources = prompt.sources().to_vec();
        let write = ArchiveWrite {
            side: target_side.other(),
            what: ArchiveWriteKind::Pack { name, folder },
        };
        let packed = archive.clone();
        let keep_under = prompt.kept_folders_under().map(Path::to_path_buf);
        let numbered: Option<Vec<(PathBuf, String)>> = (keep_under.is_some()
            || fs::flat_names::from_several_folders(&sources))
        .then(|| fs::flat_names::archive_names(&sources, keep_under.as_deref()));
        self.start_archive_write(
            jobs::JobKind::Pack,
            archive,
            write,
            move |progress| match numbered {
                Some(items) => fs::archive::pack_named(&items, &packed, progress),
                None => fs::archive::pack(&sources, &packed, progress),
            },
        )
    }

    /// F5 with an archive, or a folder in one, as the target: one job rewrites
    /// the archive with the selection added. `Ask` cannot ask per file here, so
    /// it stops at the first name in the way and says what the dialog offers.
    fn begin_copy_into_archive(
        &mut self,
        location: fs::archive::ArchiveLocation,
        sources: Vec<PathBuf>,
        policy: Policy,
    ) -> Task<Message> {
        let write = ArchiveWrite {
            side: self.source_side(),
            what: ArchiveWriteKind::CopyIn,
        };
        let conflict = policy.on_conflict();
        let fs::archive::ArchiveLocation { archive, inner, .. } = location;
        let shown = archive.clone();
        self.start_archive_write(jobs::JobKind::Copy, shown, write, move |progress| {
            fs::archive::add(&archive, &inner, &sources, conflict, progress)
        })
    }

    /// The delete dialog of a panel inside `archive` was confirmed.
    fn start_archive_delete(&mut self, archive: PathBuf, deletion: Deletion) -> Task<Message> {
        let write = ArchiveWrite {
            side: deletion.side,
            what: ArchiveWriteKind::Delete,
        };
        let shown = archive.clone();
        self.start_archive_write(jobs::JobKind::Delete, shown, write, move |progress| {
            let entries = deletion
                .sources
                .iter()
                .map(|path| {
                    fs::archive::locate_in_archive(path)
                        .filter(|place| place.archive == archive && !place.inner.is_empty())
                        .map(|place| place.inner)
                        .ok_or_else(|| {
                            std::io::Error::new(
                                std::io::ErrorKind::InvalidInput,
                                "the entry is not in this archive",
                            )
                        })
                })
                .collect::<std::io::Result<Vec<_>>>()?;
            fs::archive::delete(&archive, &entries, progress)
        })
    }

    /// Runs `work` on the blocking pool as the one job of the queue. It reports
    /// as `ArchiveWritten`; Escape closes the progress channel, which makes the
    /// writer drop its temporary file and leave the archive as it was.
    fn start_archive_write(
        &mut self,
        kind: jobs::JobKind,
        shown: PathBuf,
        write: ArchiveWrite,
        work: impl FnOnce(&mut fs::transfer::Reporting<'_>) -> std::io::Result<fs::archive::WriteReport>
            + Send
            + 'static,
    ) -> Task<Message> {
        if self.jobs.is_busy()
            || self.transfer.is_some()
            || self.deleting.is_some()
            || self.extracting.is_some()
            || self.archive_write.is_some()
        {
            let text = self.lang.text(Msg::StatusArchiveWriteBusy).to_owned();
            return self.show_notice(text);
        }
        self.job_error = None;
        self.notice = None;
        self.job_done = 0;
        self.job_progress = None;
        let progress_tx = self.progress_sender();
        self.generation = self.generation.wrapping_add(1);
        let generation = self.generation;
        self.archive_write = Some(write);
        self.jobs.enqueue(jobs::Job {
            kind,
            path: shown,
            total: None,
        });
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        let mut progress = fs::transfer::Reporting::new(&progress_tx);
                        work(&mut progress)
                    }),
                    move |outcome| {
                        let result = match outcome {
                            Ok(Ok(report)) => Ok(report),
                            Ok(Err(err)) => Err(RowFailure::from_io(err)),
                            Err(join) => Err(RowFailure::Other(join.to_string())),
                        };
                        Message::ArchiveWritten { result, generation }
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    fn archive_written(
        &mut self,
        generation: u64,
        result: Result<fs::archive::WriteReport, RowFailure>,
    ) -> Task<Message> {
        if generation != self.generation {
            return Task::none();
        }
        self.jobs.finish();
        self.job_progress = None;
        let Some(write) = self.archive_write.take() else {
            return Task::none();
        };
        self.generation = self.generation.wrapping_add(1);
        let notice = match result {
            Ok(report) => Some(self.written_text(&write, report)),
            Err(failure) => {
                let text = self.write_failure_text(&write, failure);
                self.set_status_error(&text);
                None
            }
        };
        let reload = self.end_archive_write(&write);
        match notice {
            Some(text) => Task::batch([self.show_notice(text), reload]),
            None => reload,
        }
    }

    fn written_text(&self, write: &ArchiveWrite, report: fs::archive::WriteReport) -> String {
        let mut text = match &write.what {
            ArchiveWriteKind::Pack { name, .. } => {
                fill_template(self.lang.text(Msg::StatusPacked), &[("{name}", name)])
            }
            ArchiveWriteKind::CopyIn => self.lang.text(Msg::StatusArchiveCopiedIn).to_owned(),
            ArchiveWriteKind::Delete => self.lang.text(Msg::StatusArchiveDeleted).to_owned(),
        };
        for (count, template) in [
            (report.skipped, Msg::StatusArchiveSkipped),
            (report.kept_existing, Msg::StatusArchiveKept),
        ] {
            if count > 0 {
                text.push_str(&fill_template(
                    self.lang.text(template),
                    &[("{count}", &count.to_string())],
                ));
            }
        }
        text
    }

    fn write_failure_text(&self, write: &ArchiveWrite, failure: RowFailure) -> String {
        match failure {
            RowFailure::Refused(refusal) => self.refusal_text(refusal),
            RowFailure::Conflict(detail) if write.what == ArchiveWriteKind::CopyIn => {
                fill_template(
                    self.lang.text(Msg::ErrorArchiveNameTaken),
                    &[("{detail}", &detail)],
                )
            }
            RowFailure::Conflict(reason)
            | RowFailure::UnsafeName(reason)
            | RowFailure::Other(reason) => fill_template(
                self.lang.text(Msg::ErrorArchiveWriteFailed),
                &[("{reason}", &reason)],
            ),
        }
    }

    /// Ends the bookkeeping of a write that finished, failed or was stopped:
    /// the tags of a delete refer to entries that may be gone, and both panels
    /// are read again, the new archive of a pack selected.
    fn end_archive_write(&mut self, write: &ArchiveWrite) -> Task<Message> {
        if write.what == ArchiveWriteKind::Delete {
            self.panel_mut(write.side).selection.clear();
        }
        let tasks = [PanelSide::Left, PanelSide::Right].map(|each| {
            let path = self.panel(each).path.clone();
            let select = match &write.what {
                ArchiveWriteKind::Pack { name, folder } if path == *folder => Some(name.clone()),
                ArchiveWriteKind::Pack { .. }
                | ArchiveWriteKind::CopyIn
                | ArchiveWriteKind::Delete => None,
            };
            self.load(each, path, select)
        });
        Task::batch(tasks.into_iter().chain([self.restart_search()]))
    }

    /// Stops the running job, see `Message::AbortJob`.
    fn abort_job(&mut self) -> Task<Message> {
        if !self.jobs.abort_running() {
            return Task::none();
        }
        self.drop_progress_channel();
        if self.extracting.is_some() {
            self.end_extraction();
            Task::none()
        } else if let Some(write) = self.archive_write.take() {
            self.generation = self.generation.wrapping_add(1);
            self.end_archive_write(&write)
        } else if self.deleting.is_some() {
            self.end_delete()
        } else if self.restoring.is_some() {
            self.end_restore()
        } else {
            self.end_transfer()
        }
    }

    /// Both halves of the progress channel go together: a sender kept without
    /// its receiver makes every later transfer fail on a closed channel.
    /// Dropping the receiver is also what stops a blocking copy, whose next
    /// tick cannot be sent.
    fn drop_progress_channel(&mut self) {
        self.job_done = 0;
        self.job_progress = None;
        self.progress_rx = None;
        self.progress_tx = None;
    }

    /// Ends the bookkeeping of an unpacking whose job was stopped; its result
    /// is ignored if it still arrives. The slot stays known: the unpacking
    /// thread removes it when it notices the stop, and if it finished first,
    /// the copy goes with the others of its archive.
    fn end_extraction(&mut self) {
        self.generation = self.generation.wrapping_add(1);
        self.extracting = None;
    }

    /// A panel has left `archive`: the copies made for the viewer go, unless
    /// the other panel is still in it. A running unpacking stops first.
    fn drop_view_copies_of(&mut self, archive: &Path) {
        if self.panel_shows(archive) {
            return;
        }
        if self
            .extracting
            .as_ref()
            .is_some_and(|extracting| extracting.archive == archive)
        {
            self.jobs.abort_running();
            self.drop_progress_channel();
            self.end_extraction();
        }
        if let Some(copies) = self.view_copies.as_mut() {
            copies.release(archive);
        }
    }

    /// Hands `path` to the program for `kind`, at `line` when the program
    /// takes one. `from` says whether `path` is a temporary copy made for
    /// viewing, and of what.
    fn launch_external(
        &mut self,
        kind: fs::OpenKind,
        path: PathBuf,
        line: Option<u64>,
        from: CopyOf,
    ) {
        self.job_error = None;
        self.notice = None;
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();
        let executable = fs::could_execute(&path);
        let Some(command) = fs::open_command(&self.open_programs, kind, &path, executable, line)
        else {
            let message = if from != CopyOf::Nothing {
                // The edit key is refused in an archive and on a server, so it
                // is not offered.
                fill_template(
                    self.lang.text(if from == CopyOf::Server {
                        Msg::ErrorRemoteViewExecutable
                    } else {
                        Msg::ErrorArchiveViewExecutable
                    }),
                    &[("{name}", &name)],
                )
            } else {
                self.open_refused_text(&name)
            };
            self.set_status_error(&message);
            return;
        };
        if let Err(reason) = self.launcher.launch(&command) {
            let message = self
                .lang
                .text(Msg::ErrorOpenFailed)
                .replace("{name}", &name)
                .replace("{reason}", &reason);
            self.set_status_error(&message);
        }
    }

    fn open_refused_text(&self, name: &str) -> String {
        let keys: Vec<String> = [
            Message::OpenExternal(fs::OpenKind::View),
            Message::OpenExternal(fs::OpenKind::Edit),
        ]
        .iter()
        .filter_map(|opener| self.keymap.shortcut_label(opener))
        .collect();
        if keys.is_empty() {
            fill_template(
                self.lang.text(Msg::ErrorOpenRefusedNoKey),
                &[("{name}", name)],
            )
        } else {
            fill_template(
                self.lang.text(Msg::ErrorOpenRefused),
                &[("{name}", name), ("{keys}", &keys.join("/"))],
            )
        }
    }

    /// The status line for an entry that could not be deleted. A failed trash
    /// points at the permanent-delete key rather than falling back to it:
    /// deleting for good is the user's decision, not the app's.
    fn delete_failure(&self, index: usize, reason: &str) -> String {
        let permanent = self.deleting.as_ref().is_some_and(|d| d.permanent);
        let name = self
            .deleting
            .as_ref()
            .and_then(|d| d.sources.get(index))
            .and_then(|p| p.file_name())
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();
        let permanent_key = self
            .keymap
            .shortcut_label(&Message::Delete { permanent: true });
        let template = match (permanent, &permanent_key) {
            (true, _) => Msg::ErrorDeleteFailed,
            (false, Some(_)) => Msg::ErrorTrashFailed,
            (false, None) => Msg::ErrorTrashFailedNoKey,
        };
        fill_template(
            self.lang.text(template),
            &[
                ("{name}", &name),
                ("{reason}", reason),
                ("{key}", permanent_key.as_deref().unwrap_or_default()),
            ],
        )
    }

    /// F5 / F6: resolve what to transfer and ask before anything starts.
    ///
    /// The rows are resolved here rather than at the confirmation because a
    /// conflict dialog pauses the operation, and by then the selection may
    /// have moved. With a transfer already running the key brings its progress
    /// back instead: one transfer at a time owns the conflict state.
    fn open_transfer_dialog(&mut self, kind: TransferKind) -> Task<Message> {
        self.open_transfer_dialog_to(kind, None)
    }

    /// As [`Self::open_transfer_dialog`], with the target field preset to
    /// `target` instead of the other panel's folder.
    fn open_transfer_dialog_to(
        &mut self,
        kind: TransferKind,
        preset: Option<PathBuf>,
    ) -> Task<Message> {
        if self.transfer.is_some() {
            self.transfer_mask_visible = true;
            return Task::none();
        }
        if self.extracting.is_some() {
            let text = self.lang.text(Msg::StatusArchiveViewBusy).to_owned();
            return self.show_notice(text);
        }
        if self.prompt.is_some()
            || self.conflict_is_open()
            || self.delete_dialog.is_some()
            || self.transfer_dialog.is_some()
            || self.archive_write.is_some()
        {
            return Task::none();
        }
        let sources = self.action_sources();
        if sources.is_empty() {
            return Task::none();
        }
        if preset.is_none() && self.panel(self.source_side().other()).is_hit_list() {
            let text = self.lang.text(Msg::StatusHitListNotAFolder).to_owned();
            self.set_status_error(&text);
            return Task::none();
        }
        self.job_error = None;
        self.notice = None;
        self.transfer_dialogs_opened = self.transfer_dialogs_opened.wrapping_add(1);
        let base = preset.unwrap_or_else(|| self.panel(self.source_side().other()).path.clone());
        let remote_home = RemotePath::parse(&base).and_then(|place| {
            self.remote
                .session(place.server())
                .map(|session| session.home().to_owned())
        });
        let hit_scope = self
            .panel(self.source_side())
            .hit_list
            .as_ref()
            .map(|list| list.scope.clone());
        let dialog = TransferDialog::new(self.transfer_dialogs_opened, kind, sources, base)
            .with_remote_home(remote_home)
            .with_hit_scope(hit_scope);
        let scan = scan_task(&dialog);
        let conflicts = conflicts_task(&dialog);
        self.transfer_dialog = Some(dialog);
        let target = transfer_ui::TARGET_FIELD_ID;
        Task::batch([
            scan,
            conflicts,
            operation::focus(target).chain(operation::move_cursor_to_end(target)),
        ])
    }

    fn update_transfer_dialog(&mut self, message: TransferDialogMessage) -> Task<Message> {
        let Some(action) = ncrs_ops::update_transfer_dialog(&mut self.transfer_dialog, message)
        else {
            return Task::none();
        };
        match action {
            TransferAction::CountConflicts => self
                .transfer_dialog
                .as_ref()
                .map_or_else(Task::none, conflicts_task),
            TransferAction::Closed => release_focus(),
            TransferAction::Confirm => self.confirm_transfer(),
            TransferAction::HideProgress => {
                self.transfer_mask_visible = false;
                Task::none()
            }
            TransferAction::ShowProgress => {
                self.transfer_mask_visible = self.transfer.is_some();
                Task::none()
            }
        }
    }

    /// Enter in the confirmation: refuse a target that cannot take the
    /// selection, with the reason in the dialog, or start the transfer.
    fn confirm_transfer(&mut self) -> Task<Message> {
        let Some(open) = self.transfer_dialog.as_mut() else {
            return Task::none();
        };
        let target =
            match transfer_dialog::validate(open.kind(), open.sources(), &open.target_path()) {
                Ok(target) => target,
                Err(refusal) => {
                    open.refuse(refusal);
                    return Task::none();
                }
            };
        let (kind, sources, policy) = (open.kind(), open.sources().to_vec(), open.policy());
        if !self.target_server_is_reachable(&target) {
            return Task::none();
        }
        self.transfer_dialog = None;
        Task::batch([
            release_focus(),
            self.start_validated_transfer(kind, sources, target, policy),
        ])
    }

    /// Says so in the status bar when `target` is on a server that is not
    /// connected.
    fn target_server_is_reachable(&mut self, target: &Path) -> bool {
        let Some(place) = RemotePath::parse(target) else {
            return true;
        };
        if self.remote.is_connected(place.server()) {
            return true;
        }
        let text = fill_template(
            self.lang.text(Msg::ErrorRemoteDisconnected),
            &[("{server}", &place.server().to_string())],
        );
        self.set_status_error(&text);
        false
    }

    fn queue_dropped_file(&mut self, path: PathBuf) -> Task<Message> {
        self.drop_hover = false;
        self.dropped_files.push(path);
        self.drop_generation = self.drop_generation.wrapping_add(1);
        let generation = self.drop_generation;
        Task::perform(async { tokio::time::sleep(DROP_SETTLE).await }, move |()| {
            Message::DropSettled(generation)
        })
    }

    fn copy_settled_drop(&mut self, generation: u64) -> Task<Message> {
        if generation != self.drop_generation || self.dropped_files.is_empty() {
            return Task::none();
        }
        let paths = std::mem::take(&mut self.dropped_files);
        self.copy_external_files_into_active_panel(paths)
    }

    /// A job runs or a dialog is open, so nothing may start a transfer into
    /// the active panel.
    fn transfer_into_panel_is_blocked(&self) -> bool {
        self.transfer.is_some()
            || self.extracting.is_some()
            || self.prompt.is_some()
            || self.conflict_is_open()
            || self.delete_dialog.is_some()
            || self.transfer_dialog.is_some()
            || self.archive_write.is_some()
    }

    /// Copies files that come from outside the panels (dropped from another
    /// app, pasted from the clipboard) into the active panel. They carry no
    /// cursor position or modifier, so the target is always the active panel
    /// and the transfer always a copy.
    fn copy_external_files_into_active_panel(&mut self, paths: Vec<PathBuf>) -> Task<Message> {
        if self.active_panel().is_hit_list() {
            let text = self.lang.text(Msg::StatusHitListNotAFolder).to_owned();
            self.set_status_error(&text);
            return Task::none();
        }
        if self.transfer_into_panel_is_blocked() {
            let text = self.lang.text(Msg::StatusDropBusy).to_owned();
            return self.show_notice(text);
        }
        let panel_path = self.active_panel().path.clone();
        match transfer_dialog::validate(TransferKind::Copy, &paths, &panel_path) {
            Err(refusal) => {
                let text = transfer_ui::refusal_text(refusal, self.lang).to_owned();
                self.set_status_error(&text);
                Task::none()
            }
            Ok(resolved) if !self.target_server_is_reachable(&resolved) => Task::none(),
            Ok(resolved) => {
                self.job_error = None;
                self.notice = None;
                self.start_validated_transfer(TransferKind::Copy, paths, resolved, Policy::Ask)
            }
        }
    }

    /// The prompt is a pack or a paste with a name that passed validation:
    /// neither creates an entry by itself, each starts its own job.
    fn valid_prompt_has_its_own_job(&self) -> bool {
        self.prompt.as_ref().is_some_and(|prompt| {
            matches!(prompt.kind(), PromptKind::Pack | PromptKind::Paste)
                && prompt.validate().is_ok()
        })
    }

    fn start_prompt_job(&mut self) -> Task<Message> {
        match self.prompt.as_ref().map(Prompt::kind) {
            Some(PromptKind::Pack) => self.start_pack(),
            Some(PromptKind::Paste) => self.submit_paste(),
            Some(PromptKind::CreateDir | PromptKind::CreateFile) | None => Task::none(),
        }
    }

    /// Cmd+V / Ctrl+V: reads the system clipboard, then `paste_content` decides.
    fn paste_from_clipboard(&mut self) -> Task<Message> {
        if self.transfer_into_panel_is_blocked() {
            let text = self.lang.text(Msg::StatusPasteBusy).to_owned();
            return self.show_notice(text);
        }
        (self.read_clipboard)().map(Message::ClipboardRead)
    }

    /// What the clipboard held: files are copied like a drop, a picture or
    /// text first asks for the name of the file it becomes.
    fn paste_content(&mut self, content: Option<PastedContent>) -> Task<Message> {
        match content {
            None => {
                let text = self.lang.text(Msg::StatusClipboardEmpty).to_owned();
                self.show_notice(text)
            }
            Some(PastedContent::Files(files)) => self.copy_external_files_into_active_panel(files),
            Some(pasted) => self.ask_for_pasted_file_name(pasted),
        }
    }

    fn ask_for_pasted_file_name(&mut self, pasted: PastedContent) -> Task<Message> {
        if self.active_panel().is_hit_list() {
            let text = self.lang.text(Msg::StatusHitListNotAFolder).to_owned();
            self.set_status_error(&text);
            return Task::none();
        }
        let Some(kind) = pasted.kind() else {
            return Task::none();
        };
        if self.transfer_into_panel_is_blocked() {
            let text = self.lang.text(Msg::StatusPasteBusy).to_owned();
            return self.show_notice(text);
        }
        let panel = self.active_panel();
        let name = clipboard_paste::pasted_name(
            kind,
            chrono::Local::now().naive_local(),
            self.lang,
            |candidate| panel.entries.iter().any(|entry| entry.name == candidate),
        );
        let parent = panel.path.clone();
        self.pending_paste = Some(pasted);
        self.open_prompt(Prompt::paste(parent, name))
    }

    /// The name of a pasted picture or text is confirmed: write it into a
    /// private folder and copy it into the panel the way F5 would.
    fn submit_paste(&mut self) -> Task<Message> {
        let (Some(prompt), Some(bytes)) = (
            self.prompt.as_ref(),
            self.pending_paste
                .as_ref()
                .and_then(PastedContent::file_bytes),
        ) else {
            return Task::none();
        };
        let name = prompt.name().trim().to_owned();
        let written = tempfile::Builder::new()
            .prefix("ncrs-paste-")
            .tempdir()
            .and_then(|folder| {
                let file = folder.path().join(&name);
                std::fs::write(&file, bytes)?;
                Ok((folder, file))
            });
        let (folder, file) = match written {
            Ok(staging) => staging,
            Err(error) => {
                self.set_prompt_error_text(&error.to_string());
                return Task::none();
            }
        };
        self.prompt = None;
        self.prompt_side = None;
        self.pending_paste = None;
        self.paste_staging = Some(folder);
        self.copy_external_files_into_active_panel(vec![file])
    }

    /// Files from another app held over the window outline the active panel;
    /// a row dragged over the other panel outlines that one.
    fn is_drop_target(&self, side: PanelSide) -> bool {
        (self.drop_hover && side == self.panels.active) || self.panels.drag_hovers_side(side)
    }

    /// A cursor only where a drag from a panel is over a panel; files held over
    /// the window from another app keep the OS cursor.
    fn drag_cursor(&self, side: PanelSide) -> Option<mouse::Interaction> {
        self.panels.drag_cursor(side, self.modifiers)
    }

    #[cfg(any(target_os = "macos", target_os = "windows"))]
    fn drag_out_started(&mut self, started: Result<(), String>) -> Task<Message> {
        if let Err(reason) = started {
            let text = fill_template(
                self.lang.text(Msg::ErrorDragOutFailed),
                &[("{reason}", &reason)],
            );
            self.set_status_error(&text);
        }
        Task::none()
    }

    fn end_panel_drag(&mut self) -> Option<PanelDrag> {
        self.input.lock().panel_drag_armed = false;
        self.panels.drag.take()
    }

    /// The pointer left the window with files held: hands them to the system
    /// drag, which takes over the mouse until the drop.
    #[cfg(any(target_os = "macos", target_os = "windows"))]
    fn start_drag_out(&mut self) -> Task<Message> {
        self.end_panel_drag();
        let sources = self.action_sources();
        if sources.is_empty() {
            return Task::none();
        }
        if !sources.iter().all(|path| is_file_on_local_disk(path)) {
            let text = self.lang.text(Msg::StatusDragOutLocalOnly).to_owned();
            return self.show_notice(text);
        }
        window::latest()
            .and_then(move |id| {
                let files = sources.clone();
                window::run(id, move |window| crate::drag_out::start(window, files))
            })
            .map(Message::DragOutStarted)
    }

    /// Puts the tagged files, else the one under the cursor, on the system
    /// clipboard as files. Only files of this computer's disk can go there.
    fn copy_files_to_clipboard(&mut self) -> Task<Message> {
        if self.overlay_is_open() {
            return Task::none();
        }
        let sources = self.action_sources();
        if sources.is_empty() {
            return Task::none();
        }
        if !sources.iter().all(|path| is_file_on_local_disk(path)) {
            let text = self
                .lang
                .text(Msg::StatusClipboardFilesLocalOnly)
                .to_owned();
            return self.show_notice(text);
        }
        if let Err(reason) = (self.write_clipboard_files)(&sources) {
            let text = fill_template(
                self.lang.text(Msg::ErrorClipboardWriteFailed),
                &[("{reason}", &reason)],
            );
            self.set_status_error(&text);
            return Task::none();
        }
        self.job_error = None;
        let text = match sources.len() {
            1 => self
                .lang
                .text(Msg::StatusFilesCopiedToClipboardOne)
                .to_owned(),
            count => fill_template(
                self.lang.text(Msg::StatusFilesCopiedToClipboardMany),
                &[("{count}", &count.to_string())],
            ),
        };
        self.show_notice(text)
    }

    /// Starts a transfer whose target passed `transfer_dialog::validate`.
    fn start_validated_transfer(
        &mut self,
        kind: TransferKind,
        sources: Vec<PathBuf>,
        target: PathBuf,
        policy: Policy,
    ) -> Task<Message> {
        let needs_numbering = fs::flat_names::from_several_folders(&sources)
            && fs::flat_names::flat_names(&sources)
                .iter()
                .zip(&sources)
                .any(|(name, source)| name.as_deref() != source.file_name());
        let into_archive = fs::archive::locate_in_archive(&target);
        if needs_numbering && (into_archive.is_some() || RemotePath::parse(&target).is_some()) {
            let text = self.lang.text(Msg::StatusNumberingNeedsFolder).to_owned();
            self.set_status_error(&text);
            return Task::none();
        }
        if let Some(location) = into_archive {
            return self.begin_copy_into_archive(location, sources, policy);
        }
        self.begin_transfer(kind, sources, target, policy)
    }

    /// Starts the first row of a confirmed transfer and shows its progress.
    fn begin_transfer(
        &mut self,
        kind: TransferKind,
        sources: Vec<PathBuf>,
        target: PathBuf,
        policy: Policy,
    ) -> Task<Message> {
        let names = if fs::flat_names::from_several_folders(&sources) {
            fs::flat_names::flat_names(&sources)
                .into_iter()
                .map(Option::unwrap_or_default)
                .collect()
        } else {
            Vec::new()
        };
        let transfer = Transfer {
            kind,
            sources,
            target,
            names,
        };
        self.transfer = Some(transfer.clone());
        self.conflict_rule = policy.standing_rule();
        self.generation = self.generation.wrapping_add(1);
        self.transfer_mask_visible = true;
        self.transfer_rows_done = 0;
        self.run_from(transfer, 0, policy.on_conflict())
    }

    /// Whether the progress mask is up over a running transfer.
    fn progress_mask_is_open(&self) -> bool {
        self.transfer_mask_visible && self.transfer.is_some()
    }

    /// What the progress mask shows: how far, counted in rows when there are
    /// several (the tick only knows the row it is in) and in the tick's items
    /// when a single entry, maybe a whole folder, is the transfer.
    fn progress_mask(&self) -> Option<transfer_ui::Progress<'_>> {
        let transfer = self
            .transfer
            .as_ref()
            .filter(|_| self.transfer_mask_visible)?;
        let (done, total) = if transfer.sources.len() > 1 {
            (self.transfer_rows_done, transfer.sources.len())
        } else {
            self.job_progress
                .map_or((0, 0), |tick| (tick.done, tick.total))
        };
        Some(transfer_ui::Progress {
            kind: transfer.kind,
            target: &transfer.target,
            done,
            total,
        })
    }

    /// Answers a conflict and remembers an "all" answer, so the next
    /// conflict does not ask again.
    fn answer_conflict(&mut self, clicked: ConflictChoice) -> Task<Message> {
        if let Some(index) = self.restore_conflict.take() {
            let choice = self.conflict_answer(clicked);
            return self.resume_restore(index, choice);
        }
        let Some(pending) = self.pending_conflict.take() else {
            return Task::none();
        };
        let choice = self.conflict_answer(clicked);
        // Cancel ends the transfer; the rows already done stay done.
        if choice == ConflictChoice::Cancel {
            return self.end_transfer();
        }
        if choice.applies_to_all() {
            self.conflict_rule = Some(choice.conflict());
        }
        // The task is returned, not dropped: dropping it would leave the
        // transfer standing still after the user answered, which is the one
        // thing the dialog must not do.
        self.resume_transfer(pending, choice)
    }

    /// The file the open conflict dialog asks about.
    fn conflict_name(&self) -> String {
        let path = match (self.pending_conflict.as_ref(), self.restore_conflict) {
            (Some(pending), _) => pending.transfer.sources.get(pending.index),
            (None, Some(index)) => self
                .restoring
                .as_ref()
                .and_then(|restoring| restoring.items.get(index))
                .map(|item| &item.original),
            (None, None) => None,
        };
        let renamed = self
            .pending_conflict
            .as_ref()
            .and_then(|pending| pending.transfer.name_in_target(pending.index));
        renamed
            .as_deref()
            .or_else(|| path?.file_name())
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    /// What the dialog's button means: the tick belonged to the question just
    /// answered, so it goes with it.
    fn conflict_answer(&mut self, clicked: ConflictChoice) -> ConflictChoice {
        let choice = if self.conflict_all {
            clicked.for_all()
        } else {
            clicked
        };
        self.conflict_all = false;
        choice
    }

    /// Whether a name that is taken waits for an answer, in a transfer or in
    /// a restore from the trash.
    fn conflict_is_open(&self) -> bool {
        self.pending_conflict.is_some() || self.restore_conflict.is_some()
    }

    /// Continues a transfer from `index` under the given conflict rule.
    fn resume_transfer(
        &mut self,
        pending: PendingConflict,
        choice: ConflictChoice,
    ) -> Task<Message> {
        let PendingConflict { transfer, index } = pending;
        self.transfer = Some(transfer.clone());
        self.run_from(transfer, index, choice.conflict())
    }

    /// Ends the transfer, finished or not: forgets it and its "for all" rule, and
    /// reloads both panels, since a move changes the source directory as well as
    /// the target and rows before a failure or a cancel are already done.
    fn end_transfer(&mut self) -> Task<Message> {
        self.transfer = None;
        self.transfer_mask_visible = false;
        self.transfer_rows_done = 0;
        self.conflict_rule = None;
        self.generation = self.generation.wrapping_add(1);
        let source_side = self.source_side();
        let target_side = source_side.other();
        let source_path = self.panel(source_side).path.clone();
        let target_path = self.panel(target_side).path.clone();
        Task::batch([
            self.load(source_side, source_path, None),
            self.load(target_side, target_path, None),
            self.restart_search(),
        ])
    }

    fn progress_sender(&mut self) -> mpsc::UnboundedSender<fs::transfer::Tick> {
        match &self.progress_tx {
            Some(tx) => tx.clone(),
            None => {
                let (created, receiver) = tokio::sync::mpsc::unbounded_channel();
                self.progress_tx = Some(created.clone());
                self.progress_rx = Some(Arc::new(tokio::sync::Mutex::new(receiver)));
                created
            }
        }
    }

    /// Runs the selected plan entries on the blocking pool, as one job. Escape
    /// closes the progress channel, which stops the run between two files.
    fn run_reorganisation(&mut self, selection: Vec<PlannedItem>) -> Task<Message> {
        if self.jobs.is_busy() || selection.is_empty() {
            return Task::none();
        }
        let Some(access) = self.filing.as_ref().and_then(FilingModule::plan_access) else {
            self.set_status_error(INDEX_NOT_OPEN);
            return Task::none();
        };
        let progress_tx = self.progress_sender();
        let total = selection.len();
        self.job_progress = Some(fs::transfer::Tick { done: 0, total });
        self.jobs.enqueue(jobs::Job {
            kind: jobs::JobKind::Reorganise,
            path: selection
                .first()
                .map(|entry| entry.location.clone())
                .unwrap_or_default(),
            total: Some(total),
        });
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        let mut progress = fs::transfer::Reporting::new(&progress_tx);
                        access.execute(&selection, &mut progress)
                    }),
                    |joined| {
                        Message::ReorganisationExecuted(
                            joined.unwrap_or_else(|join| Err(join.to_string())),
                        )
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    /// One job files every planned document. Waits for a running job instead
    /// of queueing behind it, and is asked for again on the next tick.
    fn run_filing(&mut self) -> Task<Message> {
        if self.jobs.is_busy() {
            self.filing_due = true;
            return Task::none();
        }
        self.filing_due = false;
        let Some(access) = self.filing.as_ref().and_then(FilingModule::filing_access) else {
            return Task::none();
        };
        let progress_tx = self.progress_sender();
        self.jobs.enqueue(jobs::Job {
            kind: jobs::JobKind::File,
            path: PathBuf::new(),
            total: None,
        });
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        let mut progress = fs::transfer::Reporting::new(&progress_tx);
                        access.file_planned(&mut progress)
                    }),
                    |joined| {
                        Message::DocumentsFiled(joined.unwrap_or_else(|join| Err(join.to_string())))
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    fn documents_filed(&mut self, result: Result<FilingSummary, String>) -> Task<Message> {
        self.jobs.finish();
        self.job_progress = None;
        match result {
            Ok(summary) if summary.filed + summary.reviewed > 0 => {
                let text = fill_template(
                    self.lang.text(Msg::StatusDocumentsFiled),
                    &[
                        ("{filed}", &summary.filed.to_string()),
                        ("{reviewed}", &summary.reviewed.to_string()),
                    ],
                );
                self.show_notice(text)
            }
            Ok(_) => Task::none(),
            Err(detail) => {
                self.set_status_error(&detail);
                Task::none()
            }
        }
    }

    fn reorganisation_executed(
        &mut self,
        result: Result<ExecutionSummary, String>,
    ) -> Task<Message> {
        self.jobs.finish();
        self.job_progress = None;
        match result {
            Ok(summary) => {
                let text = self
                    .lang
                    .text(Msg::StatusReorganised)
                    .replace("{moved}", &summary.moved.to_string())
                    .replace("{skipped}", &summary.skipped.to_string());
                Task::batch([self.show_notice(text), self.replan_if_open()])
            }
            Err(detail) => {
                self.set_status_error(&detail);
                self.replan_if_open()
            }
        }
    }

    fn undo_reorganisation(&mut self) -> Task<Message> {
        if self.jobs.is_busy() {
            return Task::none();
        }
        let Some(access) = self.filing.as_ref().and_then(FilingModule::plan_access) else {
            self.set_status_error(INDEX_NOT_OPEN);
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.undo_last()),
            |joined| {
                Message::ReorganisationUndone(joined.unwrap_or_else(|join| Err(join.to_string())))
            },
        )
    }

    fn reorganisation_undone(
        &mut self,
        result: Result<Option<execute::UndoReport>, String>,
    ) -> Task<Message> {
        match result {
            Ok(Some(report)) => {
                let text = self
                    .lang
                    .text(Msg::StatusReorganisationUndone)
                    .replace("{moved}", &report.undone.to_string())
                    .replace("{skipped}", &report.left.to_string());
                Task::batch([self.show_notice(text), self.replan_if_open()])
            }
            Ok(None) => {
                let text = self.lang.text(Msg::StatusNothingToUndo).to_string();
                self.show_notice(text)
            }
            Err(detail) => {
                self.set_status_error(&detail);
                Task::none()
            }
        }
    }

    /// The files moved, so an open plan is out of date.
    fn replan_if_open(&mut self) -> Task<Message> {
        let Some(view) = self.reorganisation.as_mut() else {
            return Task::none();
        };
        view.begin_planning();
        self.reorganisation_generation = self.reorganisation_generation.wrapping_add(1);
        self.run_planning()
    }

    /// Runs the rows from `index`, on the blocking pool, reporting progress.
    ///
    /// One row at a time rather than the whole list, so a conflict can be
    /// answered between two files and the queue stays one job.
    fn run_from(
        &mut self,
        transfer: Transfer,
        index: usize,
        conflict: fs::transfer::OnConflict,
    ) -> Task<Message> {
        let Some(source) = transfer.sources.get(index).cloned() else {
            return self.end_transfer();
        };

        // One channel per transfer, but the receiving half is created once for
        // the app (see `progress_rx`) and reused, so `subscription` does not
        // have to hand out a fresh receiver after every row.
        let progress_tx = self.progress_sender();

        let generation = self.generation;
        let target = transfer.target.clone();
        let name_in_target = transfer.name_in_target(index);
        let pool = Arc::clone(&self.remote);
        let job = jobs::Job {
            kind: transfer.kind.job_kind(),
            path: child_path(
                &target,
                name_in_target
                    .as_deref()
                    .unwrap_or_else(|| source.file_name().unwrap_or_default()),
            ),
            total: None,
        };
        // One row per job keeps a conflict answerable between two files.
        self.jobs.enqueue(job.clone());
        if let Some(task) = self.jobs.start_next(|_| {
            // transfer::run is blocking filesystem work, so it goes on the
            // blocking pool — the same reason read_directory does.
            Task::perform(
                tokio::task::spawn_blocking({
                    let from = source.clone();
                    let to = target.clone();
                    let kind = transfer.kind;
                    let renamed = name_in_target.clone();
                    move || {
                        if let Some(name) = renamed {
                            return crate::fs::transfer::run_reporting_as(
                                &from,
                                &to.join(name),
                                kind,
                                conflict,
                                &progress_tx,
                            );
                        }
                        // Reports as it goes, so the bar moves during a long
                        // copy rather than jumping at the end. A server on
                        // either side is the SFTP layer's.
                        fs::remote::transfer::run_reporting(
                            &pool,
                            &from,
                            &to,
                            kind,
                            conflict,
                            &progress_tx,
                        )
                        .unwrap_or_else(|| {
                            crate::fs::transfer::run_reporting(
                                &from,
                                &to,
                                kind,
                                conflict,
                                &progress_tx,
                            )
                        })
                    }
                }),
                move |outcome| {
                    // Two failures collapse into one string here: the join error
                    // means the blocking task died, the other means the copy
                    // itself failed. The dialog cannot tell them apart anyway.
                    let result = match outcome {
                        Ok(Ok(_)) => Ok(transfer.clone()),
                        // The kind travels with the message rather than being
                        // formatted into it: the dialog has to recognise a
                        // conflict, and it cannot do that from wording.
                        Ok(Err(e)) => Err(RowFailure::from_io(e)),
                        // A dead blocking task is not a conflict. Its reason is
                        // a string already, so it is shown as one.
                        Err(join) => Err(RowFailure::Other(join.to_string())),
                    };
                    Message::TransferRowDone {
                        result,
                        index,
                        generation,
                    }
                },
            )
        }) {
            return task;
        }
        Task::none()
    }

    /// What the status bar shows about the queue: the running job, how far
    /// along it is, how many wait, and whether Escape will stop it.
    fn job_status(&self) -> Option<statusbar::JobStatus> {
        let running = self.jobs.running()?;
        // The tick from the blocking thread, not a row counter: F5 on one
        // directory with fifty thousand files is one row and fifty thousand
        // items, and the bar has to say the second number.
        let (done, total) = match self.job_progress {
            Some(tick) => (tick.done, tick.total),
            None => (0, running.total.unwrap_or(0)),
        };
        Some(statusbar::JobStatus {
            label: self.lang.text(running.kind.label()),
            done,
            total,
            waiting: self.jobs.waiting(),
            // Escape belongs to the prompt while one is open, so the hint is
            // only true when nothing else is claiming the key.
            abortable: self.prompt.is_none() && !self.conflict_is_open(),
        })
    }

    /// Records why a job failed. The status bar reads it; nothing else does, so
    /// it is a string rather than a typed error — the layer that knew the kind
    /// already wrote the wording.
    fn set_status_error(&mut self, reason: &str) {
        self.job_error = Some(reason.to_string());
        self.job_error_press = None;
        self.notice = None;
    }

    /// An error the user can press, for instance to open the trash in the Finder.
    fn set_status_error_with_press(&mut self, reason: &str, press: Message) {
        self.set_status_error(reason);
        self.job_error_press = Some(press);
    }

    /// Shows a validation failure in the open prompt.
    fn set_prompt_error(&mut self, reason: &'static str) {
        if let Some(prompt) = self.prompt.as_mut() {
            prompt.set_validation_error(reason);
        }
    }

    /// Wording for a failed create, in the active language. Deciding here
    /// rather than in the filesystem layer keeps `fs` free of user-facing text,
    /// and the two failures need different advice: a taken name means pick
    /// another, a missing parent means the panel has gone stale.
    fn prompt_error(&self, err: &CreateDirError) -> String {
        use std::io::ErrorKind;
        let lang = self.lang;
        let name = self.prompt_name();
        match err.io_error().map(|e| e.kind()) {
            Some(ErrorKind::AlreadyExists) => {
                lang.text(Msg::ErrorMkdirTaken).replace("{name}", &name)
            }
            Some(ErrorKind::NotFound) => lang.text(Msg::ErrorParentMissing).to_string(),
            _ => lang
                .text(Msg::ErrorMkdirFailed)
                .replace("{name}", &name)
                .replace("{reason}", &err.to_string()),
        }
    }

    /// The name currently in the prompt, or an empty string.
    fn prompt_name(&self) -> String {
        self.prompt
            .as_ref()
            .map(|p| p.name().to_string())
            .unwrap_or_default()
    }

    /// Shows a filesystem failure in the open prompt.
    fn set_prompt_error_text(&mut self, reason: &str) {
        if let Some(prompt) = self.prompt.as_mut() {
            prompt.set_error(reason.to_string());
        }
    }

    fn set_prompt_busy(&mut self, busy: bool) {
        if let Some(prompt) = self.prompt.as_mut() {
            prompt.set_busy(busy);
        }
    }

    /// A panel inside an archive can be read and copied from, nothing else.
    fn apply_unless_refused(&mut self, message: Message) -> Task<Message> {
        if asks_for_hermes(&message) {
            if self.hermes_is_restarting() {
                let text = self.lang.text(Msg::StatusHermesRestarting).to_owned();
                return self.show_notice(text);
            }
            if self.hermes_is_off() {
                return self.explain_hermes_is_off();
            }
        }
        let panel = self.panel(self.source_side());
        if panel.is_hit_list() && is_not_offered_in_hit_list(&message) {
            return Task::none();
        }
        match archive_refusal(panel, &message).or_else(|| remote_refusal(panel, &message)) {
            Some(refusal) => {
                let text = self.lang.text(refusal).to_string();
                self.set_status_error(&text);
                Task::none()
            }
            None => self.apply(message),
        }
    }

    fn toggle_shortcuts(&self) -> ncrs_search::ToggleShortcuts {
        let label = |toggle| self.keymap.shortcut_label(&Message::Search(toggle));
        ncrs_search::ToggleShortcuts {
            case: label(SearchMessage::ToggleCase),
            whole_word: label(SearchMessage::ToggleWholeWord),
            regex: label(SearchMessage::ToggleRegex),
        }
    }

    /// The search view, while it is up.
    fn open_search_view(&self) -> Option<&SearchView> {
        self.search.view.as_ref().filter(|_| self.search_has_keys())
    }

    /// The search view is up and its panel is the active one: the keys and the
    /// file actions are the search's. After Tab or a click on the other panel
    /// they are that panel's again, while the search stays on screen.
    /// The trash view is up and its panel is the active one: its keys are
    /// the cursor's.
    fn trash_has_keys(&self) -> bool {
        self.trash_view.is_some() && self.panels.active == self.trash_side
    }

    fn search_has_keys(&self) -> bool {
        self.search.open && self.panels.active == self.search.side
    }

    /// The panel that file actions take their files from: the one the search
    /// view stands in for, else the active one.
    fn source_side(&self) -> PanelSide {
        if self.search_has_keys() {
            self.search.side
        } else if self.trash_has_keys() {
            self.trash_side
        } else {
            self.panels.active
        }
    }

    fn apply_window_size(&mut self, size: Size) {
        self.window_size = size;
        self.resize_command_palette(size);
        self.visible_rows = layout::visible_rows(size);
        self.search.resize(size);
        self.panels.left.ensure_visible(self.visible_rows);
        self.panels.right.ensure_visible(self.visible_rows);
    }

    /// Puts what an earlier run remembered on top of the fresh start. The first
    /// listing of each panel arrives sorted the default way and is re-sorted by
    /// `apply_sorted_listing`, which compares its `sorted_by` with the panel's.
    fn apply_session_state(&mut self, saved: &SessionState) {
        self.panels.left.sort = saved.left.sort_key();
        self.panels.right.sort = saved.right.sort_key();
        self.panels.left.history = saved.left.history();
        self.panels.right.history = saved.right.history();
        // Not checked for existence: a favourite on a drive that is not
        // plugged in now is still wanted when it is.
        self.favourites = saved.favourites.iter().map(PathBuf::from).collect();
        if let Some(side) = saved.active {
            self.panels.active = side;
        }
        if let Some(size) = saved.window_size() {
            self.apply_window_size(size);
        }
        // Starting is not a change: nothing is written until something differs.
        self.session_scheduled = self.session_state();
    }

    /// What would be remembered if ncrs quit now.
    fn session_state(&self) -> SessionState {
        let record = |panel: &PanelState| {
            // A restart must not unpack a large tar.zst before the panel shows
            // anything, and the archive may be gone or replaced by then, so a
            // panel inside one is remembered as standing on the archive file.
            let (path, cursor) = match panel.archive.as_deref().and_then(archive_file_place) {
                Some((folder, name)) => (session_state::record_path(folder), Some(name)),
                // A server is never written to the file; the panel comes back
                // in the home folder.
                None if panel.remote().is_some() => (session_state::record_path(&self.home), None),
                None => (
                    session_state::record_path(
                        panel
                            .hit_list
                            .as_ref()
                            .map_or(&panel.path, |list| &list.return_to),
                    ),
                    panel
                        .selected_entry()
                        .filter(|entry| !entry.is_parent)
                        .and_then(|entry| entry.name.to_str().map(str::to_owned)),
                ),
            };
            PanelRecord {
                path,
                sort: panel.sort.column,
                descending: panel.sort.descending,
                back: session_state::record_history(panel.history.back()),
                forward: session_state::record_history(panel.history.forward()),
                cursor,
            }
        };
        let current = WindowSize {
            width: self.window_size.width,
            height: self.window_size.height,
        };
        // A minimised window reports no usable size; the last good one stays.
        let window = if current.restorable().is_some() {
            Some(current)
        } else {
            self.session_scheduled.window
        };
        SessionState {
            version: session_state::STATE_VERSION,
            active: Some(self.panels.active),
            favourites: session_state::record_paths(&self.favourites),
            window,
            left: record(&self.panels.left),
            right: record(&self.panels.right),
        }
    }

    /// Plans a write when the remembered state differs from the last one
    /// planned. Debounced: the timer carries the generation, so a resize drag
    /// or a quick walk through folders writes once, after it settles.
    fn schedule_session_save(&mut self) -> Task<Message> {
        if self.state_path.is_none() {
            return Task::none();
        }
        let snapshot = self.session_state();
        if snapshot == self.session_scheduled {
            return Task::none();
        }
        self.session_scheduled = snapshot;
        self.session_save_generation = self.session_save_generation.wrapping_add(1);
        let generation = self.session_save_generation;
        Task::perform(
            async { tokio::time::sleep(SESSION_SAVE_DELAY).await },
            move |()| Message::SaveSessionState(generation),
        )
    }

    /// The write a timer is entitled to: only the newest generation, and only
    /// with a state path.
    fn due_session_state(&self, generation: u64) -> Option<(PathBuf, SessionState)> {
        if generation != self.session_save_generation {
            return None;
        }
        Some((self.state_path.clone()?, self.session_scheduled.clone()))
    }

    /// What the search reads from the app.
    fn search_ctx(&self) -> ncrs_search::Ctx {
        ncrs_search::Ctx {
            window_size: self.window_size,
            side_is_remote: self.panel(self.search.side).remote().is_some(),
            has_keys: self.search_has_keys(),
            index: self
                .filing
                .as_ref()
                .and_then(FilingModule::query_access)
                .map(|access| Arc::new(access) as Arc<dyn ncrs_search::SearchIndex>),
        }
    }

    /// The rows of the search after its filters changed what they offer.
    fn refresh_search_rows(&mut self) {
        self.search.resize(self.window_size);
    }

    fn focus_search_field(&self) -> Task<Message> {
        self.search.focus_field()
    }

    /// Shows the search view in place of the active panel, below that panel's
    /// directory. A view kept from before keeps its fields and options, and
    /// searches anew, so no result is older than the files. Pressed while it is
    /// up, the key moves to the next field.
    fn open_search(&mut self) -> Task<Message> {
        if self.blocking_overlay_is_open() {
            return Task::none();
        }
        if self.search.open {
            if self.search_has_keys() {
                if let Some(view) = self.search.view.as_mut() {
                    view.focused = view.focused.next();
                }
            } else {
                self.panels.active = self.search.side;
            }
            return self.focus_search_field();
        }
        self.context_menu = None;
        self.job_error = None;
        self.notice = None;
        let side = self.panels.active;
        if self.trash_side == side {
            self.close_trash();
        }
        let root = self.panel(side).path.clone();
        self.search.side = side;
        self.search.open = true;
        let indexed = self.panel(side).remote().is_none()
            && self
                .filing
                .as_ref()
                .and_then(FilingModule::query_access)
                .is_some();
        let kinds = Arc::clone(&self.kinds.catalog);
        let view = self
            .search
            .view
            .get_or_insert_with(|| SearchView::new(root.clone()));
        view.root = root;
        view.filters = if indexed {
            view.filters
                .take()
                .or_else(|| Some(SearchFilters::new(kinds)))
        } else {
            None
        };
        self.refresh_search_rows();
        let search = self.restart_search();
        Task::batch([self.focus_search_field(), search])
    }

    /// The search opened with the words typed in the box that asked.
    fn open_search_with_words(&mut self, text: String) -> Task<Message> {
        let opened = self.open_search();
        if let Some(view) = self.search.view.as_mut() {
            view.query = text;
            view.focused = SearchField::Query;
        }
        Task::batch([opened, self.restart_search()])
    }

    /// Searches again now, for when the files changed under the results.
    fn restart_search(&mut self) -> Task<Message> {
        let ctx = self.search_ctx();
        self.search.restart(&ctx).map(Message::Search)
    }

    /// Lists the hits of the search in the panel on `target`. The files are
    /// read on the blocking pool; the panel shows itself loading meanwhile.
    fn open_hit_list(&mut self, target: PanelSide) -> Task<Message> {
        let Some(view) = self.open_search_view() else {
            return Task::none();
        };
        if view.results.is_empty() {
            return Task::none();
        }
        let paths: Vec<PathBuf> = view.results.iter().map(|file| file.path.clone()).collect();
        let query = view.query.trim().to_owned();
        let scope = view.root.clone();
        let origin = self.search.side;
        self.context_menu = None;
        self.job_error = None;
        self.notice = None;
        let closed = if target == origin {
            self.close_search()
        } else {
            if self.trash_view.is_some() && self.trash_side == target {
                self.close_trash();
            }
            Task::none()
        };
        let panel = self.panel_mut(target);
        let return_to = panel
            .hit_list
            .as_ref()
            .map_or_else(|| panel.path.clone(), |list| list.return_to.clone());
        let request_id = panel.begin_hit_list(HitList {
            query,
            scope,
            return_to,
        });
        self.panels.active = target;
        Task::batch([closed, read_hit_files(target, request_id, paths)])
    }

    /// Reads the files of the list again: the rows that vanished drop out.
    fn refresh_hit_list(&mut self, side: PanelSide) -> Task<Message> {
        let panel = self.panel_mut(side);
        let paths: Vec<PathBuf> = panel
            .entries
            .iter()
            .map(|entry| entry.path.clone())
            .collect();
        let request_id = panel.begin_load();
        read_hit_files(side, request_id, paths)
    }

    fn update_hit_list(&mut self, message: HitListMessage) -> Task<Message> {
        match message {
            HitListMessage::Read {
                side,
                request_id,
                entries,
            } => {
                let rows = self.visible_rows;
                let panel = self.panel_mut(side);
                if panel.request_id == request_id && panel.is_hit_list() {
                    panel.apply_hit_entries(entries, rows);
                }
                Task::none()
            }
            HitListMessage::BackToSearch => {
                if self.jobs.is_busy() {
                    return Task::none();
                }
                let side = self.panels.active;
                self.leave_hit_list(side, true)
            }
            HitListMessage::Close(side) => self.leave_hit_list(side, false),
            HitListMessage::ShowOnOtherSide => self.show_hit_on_other_side(),
            HitListMessage::RemoveFromList => {
                let rows = self.visible_rows;
                let panel = self.active_panel_mut();
                if !panel.is_hit_list() {
                    return Task::none();
                }
                let mut paths: Vec<PathBuf> = panel
                    .entries
                    .iter()
                    .filter(|entry| panel.selection.is_tagged(&entry.path))
                    .map(|entry| entry.path.clone())
                    .collect();
                if paths.is_empty() {
                    paths.extend(panel.selected_entry().map(|entry| entry.path.clone()));
                }
                panel.remove_hits(&paths, rows);
                Task::none()
            }
        }
    }

    /// Drops the list of `side` and shows the folder it came from. With
    /// `search` the search comes back, with the fields it was left with.
    fn leave_hit_list(&mut self, side: PanelSide, search: bool) -> Task<Message> {
        let Some(list) = self.panel_mut(side).drop_hit_list() else {
            return Task::none();
        };
        self.context_menu = None;
        let load = self.load(side, list.return_to, None);
        if !search || self.search.view.is_none() {
            return load;
        }
        if self.search.open {
            self.panels.active = self.search.side;
            return load;
        }
        self.search.open = true;
        self.panels.active = self.search.side;
        self.refresh_search_rows();
        let restarted = self.restart_search();
        Task::batch([load, restarted, self.focus_search_field()])
    }

    /// Shows the file under the cursor in its folder on the other side. The
    /// list stays.
    fn show_hit_on_other_side(&mut self) -> Task<Message> {
        let side = self.panels.active;
        let target = match self.open_search_view() {
            Some(search) => search.cursor_target().map(|(path, _)| path),
            None => self
                .panel(side)
                .selected_entry()
                .map(|entry| entry.path.clone()),
        };
        let Some(path) = target else {
            return Task::none();
        };
        let (Some(folder), Some(name)) = (
            path.parent().map(PathBuf::from),
            path.file_name()
                .map(|name| name.to_string_lossy().into_owned()),
        ) else {
            return Task::none();
        };
        let other = side.other();
        let closed = if self.search.open && self.search.side == other {
            self.close_search()
        } else {
            Task::none()
        };
        if self.trash_view.is_some() && self.trash_side == other {
            self.close_trash();
        }
        self.panel_mut(other).drop_hit_list();
        self.panels.active = other;
        let load = self.load(other, folder, Some(name));
        Task::batch([closed, load])
    }

    fn close_search(&mut self) -> Task<Message> {
        self.search.close().map(Message::Search)
    }

    /// The report page after the search handed its criteria over.
    fn hand_search_to_reports(
        &mut self,
        unsaved: Option<Draft>,
        report: Option<SavedQueryId>,
    ) -> Task<Message> {
        let closed = self.close_search();
        let opened = self.open_saved_queries();
        if let Some(view) = self.saved_queries.as_mut() {
            if let Some(draft) = unsaved {
                view.prefill(draft);
            }
            if let Some(id) = report {
                view.select_when_loaded(id);
            }
        }
        Task::batch([closed, opened])
    }

    /// The search opened on `spec`, in place of the reports page. With a
    /// `report` the search changes that one.
    fn open_search_for(&mut self, spec: &QuerySpec, report: Option<SavedQueryId>) -> Task<Message> {
        self.saved_queries = None;
        let opened = self.open_search();
        if let Some(view) = self.search.view.as_mut() {
            view.query = spec.full_text.clone().unwrap_or_default();
            view.focused = SearchField::Query;
            if let Some(filters) = view.filters.as_mut() {
                match report {
                    Some(id) => filters.edit_report(id, spec),
                    None => filters.start_from(spec),
                }
            }
        }
        self.refresh_search_rows();
        Task::batch([opened, self.restart_search()])
    }

    fn update_panel(&mut self, message: PanelMessage) -> Task<Message> {
        let overlay_is_open = self.overlay_is_open();
        let context_menu_is_open = self.context_menu.is_some();
        let pointer = self.input.lock().pointer;
        let ctx = ncrs_files::Ctx {
            visible_rows: self.visible_rows,
            window_size: self.window_size,
            modifiers: self.modifiers,
            is_context_click: is_context_click(self.modifiers),
            pointer,
            overlay_is_open,
            context_menu_is_open,
            clock: &*self.clock,
            folder_sizes: &self.folder_sizes,
            nearest_existing_directory: session_state::nearest_existing_directory,
        };
        let (task, actions) = ncrs_files::update(&mut self.panels, message, &ctx);
        let mapped = task.map(Message::Panel);
        let acted: Vec<_> = actions
            .into_iter()
            .map(|action| self.run_panel_action(action))
            .collect();
        Task::batch(std::iter::once(mapped).chain(acted))
    }

    /// What the panels asked for because it reaches outside the panels.
    fn run_panel_action(&mut self, action: ncrs_files::Action) -> Task<Message> {
        use ncrs_files::Action;
        match action {
            Action::Load { side, path, select } => self.load(side, path, select),
            Action::MarkHistoryStep(side) => {
                self.panel_mut(side).mark_history_step();
                Task::none()
            }
            Action::ClearMessages => {
                self.job_error = None;
                self.notice = None;
                Task::none()
            }
            Action::OpenContextMenu {
                side,
                index,
                pointer,
            } => {
                self.open_context_menu(side, index, Some(pointer));
                Task::none()
            }
            Action::ContextMenuAt { side, index } => {
                self.update(Message::ContextMenuAt { side, index })
            }
            Action::CloseContextMenu => {
                self.context_menu = None;
                Task::none()
            }
            Action::CloseMenuOfReloaded(side) => {
                self.close_menu_of_reloaded(side);
                Task::none()
            }
            Action::DropViewCopies(place) => {
                self.drop_view_copies_of(&place);
                Task::none()
            }
            Action::StopFolderSizeRunIfLeft(side) => {
                self.stop_folder_size_run_if_left(side);
                Task::none()
            }
            Action::DragArmed(armed) => {
                self.input.lock().panel_drag_armed = armed;
                Task::none()
            }
            #[cfg(any(target_os = "macos", target_os = "windows"))]
            Action::StartDragOut => self.start_drag_out(),
            Action::OpenTransferDialog(kind) => self.open_transfer_dialog_to(kind, None),
            Action::OpenSelected => self.update(Message::Panel(PanelMessage::OpenSelected)),
            Action::CloseSettings => self.close_settings(),
        }
    }

    fn update_search(&mut self, message: SearchMessage) -> Task<Message> {
        if !self.search.open {
            return Task::none();
        }
        let ctx = self.search_ctx();
        // Using the view makes its panel the active one, unless the keys it
        // asks for are not its own.
        if ncrs_search::activates_panel(&message)
            && !(ncrs_search::needs_keys(&message) && !ctx.has_keys)
        {
            self.panels.active = self.search.side;
        }
        let (task, asked) = ncrs_search::update(&mut self.search, message, &ctx);
        let mapped = task.map(Message::Search);
        match asked {
            Some(action) => Task::batch([mapped, self.run_search_action(action)]),
            None => mapped,
        }
    }

    /// What the search asked for because it reaches outside the search.
    fn run_search_action(&mut self, action: ncrs_search::Action) -> Task<Message> {
        match action {
            ncrs_search::Action::Close => self.close_search(),
            ncrs_search::Action::OpenHitList(side) => self.open_hit_list(side),
            ncrs_search::Action::ActivateCursor => self.activate_search_cursor(),
            ncrs_search::Action::OpenContextMenu => {
                self.open_search_context_menu();
                Task::none()
            }
            ncrs_search::Action::HandToReports { unsaved, report } => {
                let draft = unsaved.map(|spec| Draft {
                    name: String::new(),
                    spec,
                });
                self.hand_search_to_reports(draft, report)
            }
        }
    }

    /// Enter on a result: the file is shown in the other panel.
    fn activate_search_cursor(&mut self) -> Task<Message> {
        let Some((path, _)) = self.open_search_view().and_then(SearchView::cursor_target) else {
            return Task::none();
        };
        let (Some(directory), Some(file)) = (path.parent(), path.file_name()) else {
            return Task::none();
        };
        let name = file.to_string_lossy().into_owned();
        self.load(
            self.search.side.other(),
            directory.to_path_buf(),
            Some(name),
        )
    }

    /// Cmd/Ctrl+P: lists the files below the active panel's directory. Pressed
    /// while the box is up, it only gives the field the focus again.
    fn open_quick_open(&mut self) -> Task<Message> {
        let focus = operation::focus(quick_open_ui::QUICK_OPEN_ID);
        if self.quick_open.is_some() {
            return focus;
        }
        if self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.context_menu = None;
        let root = self.active_panel().path.clone();
        self.quick_open_walk_generation = self.quick_open_walk_generation.wrapping_add(1);
        let generation = self.quick_open_walk_generation;
        let walk = fs::search::all_files(
            root.clone(),
            stays_on_file_system(&root),
            QUICK_OPEN_FILE_LIMIT,
        );
        let (task, handle) = Task::run(
            search_events(walk, generation, quick_open_batch),
            std::convert::identity,
        )
        .abortable();
        self.quick_open_walk = Some(handle.abort_on_drop());
        let documents_enabled = self.document_finder().is_some();
        self.quick_open = Some(QuickOpen::new(root, generation).with_documents(documents_enabled));
        Task::batch([focus, task])
    }

    fn update_rule_suggestions(&mut self, message: RuleSuggestionsMessage) -> Task<Message> {
        match message {
            RuleSuggestionsMessage::Open => self.open_rule_suggestions(),
            RuleSuggestionsMessage::Close => self.close_rule_suggestions(),
            RuleSuggestionsMessage::Reanalyse => {
                let Some(view) = self.rule_suggestions.as_mut() else {
                    return Task::none();
                };
                if view.is_busy() {
                    return Task::none();
                }
                view.begin_analysis();
                self.run_suggestion_work(SuggestionAccess::analyse)
            }
            RuleSuggestionsMessage::Loaded { generation, result } => {
                if generation != self.rule_suggestions_generation {
                    return Task::none();
                }
                let Some(view) = self.rule_suggestions.as_mut() else {
                    return Task::none();
                };
                match result {
                    Ok(rows) => view.loaded(rows),
                    Err(detail) => view.failed(detail),
                }
                self.look_up_suggestion_matches()
            }
            RuleSuggestionsMessage::Move(delta) => {
                if let Some(view) = self.rule_suggestions.as_mut() {
                    view.move_cursor(delta);
                }
                self.look_up_suggestion_matches()
            }
            RuleSuggestionsMessage::Scrolled(delta) => {
                if let Some(view) = self.rule_suggestions.as_mut() {
                    view.scroll(delta);
                }
                self.look_up_suggestion_matches()
            }
            RuleSuggestionsMessage::Select(index) => {
                if let Some(view) = self.rule_suggestions.as_mut() {
                    view.select(index);
                }
                self.look_up_suggestion_matches()
            }
            RuleSuggestionsMessage::Edit => {
                let Some(view) = self.rule_suggestions.as_ref() else {
                    return Task::none();
                };
                let Some(rule) = view.rule_to_edit() else {
                    return Task::none();
                };
                self.open_rule_form(
                    RuleForm::from_suggestion(&rule),
                    Some(HermesPage::RuleSuggestions),
                )
            }
            RuleSuggestionsMessage::Confirm => {
                let Some((id, spec)) = self
                    .rule_suggestions
                    .as_mut()
                    .and_then(RuleSuggestions::begin_confirm)
                else {
                    return Task::none();
                };
                self.run_suggestion_work(move |access| access.confirm(id, &spec))
            }
            RuleSuggestionsMessage::Discard => {
                let Some(id) = self
                    .rule_suggestions
                    .as_mut()
                    .and_then(RuleSuggestions::begin_discard)
                else {
                    return Task::none();
                };
                self.run_suggestion_work(move |access| access.discard(id))
            }
            RuleSuggestionsMessage::MatchesFound { id, result } => {
                if let (Some(view), Ok(paths)) = (self.rule_suggestions.as_mut(), result) {
                    view.matches_found(id, paths);
                }
                Task::none()
            }
        }
    }

    /// The analysis starts with the view; the list appears when it is done.
    fn update_rules(&mut self, message: RulesMessage) -> Task<Message> {
        match message {
            RulesMessage::Open => self.open_rules(),
            RulesMessage::Close => self.close_rules(),
            RulesMessage::Loaded { generation, result } => {
                if generation != self.rules_generation {
                    return Task::none();
                }
                if let Some(view) = self.rules.as_mut() {
                    match result {
                        Ok(load) => view.loaded(load),
                        Err(detail) => view.failed(detail),
                    }
                }
                self.schedule_rule_try()
            }
            RulesMessage::Move(delta) => {
                if let Some(view) = self.rules.as_mut() {
                    view.move_cursor(delta);
                }
                self.schedule_rule_try()
            }
            RulesMessage::Scrolled(delta) => {
                if let Some(view) = self.rules.as_mut() {
                    view.scroll(delta);
                }
                self.schedule_rule_try()
            }
            RulesMessage::Select(index) => {
                if let Some(view) = self.rules.as_mut() {
                    view.select(index);
                }
                Task::batch([release_focus(), self.schedule_rule_try()])
            }
            RulesMessage::ToggleTryList => {
                if let Some(view) = self.rules.as_mut() {
                    view.toggle_try_list();
                }
                Task::none()
            }
            RulesMessage::Toggle => {
                let change = self
                    .rules
                    .as_mut()
                    .and_then(|view| view.begin_toggle(view.cursor()));
                self.run_rule_change(change)
            }
            RulesMessage::ToggleAt(index) => {
                let change = self
                    .rules
                    .as_mut()
                    .and_then(|view| view.begin_toggle(index));
                self.run_rule_change(change)
            }
            RulesMessage::Reorder(delta) => {
                let change = self.rules.as_mut().and_then(|view| view.begin_move(delta));
                self.run_rule_change(change)
            }
            RulesMessage::AskDelete => {
                if let Some(view) = self.rules.as_mut() {
                    view.ask_delete();
                }
                Task::none()
            }
            RulesMessage::CancelDelete => {
                if let Some(view) = self.rules.as_mut() {
                    view.cancel_delete();
                }
                Task::none()
            }
            RulesMessage::ConfirmDelete => {
                let change = self.rules.as_mut().and_then(RulesPage::begin_delete);
                self.run_rule_change(change)
            }
            RulesMessage::Changed { generation, result } => {
                if generation != self.rules_generation {
                    return Task::none();
                }
                match result {
                    Ok(()) => self.run_rules_load(),
                    Err(detail) => {
                        if let Some(view) = self.rules.as_mut() {
                            view.failed(detail);
                        }
                        Task::none()
                    }
                }
            }
            RulesMessage::New => {
                if let Some(view) = self.rules.as_mut() {
                    view.begin_new();
                }
                Task::batch([self.focus_rule_form(), self.schedule_rule_try()])
            }
            RulesMessage::Edit => {
                if let Some(view) = self.rules.as_mut() {
                    view.begin_edit();
                }
                Task::batch([self.focus_rule_form(), self.schedule_rule_try()])
            }
            RulesMessage::Form(form_message) => self.update_rule_form(form_message),
            RulesMessage::TryElapsed(generation) => self.run_rule_try(generation),
            RulesMessage::Tried { generation, result } => {
                if let Some(form) = self.rules.as_mut().and_then(RulesPage::form_mut) {
                    form.try_answered(generation, result);
                }
                Task::none()
            }
        }
    }

    fn focus_rule_form(&self) -> Task<Message> {
        if self
            .rules
            .as_ref()
            .is_some_and(|view| view.form().is_some())
        {
            operation::focus(crate::ui::rules::NAME_FIELD_ID)
        } else {
            Task::none()
        }
    }

    /// Closes the form without saving, if there is one, and goes back to the
    /// page it was opened from.
    fn cancel_rule_form(&mut self) -> Option<Task<Message>> {
        let view = self.rules.as_mut()?;
        if !view.cancel_form() {
            return None;
        }
        Some(match view.take_return_to() {
            Some(page) => self.go_to_hermes_page(page),
            None => Task::batch([release_focus(), self.schedule_rule_try()]),
        })
    }

    /// Shows the Rules page with `form` open. From another Hermes page, or
    /// from the panels, the page loads as the sidebar would load it.
    fn open_rule_form(&mut self, form: RuleForm, return_to: Option<HermesPage>) -> Task<Message> {
        let opened = if self.open_hermes_page().is_some() {
            self.go_to_hermes_page(HermesPage::Rules)
        } else {
            self.open_rules()
        };
        let Some(view) = self.rules.as_mut() else {
            return opened;
        };
        view.open_form(form, return_to);
        Task::batch([opened, self.focus_rule_form(), self.schedule_rule_try()])
    }

    /// The form changed: its try waits for the form to rest.
    fn schedule_rule_try(&mut self) -> Task<Message> {
        let Some(form) = self.rules.as_mut().and_then(RulesPage::form_mut) else {
            return Task::none();
        };
        let generation = form.restart_try();
        Task::perform(
            async { tokio::time::sleep(TRY_DEBOUNCE).await },
            move |()| Message::Rules(RulesMessage::TryElapsed(generation)),
        )
    }

    fn run_rule_try(&mut self, generation: u64) -> Task<Message> {
        let Some(request) = self
            .rules
            .as_mut()
            .and_then(RulesPage::form_mut)
            .and_then(|form| form.try_request(generation))
        else {
            return Task::none();
        };
        let Some(access) = self.filing.as_ref().and_then(FilingModule::rules_access) else {
            if let Some(form) = self.rules.as_mut().and_then(RulesPage::form_mut) {
                form.try_answered(generation, Err(INDEX_NOT_OPEN.to_owned()));
            }
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.try_rule(&request)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::Rules(RulesMessage::Tried { generation, result })
            },
        )
    }

    fn update_rule_form(&mut self, message: RuleFormMessage) -> Task<Message> {
        let Some(view) = self.rules.as_mut() else {
            return Task::none();
        };
        match message {
            RuleFormMessage::Save => {
                let save = view.begin_save();
                self.run_rule_save(save)
            }
            RuleFormMessage::Cancel => self.cancel_rule_form().unwrap_or_else(Task::none),
            RuleFormMessage::Saved { generation, result } => {
                if generation != self.rules_generation {
                    return Task::none();
                }
                match result {
                    Ok(id) => match view.saved(id) {
                        Some(page) => self.go_to_hermes_page(page),
                        None => self.run_rules_load(),
                    },
                    Err(detail) => {
                        view.save_failed(detail);
                        Task::none()
                    }
                }
            }
            RuleFormMessage::OpenTagInput => {
                if let Some(form) = view.form_mut() {
                    form.update(RuleFormMessage::OpenTagInput);
                }
                view.start_editing();
                operation::focus(crate::ui::rules::TAG_FIELD_ID)
            }
            field_change => {
                if let Some(form) = view.form_mut() {
                    form.update(field_change);
                }
                view.start_editing();
                self.schedule_rule_try()
            }
        }
    }

    fn open_rules(&mut self) -> Task<Message> {
        if self.rules.is_some() || self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.context_menu = None;
        self.rules_generation = self.rules_generation.wrapping_add(1);
        self.rules = Some(RulesPage::new().with_kinds(Arc::clone(&self.kinds.catalog)));
        self.run_rules_load()
    }

    /// Escape backs out of the delete question, the list of the try, a form
    /// that is not listed yet and the fields, then leaves the page.
    fn close_rules(&mut self) -> Task<Message> {
        let Some(view) = self.rules.as_mut() else {
            return Task::none();
        };
        if view.cancel_delete() {
            return Task::none();
        }
        if view.is_try_list_open() {
            view.toggle_try_list();
            return Task::none();
        }
        if view.has_unlisted_form() {
            return self.cancel_rule_form().unwrap_or_else(Task::none);
        }
        if view.stop_editing() {
            return release_focus();
        }
        self.rules = None;
        release_focus()
    }

    fn rules_access(&mut self) -> Option<RulesAccess> {
        let access = self.filing.as_ref().and_then(FilingModule::rules_access);
        if access.is_none() {
            if let Some(view) = self.rules.as_mut() {
                view.failed(INDEX_NOT_OPEN.to_owned());
            }
        }
        access
    }

    fn run_rules_load(&mut self) -> Task<Message> {
        let generation = self.rules_generation;
        let Some(access) = self.rules_access() else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.load()),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::Rules(RulesMessage::Loaded { generation, result })
            },
        )
    }

    fn run_rule_save(&mut self, requested: Option<RuleSave>) -> Task<Message> {
        let Some(save) = requested else {
            return Task::none();
        };
        let generation = self.rules_generation;
        let Some(access) = self.rules_access() else {
            if let Some(form) = self.rules.as_mut().and_then(RulesPage::form_mut) {
                form.saving = false;
            }
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.save(save)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::Rules(RulesMessage::Form(RuleFormMessage::Saved {
                    generation,
                    result,
                }))
            },
        )
    }

    fn run_rule_change(&mut self, requested: Option<RuleChange>) -> Task<Message> {
        let Some(change) = requested else {
            return Task::none();
        };
        let generation = self.rules_generation;
        let Some(access) = self.rules_access() else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.apply(change)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::Rules(RulesMessage::Changed { generation, result })
            },
        )
    }

    fn open_rule_suggestions(&mut self) -> Task<Message> {
        if self.rule_suggestions.is_some() || self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.context_menu = None;
        self.rule_suggestions_generation = self.rule_suggestions_generation.wrapping_add(1);
        self.rule_suggestions = Some(RuleSuggestions::new());
        self.run_suggestion_work(SuggestionAccess::analyse)
    }

    fn close_rule_suggestions(&mut self) -> Task<Message> {
        if self.rule_suggestions.take().is_none() {
            return Task::none();
        }
        release_focus()
    }

    /// Runs `work` on a blocking thread: the index is shared with the intake,
    /// which may hold it while it hashes a large file.
    fn run_suggestion_work(
        &mut self,
        work: impl FnOnce(&SuggestionAccess) -> Result<Vec<SuggestedRule>, String> + Send + 'static,
    ) -> Task<Message> {
        let generation = self.rule_suggestions_generation;
        let Some(access) = self
            .filing
            .as_ref()
            .and_then(FilingModule::suggestion_access)
        else {
            if let Some(view) = self.rule_suggestions.as_mut() {
                view.failed(INDEX_NOT_OPEN.to_owned());
            }
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || work(&access)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::RuleSuggestions(RuleSuggestionsMessage::Loaded { generation, result })
            },
        )
    }

    /// Looks up the documents of the selected suggestion, once per selection.
    fn look_up_suggestion_matches(&mut self) -> Task<Message> {
        let Some((id, condition)) = self
            .rule_suggestions
            .as_mut()
            .and_then(RuleSuggestions::matches_wanted)
        else {
            return Task::none();
        };
        let Some(access) = self
            .filing
            .as_ref()
            .and_then(FilingModule::suggestion_access)
        else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.matching_documents(&condition)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::RuleSuggestions(RuleSuggestionsMessage::MatchesFound { id, result })
            },
        )
    }

    fn update_review_list(&mut self, message: ReviewListMessage) -> Task<Message> {
        match message {
            ReviewListMessage::Open => self.open_review_list(),
            ReviewListMessage::Close => self.close_review_list(),
            ReviewListMessage::ReadAgainWithAi => self.read_reviews_again_with_ai(),
            ReviewListMessage::Loaded { generation, result } => {
                if generation != self.review_list_generation {
                    return Task::none();
                }
                let Some(view) = self.review_list.as_mut() else {
                    return Task::none();
                };
                match result {
                    Ok(rows) => view.loaded(rows),
                    Err(detail) => view.failed(detail),
                }
                view.take_focus_request().map_or_else(Task::none, |field| {
                    operation::focus(review_list_ui::field_id(field))
                })
            }
            ReviewListMessage::Move(delta) => {
                if let Some(view) = self.review_list.as_mut() {
                    view.move_cursor(delta);
                }
                Task::none()
            }
            ReviewListMessage::Scrolled(delta) => {
                if let Some(view) = self.review_list.as_mut() {
                    view.scroll(delta);
                }
                Task::none()
            }
            ReviewListMessage::Select(index) => {
                if let Some(view) = self.review_list.as_mut() {
                    view.select(index);
                }
                Task::none()
            }
            ReviewListMessage::Edit => {
                let Some(view) = self.review_list.as_mut() else {
                    return Task::none();
                };
                view.start_edit();
                if view.is_editing() {
                    operation::focus(review_list_ui::FIRST_FIELD_ID)
                } else {
                    Task::none()
                }
            }
            ReviewListMessage::FieldChanged(field, text) => {
                if let Some(view) = self.review_list.as_mut() {
                    view.set_text(field, text);
                }
                Task::none()
            }
            ReviewListMessage::TogglePreview => {
                if let Some(view) = self.review_list.as_mut() {
                    view.toggle_preview();
                }
                Task::none()
            }
            ReviewListMessage::OpenTagInput => {
                let Some(view) = self.review_list.as_mut() else {
                    return Task::none();
                };
                view.open_tag_input();
                if view.is_tag_input_open() {
                    operation::focus(review_list_ui::TAG_INPUT_ID)
                } else {
                    Task::none()
                }
            }
            ReviewListMessage::TargetEdited(edit) => {
                let starts_own_name = edit == TargetEdit::StartOwnName;
                if let Some(view) = self.review_list.as_mut() {
                    view.edit_target(edit);
                }
                if starts_own_name {
                    operation::focus(review_list_ui::FOLDER_NAME_FIELD_ID)
                } else {
                    Task::none()
                }
            }
            ReviewListMessage::AddTag => {
                if let Some(view) = self.review_list.as_mut() {
                    view.add_tag();
                }
                Task::none()
            }
            ReviewListMessage::RemoveTag(tag) => {
                if let Some(view) = self.review_list.as_mut() {
                    view.remove_tag(&tag);
                }
                Task::none()
            }
            ReviewListMessage::FocusField { backwards } => {
                if backwards {
                    operation::focus_previous()
                } else {
                    operation::focus_next()
                }
            }
            ReviewListMessage::Confirm => {
                let Some(request) = self
                    .review_list
                    .as_mut()
                    .and_then(ReviewList::begin_confirm)
                else {
                    return Task::none();
                };
                let generation = self.review_list_generation;
                let Some(access) = self.review_access() else {
                    return Task::none();
                };
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        access.confirm(
                            request.entry,
                            request.document_id,
                            &request.fields,
                            &request.pattern,
                        )
                    }),
                    move |joined| {
                        let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                        Message::ReviewList(ReviewListMessage::Confirmed { generation, result })
                    },
                )
            }
            ReviewListMessage::Confirmed { generation, result } => {
                if generation != self.review_list_generation {
                    return Task::none();
                }
                let Some(view) = self.review_list.as_mut() else {
                    return Task::none();
                };
                match result {
                    Ok(outcome) => view.confirmed(outcome),
                    Err(detail) => {
                        view.failed(detail);
                        return Task::none();
                    }
                }
                self.run_review_load()
            }
            ReviewListMessage::CreateRule => {
                let Some(prefill) = self.review_list.as_ref().and_then(ReviewList::rule_offer)
                else {
                    return Task::none();
                };
                self.open_rule_form(
                    RuleForm::from_document(prefill, &self.kinds),
                    Some(HermesPage::Review),
                )
            }
            ReviewListMessage::ReplanOpenCases => self.start_replan(ReplanScope::OpenCases),
            ReviewListMessage::Previewed {
                generation,
                serial,
                result,
            } => {
                if generation != self.review_list_generation {
                    return Task::none();
                }
                if let Some(view) = self.review_list.as_mut() {
                    match result {
                        Ok(items) => view.previewed(serial, items),
                        Err(detail) => view.failed(detail),
                    }
                }
                Task::none()
            }
            ReviewListMessage::ReplanConfirm => self.confirm_replan(),
            ReviewListMessage::ReplanCancel => {
                if let Some(view) = self.review_list.as_mut() {
                    view.cancel_replan();
                }
                Task::none()
            }
            ReviewListMessage::PreviewLoaded {
                generation,
                serial,
                content,
            } => {
                if generation == self.review_list_generation {
                    if let Some(view) = self.review_list.as_mut() {
                        view.preview_loaded(serial, content);
                    }
                }
                Task::none()
            }
        }
    }

    /// Makes the preview of the document under the cursor, on a blocking
    /// thread, when the cursor has moved to another one.
    fn request_review_preview(&mut self) -> Task<Message> {
        let generation = self.review_list_generation;
        let Some(request) = self
            .review_list
            .as_mut()
            .and_then(ReviewList::preview_request)
        else {
            return Task::none();
        };
        let serial = request.serial;
        Task::perform(
            document_preview::load_off_thread(request.path, request.passages),
            move |content| {
                Message::ReviewList(ReviewListMessage::PreviewLoaded {
                    generation,
                    serial,
                    content,
                })
            },
        )
    }

    /// Opens the review page if it is not up and plans the documents of
    /// `scope` again there, on a blocking thread. It only reads; the user
    /// sees the result before anything is filed.
    fn start_replan(&mut self, scope: ReplanScope) -> Task<Message> {
        let Some(access) = self.filing.as_ref().and_then(FilingModule::replan_access) else {
            self.set_status_error(INDEX_NOT_OPEN);
            return Task::none();
        };
        let opened = self.open_review_list();
        let generation = self.review_list_generation;
        let Some(serial) = self
            .review_list
            .as_mut()
            .and_then(|view| view.begin_replan(scope.clone()))
        else {
            return opened;
        };
        let preview = Task::perform(
            tokio::task::spawn_blocking(move || access.preview(&scope)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::ReviewList(ReviewListMessage::Previewed {
                    generation,
                    serial,
                    result,
                })
            },
        );
        Task::batch([opened, preview])
    }

    /// Plans the documents below `folder` again, if it lies in an inbox
    /// location. Anywhere else nothing happens but the message.
    fn reprocess_folder(&mut self, folder: PathBuf) -> Task<Message> {
        let inbox_roots: Vec<PathBuf> = self
            .filing_config
            .locations
            .iter()
            .filter(|location| location.mode == LocationMode::Inbox)
            .map(|location| location.path.clone())
            .collect();
        if !crate::replan_work::lies_in_inbox(&folder, &inbox_roots) {
            let text = self.lang.text(Msg::StatusReprocessOutsideInbox).to_owned();
            return self.show_notice(text);
        }
        self.start_replan(ReplanScope::Folder(folder))
    }

    /// The user confirmed the preview: the previewed documents are filed by
    /// one job, as soon as the queue is free.
    fn confirm_replan(&mut self) -> Task<Message> {
        if self.pending_refile.is_some() {
            return Task::none();
        }
        let Some((scope, items)) = self
            .review_list
            .as_mut()
            .and_then(ReviewList::confirm_replan)
        else {
            return Task::none();
        };
        let folder = match scope {
            ReplanScope::Folder(folder) => folder,
            ReplanScope::OpenCases => PathBuf::new(),
        };
        self.pending_refile = Some((folder, items));
        if self.jobs.is_busy() {
            let text = self.lang.text(Msg::StatusRefileWaiting).to_owned();
            return self.show_notice(text);
        }
        self.run_refile()
    }

    /// Starts the confirmed refiling if no other job runs; asked for again on
    /// the next tick otherwise, so it never queues behind another job.
    fn run_refile(&mut self) -> Task<Message> {
        if self.jobs.is_busy() {
            return Task::none();
        }
        let Some((folder, items)) = self.pending_refile.take() else {
            return Task::none();
        };
        let Some(access) = self.filing.as_ref().and_then(FilingModule::replan_access) else {
            self.set_status_error(INDEX_NOT_OPEN);
            return Task::none();
        };
        let progress_tx = self.progress_sender();
        self.jobs.enqueue(jobs::Job {
            kind: jobs::JobKind::File,
            path: folder,
            total: Some(items.iter().filter(|item| item.would_be_filed()).count()),
        });
        self.jobs
            .start_next(|_| {
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        let mut progress = fs::transfer::Reporting::new(&progress_tx);
                        access.file_previewed(&items, &mut progress)
                    }),
                    |joined| {
                        Message::DocumentsRefiled(
                            joined.unwrap_or_else(|join| Err(join.to_string())),
                        )
                    },
                )
            })
            .unwrap_or_else(Task::none)
    }

    fn documents_refiled(&mut self, result: Result<ReplanSummary, String>) -> Task<Message> {
        self.jobs.finish();
        self.job_progress = None;
        let reload = if self.review_list.is_some() {
            self.run_review_load()
        } else {
            Task::none()
        };
        let notice = match result {
            Ok(summary) => {
                let text = fill_template(
                    self.lang.text(Msg::StatusRefileDone),
                    &[
                        ("{filed}", &summary.filed.to_string()),
                        ("{reviewed}", &summary.reviewed.to_string()),
                        ("{changed}", &summary.changed.to_string()),
                        ("{requeued}", &summary.requeued.to_string()),
                    ],
                );
                self.show_notice(text)
            }
            Err(detail) => {
                self.set_status_error(&detail);
                Task::none()
            }
        };
        Task::batch([notice, reload])
    }

    fn review_access(&mut self) -> Option<ReviewAccess> {
        let access = self.filing.as_ref().and_then(FilingModule::review_access);
        if access.is_none() {
            if let Some(view) = self.review_list.as_mut() {
                view.failed(INDEX_NOT_OPEN.to_owned());
            }
        }
        access
    }

    fn open_review_list(&mut self) -> Task<Message> {
        if self.review_list.is_some() || self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.context_menu = None;
        self.review_list_generation = self.review_list_generation.wrapping_add(1);
        self.review_list = Some(
            ReviewList::new()
                .with_default_pattern(self.filing_config.default_pattern.clone())
                .with_kinds(self.kinds.clone()),
        );
        let counts = if self.filing_status.hermes_counts().is_none() {
            self.request_hermes_counts()
        } else {
            Task::none()
        };
        Task::batch([self.run_review_load(), counts])
    }

    /// Hands every open review to Hermes again, now that the AI can read it.
    /// Only on the click: nothing is re-read behind the user's back.
    fn read_reviews_again_with_ai(&mut self) -> Task<Message> {
        let Some(paths) = self.review_list.as_ref().map(|view| {
            view.rows()
                .iter()
                .map(|row| row.path.clone())
                .collect::<Vec<_>>()
        }) else {
            return Task::none();
        };
        self.read_paths_again(paths)
    }

    fn read_paths_again(&mut self, paths: Vec<PathBuf>) -> Task<Message> {
        let since = self
            .live_pipeline()
            .map_or(0, |runner| runner.snapshot().changed_sequence);
        let queued: Vec<PathBuf> = paths
            .into_iter()
            .filter(|path| {
                self.live_pipeline()
                    .is_some_and(|runner| runner.process_again(path))
            })
            .collect();
        if queued.is_empty() {
            return Task::none();
        }
        for path in &queued {
            self.invalidate_hermes_path(path);
            self.reading_again.ask(path.clone(), since);
        }
        let text = if queued.len() == 1 {
            self.lang.text(Msg::StatusReviewReadAgain).to_owned()
        } else {
            fill_template(
                self.lang.text(Msg::StatusReviewsReadAgain),
                &[("{count}", &queued.len().to_string())],
            )
        };
        self.show_notice(text)
    }

    fn review_field_guide(&self) -> review_list_ui::FieldGuide {
        review_list_ui::FieldGuide {
            confirmed_rules: self
                .filing_status
                .hermes_counts()
                .map(|counts| counts.confirmed_rules),
            ai_is_ready: !matches!(
                self.filing_status.ai(),
                crate::filing::AiStatus::Off
                    | crate::filing::AiStatus::NotDownloaded
                    | crate::filing::AiStatus::Failed(_)
            ),
        }
    }

    /// Escape leaves the form first, the list second.
    fn close_review_list(&mut self) -> Task<Message> {
        match self.review_list.as_mut() {
            Some(view) if view.is_editing() => {
                view.cancel_edit();
                release_focus()
            }
            Some(view) if view.replan().is_some() => {
                view.cancel_replan();
                Task::none()
            }
            Some(_) => {
                self.review_list = None;
                release_focus()
            }
            None => Task::none(),
        }
    }

    /// Loads on a blocking thread: the load plans every open entry again, and
    /// the index is shared with the intake.
    fn run_review_load(&mut self) -> Task<Message> {
        let generation = self.review_list_generation;
        let Some(access) = self.review_access() else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.load()),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::ReviewList(ReviewListMessage::Loaded { generation, result })
            },
        )
    }

    fn update_saved_queries(&mut self, message: SavedQueriesMessage) -> Task<Message> {
        match message {
            SavedQueriesMessage::Open => self.open_saved_queries(),
            SavedQueriesMessage::Close => self.close_saved_queries(),
            SavedQueriesMessage::Loaded { generation, result } => {
                if generation != self.saved_queries_generation {
                    return Task::none();
                }
                let Some(view) = self.saved_queries.as_mut() else {
                    return Task::none();
                };
                match result {
                    Ok(rows) => {
                        let prefilled = view.is_prefilled();
                        view.loaded(rows);
                        let focus = if prefilled {
                            operation::focus(saved_queries_ui::NAME_ID)
                        } else {
                            Task::none()
                        };
                        Task::batch([focus, self.run_selected_query(), self.run_query_counts()])
                    }
                    Err(detail) => {
                        view.failed(detail);
                        Task::none()
                    }
                }
            }
            SavedQueriesMessage::Counted { generation, result } => {
                if generation == self.saved_queries_generation {
                    if let Some(view) = self.saved_queries.as_mut() {
                        match result {
                            Ok(counts) => view.counted(counts),
                            Err(detail) => view.failed(detail),
                        }
                    }
                }
                Task::none()
            }
            SavedQueriesMessage::Move(delta) => {
                let Some(view) = self.saved_queries.as_mut() else {
                    return Task::none();
                };
                let before = view.cursor();
                view.move_cursor(delta);
                if view.cursor() == before {
                    return Task::none();
                }
                self.run_selected_query()
            }
            SavedQueriesMessage::Scrolled(delta) => {
                let Some(view) = self.saved_queries.as_mut() else {
                    return Task::none();
                };
                let before = view.cursor();
                view.scroll(delta);
                if view.cursor() == before {
                    return Task::none();
                }
                self.run_selected_query()
            }
            SavedQueriesMessage::Select(index) => {
                let Some(view) = self.saved_queries.as_mut() else {
                    return Task::none();
                };
                let before = view.cursor();
                view.select(index);
                if view.cursor() == before {
                    return Task::none();
                }
                self.run_selected_query()
            }
            SavedQueriesMessage::NewSearch(spec) => self.open_search_for(&spec, None),
            SavedQueriesMessage::EditInSearch => {
                let Some(view) = self.saved_queries.as_ref() else {
                    return Task::none();
                };
                let Some(spec) = view.selected_spec().cloned() else {
                    return Task::none();
                };
                let report = view.selected().map(|query| query.id);
                self.open_search_for(&spec, report)
            }
            SavedQueriesMessage::OpenInSearch => {
                let Some(spec) = self
                    .saved_queries
                    .as_ref()
                    .and_then(|view| view.selected_spec().cloned())
                else {
                    return Task::none();
                };
                self.open_search_for(&spec, None)
            }
            SavedQueriesMessage::NameChanged(name) => {
                if let Some(view) = self.saved_queries.as_mut() {
                    view.set_name(name);
                }
                Task::none()
            }
            SavedQueriesMessage::Confirm => {
                let Some(view) = self.saved_queries.as_ref() else {
                    return Task::none();
                };
                let next = if view.export_step().is_some() {
                    SavedQueriesMessage::Export
                } else if view.is_confirming_delete() {
                    SavedQueriesMessage::ConfirmDelete
                } else if view.unsaved().is_some() || view.name_is_changed() {
                    SavedQueriesMessage::Save
                } else {
                    SavedQueriesMessage::StartExport
                };
                self.update_saved_queries(next)
            }
            SavedQueriesMessage::Save => {
                let Some(request) = self
                    .saved_queries
                    .as_mut()
                    .and_then(SavedQueries::begin_save)
                else {
                    return Task::none();
                };
                let generation = self.saved_queries_generation;
                let Some(access) = self.query_access() else {
                    return Task::none();
                };
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        access.save(request.id, &request.name, &request.spec)
                    }),
                    move |joined| {
                        let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                        Message::SavedQueries(SavedQueriesMessage::Saved { generation, result })
                    },
                )
            }
            SavedQueriesMessage::Saved { generation, result } => {
                if generation != self.saved_queries_generation {
                    return Task::none();
                }
                let Some(view) = self.saved_queries.as_mut() else {
                    return Task::none();
                };
                match result {
                    Ok(id) => view.saved(id),
                    Err(detail) => {
                        view.failed(detail);
                        return Task::none();
                    }
                }
                self.run_query_load()
            }
            SavedQueriesMessage::AskDelete => {
                if let Some(view) = self.saved_queries.as_mut() {
                    view.ask_delete();
                }
                Task::none()
            }
            SavedQueriesMessage::CancelStep => {
                if let Some(view) = self.saved_queries.as_mut() {
                    view.cancel_step();
                }
                Task::none()
            }
            SavedQueriesMessage::ConfirmDelete => {
                let Some(id) = self
                    .saved_queries
                    .as_mut()
                    .and_then(SavedQueries::begin_delete)
                else {
                    return Task::none();
                };
                let generation = self.saved_queries_generation;
                let Some(access) = self.query_access() else {
                    return Task::none();
                };
                Task::perform(
                    tokio::task::spawn_blocking(move || access.delete(id).map(|_| id)),
                    move |joined| {
                        let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                        Message::SavedQueries(SavedQueriesMessage::Deleted { generation, result })
                    },
                )
            }
            SavedQueriesMessage::Deleted { generation, result } => {
                if generation != self.saved_queries_generation {
                    return Task::none();
                }
                let Some(view) = self.saved_queries.as_mut() else {
                    return Task::none();
                };
                match result {
                    Ok(id) => view.deleted(id),
                    Err(detail) => {
                        view.failed(detail);
                        return Task::none();
                    }
                }
                self.run_query_load()
            }
            SavedQueriesMessage::Ran {
                generation,
                serial,
                result,
            } => {
                if generation == self.saved_queries_generation {
                    if let Some(view) = self.saved_queries.as_mut() {
                        match result {
                            Ok(hits) => view.ran(serial, hits),
                            Err(detail) => view.failed(detail),
                        }
                    }
                }
                Task::none()
            }
            SavedQueriesMessage::ToggleMissing => {
                if let Some(view) = self.saved_queries.as_mut() {
                    view.toggle_missing();
                }
                Task::none()
            }
            SavedQueriesMessage::StartExport => {
                // The other panel's folder is where files are usually wanted.
                let folder = self.panel(self.panels.active.other()).path.clone();
                if let Some(view) = self.saved_queries.as_mut() {
                    view.start_export(folder);
                }
                Task::none()
            }
            SavedQueriesMessage::PickFolder => {
                let start_in = self
                    .saved_queries
                    .as_ref()
                    .and_then(|view| view.export_step())
                    .map_or_else(
                        || self.active_panel().path.clone(),
                        |step| step.folder.clone(),
                    );
                (self.pick_folder)(&start_in)
                    .map(|folder| Message::SavedQueries(SavedQueriesMessage::FolderPicked(folder)))
            }
            SavedQueriesMessage::FolderPicked(folder) => {
                if let (Some(view), Some(picked)) = (self.saved_queries.as_mut(), folder) {
                    view.set_export_folder(&picked);
                }
                Task::none()
            }
            SavedQueriesMessage::Export => {
                let Some(request) = self
                    .saved_queries
                    .as_mut()
                    .and_then(SavedQueries::begin_export)
                else {
                    return Task::none();
                };
                let generation = self.saved_queries_generation;
                let now = chrono::Local::now().naive_local();
                Task::perform(
                    tokio::task::spawn_blocking(move || {
                        query_work::export(&request.hits, &request.folder, now)
                    }),
                    move |joined| {
                        let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                        Message::SavedQueries(SavedQueriesMessage::Exported { generation, result })
                    },
                )
            }
            SavedQueriesMessage::Exported { generation, result } => {
                if generation == self.saved_queries_generation {
                    if let Some(view) = self.saved_queries.as_mut() {
                        match result {
                            Ok(summary) => view.export_done(summary),
                            Err(detail) => view.failed(detail),
                        }
                    }
                }
                Task::none()
            }
        }
    }

    /// Asks the index for the hits of the selected report.
    fn run_selected_query(&mut self) -> Task<Message> {
        let Some((serial, spec)) = self
            .saved_queries
            .as_mut()
            .and_then(SavedQueries::begin_run)
        else {
            return Task::none();
        };
        let generation = self.saved_queries_generation;
        let Some(access) = self.query_access() else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.run(&spec)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::SavedQueries(SavedQueriesMessage::Ran {
                    generation,
                    serial,
                    result,
                })
            },
        )
    }

    /// Counts the hits of every report for the list.
    fn run_query_counts(&mut self) -> Task<Message> {
        let Some(rows) = self.saved_queries.as_ref().map(|view| view.rows().to_vec()) else {
            return Task::none();
        };
        if rows.is_empty() {
            return Task::none();
        }
        let generation = self.saved_queries_generation;
        let Some(access) = self.query_access() else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.counts(&rows)),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::SavedQueries(SavedQueriesMessage::Counted { generation, result })
            },
        )
    }

    fn query_access(&mut self) -> Option<QueryAccess> {
        let access = self.filing.as_ref().and_then(FilingModule::query_access);
        if access.is_none() {
            if let Some(view) = self.saved_queries.as_mut() {
                view.failed(INDEX_NOT_OPEN.to_owned());
            }
        }
        access
    }

    fn update_tags(&mut self, message: TagsMessage) -> Task<Message> {
        match message {
            TagsMessage::Close => self.close_tags(),
            TagsMessage::Done { generation, result } => {
                if generation != self.tags_generation {
                    return Task::none();
                }
                match result {
                    Ok(loaded) => {
                        self.tag_exceptions = loaded.exceptions.clone();
                        if let Some(page) = self.tags.as_mut() {
                            page.loaded(loaded);
                        }
                    }
                    Err(failure) => {
                        if let Some(page) = self.tags.as_mut() {
                            page.failed(failure);
                        }
                    }
                }
                Task::none()
            }
            TagsMessage::ExceptionsRead(result) => {
                if let Ok(exceptions) = result {
                    self.tag_exceptions = exceptions;
                }
                Task::none()
            }
            TagsMessage::Scrolled(delta) => {
                if let Some(page) = self.tags.as_mut() {
                    page.scroll(delta);
                }
                Task::none()
            }
            TagsMessage::Move(delta) => {
                if let Some(page) = self.tags.as_mut() {
                    page.move_cursor(delta);
                }
                Task::none()
            }
            TagsMessage::Select(index) => {
                if let Some(page) = self.tags.as_mut() {
                    page.select(index);
                }
                Task::none()
            }
            TagsMessage::ToggleSelected => {
                let next = match self.tags.as_ref().and_then(TagsPage::selected) {
                    Some(TagRow::Group(group)) => TagsMessage::ToggleGroup(group),
                    Some(TagRow::Tag { group, tag, .. }) => TagsMessage::ToggleTag { group, tag },
                    Some(TagRow::More { group, .. }) => TagsMessage::Unfold(group),
                    None => return Task::none(),
                };
                self.update_tags(next)
            }
            TagsMessage::ToggleOpen(group) => {
                if let Some(page) = self.tags.as_mut() {
                    page.toggle_open(group);
                }
                Task::none()
            }
            TagsMessage::Unfold(group) => {
                if let Some(page) = self.tags.as_mut() {
                    page.unfold(group);
                }
                Task::none()
            }
            TagsMessage::ToggleTag { group, tag } => {
                let Some(page) = self.tags.as_mut().filter(|page| !page.is_busy()) else {
                    return Task::none();
                };
                let shown = page.exception_after_toggle(&self.file_list_tags, group, &tag);
                page.begin_change();
                self.run_tags_work(move |access| access.set_shown(&tag, shown))
            }
            TagsMessage::ToggleGroup(group) => self.toggle_tag_group(group),
            TagsMessage::SearchChanged(text) => {
                if let Some(page) = self.tags.as_mut() {
                    page.set_search(text);
                }
                Task::none()
            }
            TagsMessage::StartRename(tag) => {
                let Some(page) = self.tags.as_mut() else {
                    return Task::none();
                };
                page.start_rename(tag);
                if page.is_editing() {
                    operation::focus(tags_ui::RENAME_ID)
                } else {
                    Task::none()
                }
            }
            TagsMessage::RenameChanged(text) => {
                if let Some(page) = self.tags.as_mut() {
                    page.set_rename_text(text);
                }
                Task::none()
            }
            TagsMessage::ConfirmRename => {
                let Some((old_name, new_name)) =
                    self.tags.as_mut().and_then(TagsPage::begin_rename)
                else {
                    return Task::none();
                };
                self.run_tags_work(move |access| access.rename(&old_name, &new_name))
            }
            TagsMessage::AskDelete(tag) => {
                if let Some(page) = self.tags.as_mut() {
                    page.ask_delete(tag);
                }
                Task::none()
            }
            TagsMessage::ConfirmDelete => {
                let Some(page) = self.tags.as_mut() else {
                    return Task::none();
                };
                if page.step().is_none() {
                    return self.update_tags(TagsMessage::ToggleSelected);
                }
                let Some(name) = page.begin_delete() else {
                    return Task::none();
                };
                self.run_tags_work(move |access| access.delete(&name))
            }
        }
    }

    /// The default of the group follows the tick; the tags of the group that
    /// differed from it follow the group again.
    fn toggle_tag_group(&mut self, group: TagGroup) -> Task<Message> {
        let Some(page) = self.tags.as_mut().filter(|page| !page.is_busy()) else {
            return Task::none();
        };
        let on = page.group_will_be_on(&self.file_list_tags, group);
        let exceptional = page.exceptional_tags(group);
        let switched = self.file_list_tags.with_group(group, on);
        let write = self.write_setting(SettingChange::FileListTags(switched));
        if exceptional.is_empty() {
            return write;
        }
        if let Some(open) = self.tags.as_mut() {
            open.begin_change();
        }
        let clear = self.run_tags_work(move |access| access.clear_exceptions(&exceptional));
        Task::batch([write, clear])
    }

    /// The tags page, from the settings or the command list: in place of the
    /// page of the Ablage tab that is up, if any.
    fn show_tags_page(&mut self) -> Task<Message> {
        let left = self.leave_settings_page(Self::close_settings);
        let opened = if self.open_hermes_page().is_some() {
            self.show_hermes_page(HermesPage::Tags)
        } else {
            self.open_tags()
        };
        Task::batch([left, opened])
    }

    fn open_tags(&mut self) -> Task<Message> {
        if self.tags.is_some() || self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.context_menu = None;
        self.tags_generation = self.tags_generation.wrapping_add(1);
        self.tags = Some(TagsPage::new(self.kinds.clone()));
        self.run_tags_work(TagsAccess::load)
    }

    /// Escape backs out of the step that is up first, then leaves the page.
    fn close_tags(&mut self) -> Task<Message> {
        let Some(page) = self.tags.as_mut() else {
            return Task::none();
        };
        if page.cancel_step() {
            return Task::none();
        }
        self.tags = None;
        release_focus()
    }

    fn run_tags_work(
        &mut self,
        work: impl FnOnce(&TagsAccess) -> Result<TagsLoaded, TagsFailure> + Send + 'static,
    ) -> Task<Message> {
        let generation = self.tags_generation;
        let Some(access) = self.filing.as_ref().and_then(FilingModule::tags_access) else {
            if let Some(page) = self.tags.as_mut() {
                page.failed(TagsFailure::Other(INDEX_NOT_OPEN.to_owned()));
            }
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || work(&access)),
            move |joined| {
                let result =
                    joined.unwrap_or_else(|join| Err(TagsFailure::Other(join.to_string())));
                Message::Tags(TagsMessage::Done { generation, result })
            },
        )
    }

    fn open_saved_queries(&mut self) -> Task<Message> {
        if self.saved_queries.is_some() || self.blocking_overlay_is_open() {
            return Task::none();
        }
        self.context_menu = None;
        self.saved_queries_generation = self.saved_queries_generation.wrapping_add(1);
        self.saved_queries = Some(
            SavedQueries::new(chrono::Datelike::year(&chrono::Local::now()))
                .with_kinds(self.kinds.clone()),
        );
        self.run_query_load()
    }

    /// Escape backs out of the step that is up first, then leaves the page.
    fn close_saved_queries(&mut self) -> Task<Message> {
        let Some(view) = self.saved_queries.as_mut() else {
            return Task::none();
        };
        if view.cancel_step() {
            return Task::none();
        }
        self.saved_queries = None;
        release_focus()
    }

    fn run_query_load(&mut self) -> Task<Message> {
        let generation = self.saved_queries_generation;
        let Some(access) = self.query_access() else {
            return Task::none();
        };
        Task::perform(
            tokio::task::spawn_blocking(move || access.load()),
            move |joined| {
                let result = joined.unwrap_or_else(|join| Err(join.to_string()));
                Message::SavedQueries(SavedQueriesMessage::Loaded { generation, result })
            },
        )
    }

    /// The inbox, the filing location and the archive of the config, by role.
    fn overview_folders(&self) -> hermes_overview_ui::Folders<'_> {
        let find = |mode: LocationMode, is_target: bool| {
            self.filing_config
                .locations
                .iter()
                .find(|location| {
                    location.mode == mode
                        && (mode == LocationMode::Inbox || location.is_target == is_target)
                })
                .map(|location| location.path.as_path())
        };
        hermes_overview_ui::Folders {
            inbox: find(LocationMode::Inbox, false),
            filing_location: find(LocationMode::Archive, true),
            archive: find(LocationMode::Archive, false),
        }
    }

    fn overview_facts(&self, ocr_models_present: bool) -> OverviewFacts {
        let module = self.filing.as_ref();
        let module_state = if self.hermes_is_restarting() {
            ModuleState::Starting
        } else {
            module.map_or(ModuleState::Off, |running| match running.phase() {
                Phase::Dismissed if running.key_problem().is_some() => ModuleState::KeyMissing,
                phase => ModuleState::of(phase),
            })
        };
        let at_rest = !self.jobs.is_busy() && !self.hermes_is_restarting();
        let failure = match module.map(FilingModule::phase) {
            Some(Phase::Failed(reason)) => Some(reason.clone()),
            _ => None,
        };
        OverviewFacts {
            module: module_state,
            failure,
            has_locations: !self.filing_config.locations.is_empty(),
            counts: self.filing_status.hermes_counts().copied(),
            ai_on: self.filing_config.ai != crate::config::AiSetting::Off,
            ai_status: module.map(FilingModule::ai_status).unwrap_or_default(),
            ai_download: self
                .ai_model
                .as_ref()
                .filter(|card| card.is_downloading())
                .and_then(AiModelCard::progress),
            ocr: OcrFacts::of(crate::ocr_models::system_reads_scans(), ocr_models_present),
            protection: Protection::of(
                module_state,
                module.and_then(FilingModule::index_encryption),
            ),
            key_problem: module.and_then(FilingModule::key_problem),
            can_encrypt: at_rest && module.is_some_and(FilingModule::can_encrypt),
            can_start_over: at_rest && module.is_some_and(FilingModule::can_start_over),
            protection_note: module.and_then(|running| running.protection_note().cloned()),
        }
    }

    fn hermes_overview_view(&self) -> Option<Element<'_, Message>> {
        let state = self.hermes_overview.as_ref()?;
        let snapshot = self.filing_status.snapshot();
        let page = hermes_overview_ui::OverviewView {
            facts: self.overview_facts(state.ocr_models_present()),
            state,
            folders: self.overview_folders(),
            home: &self.home,
            runner: snapshot.state,
            in_progress: snapshot.open_files(),
            badges: self.hermes_badges(),
            lang: self.lang,
        };
        Some(hermes_overview_ui::view(&page, &self.palette))
    }

